// 简体中文 stories: I18N["zh-CN"].stories["<civ id>:<activity>"] = "…" (same keys as cultures/stories/ancient-americas.js).
Object.assign(I18N["zh-CN"].stories, {
  "egyptians:hunt": "在三角洲的纸莎草沼泽里，一位贵族站在轻巧的芦苇小舟上，高举投掷棒，妻女伴在身旁，一只训练有素的猫正扑向飞鸟。约公元前1350年，内巴蒙（𓎟𓇋𓏠𓈖）让人把这一幕画进了他在底比斯的墓中。在芦苇丛中猎捕水鸟与河马不只是消遣：那是秩序战胜混沌，是亡者希望永远保有的欢乐。",
  "egyptians:battle": "公元前1274年，卡迭石。年轻而过于自信的拉美西斯二世（𓇳𓄟𓋴𓇓）在大军之前扎营，穆瓦塔利的赫梯战车突然越过奥龙特斯河，冲散了拉神（𓂋𓂝𓇳𓀭）军团。法老召集亲卫，一次又一次冲锋，直到普塔（𓊪𓏏𓎛）军团赶到。双方都未真正取胜，但拉美西斯把自己孤身奋战的场面刻在了从阿布辛贝（أبو سمبل）到卡纳克（الكرنك）的神庙墙上，成了自己史诗中的英雄。",
  "egyptians:gather": "洪水退去后，凯麦特（𓆎𓅓𓏏𓊖）的黑土湿润松软。农夫撒下二粒小麦和大麦，赶着羊群踏过田地，把种子踩进土里。到了春天，书吏带着丈量绳前来清点收成、核定赋税。收割者挥动燧石镰刀，唱起劳动歌，第一捆麦子献给粮仓的眼镜蛇女神瑞内努特（𓂋𓈖𓈖𓅱𓏏𓏏𓆗）。",
  "egyptians:ritual": "在底比斯（𓌀𓏏𓊖）的「河谷美丽节」上，祭司们把阿蒙（𓇋𓏠𓈖）的圣舟扛在肩上渡过河去。人们把问题写在陶片上，一个「是」，一个「否」，等待神舟倾向其中一个答案。我该信任这个人吗？我的儿子会康复吗？阿蒙的神谕裁决土地纠纷、任命官员；圣舟移动前的那片寂静，是最神圣的时刻。",
  "egyptians:rain": "埃及几乎从不下雨，人人等待的是河水。初夏时节，天狼星索普德特（𓋴𓊪𓂧𓏏𓇼）在黎明前与太阳一同升起，象岛水位计旁的祭司每天察看石阶上的刻度。水位能否涨到十六肘尺，足以带来丰年？太少意味着饥荒，太多则是灾祸。整个国家都屏息等待着哈皮（𓎛𓂝𓊪𓈗）。",
  "egyptians:flood": "在这里，泛滥不是灾难，而是一年中最大的恩赐。丰腴的蓝绿色神祇哈皮（𓎛𓂝𓊪𓈗）头戴纸莎草冠，把河水倾注到田野上，留下黑色的淤泥，凯麦特（𓆎𓅓𓏏𓊖）之名正由此而来。村庄变成孤岛，农活停歇，人们驾船、宴饮，或为法老的营建工程出力。尼罗河颂歌唱道：当他升起，大地欢腾，人人腹中饱足。",
  "egyptians:wind": "南方沙漠吹来了喀新风，这股炎热的春风一刮就是好几天。黄沙遮蔽了底比斯（𓌀𓏏𓊖）上空的太阳，刺痛渔夫的眼睛，掩埋了田地的边缘。埃及人把红色沙漠及其风暴与混乱与力量之神塞特（𓃩）联系在一起；而每天夜里，也正是塞特站在拉（𓂋𓂝𓇳𓀭）的太阳船船头，用长矛刺向巨蛇阿佩普（𓂝𓄿𓊪𓊪𓆙）。",
  "egyptians:fire": "想象：在王陵工匠村代尔麦地那（دير المدينة）一个拥挤的街区，一盏油灯翻倒了。泥砖墙挺住了，但棕榈叶屋顶和亚麻布烧得飞快，邻居们在狭窄的巷子里一个接一个传递水罐。事后，王陵书吏把损失记录在一片石灰岩上，妇女们则祈求塔沃里特（𓏏𓄿𓅨𓂋𓏏）和贝斯（𓃀𓋴）守护灶火。",
  "egyptians:thunder": "雷声在埃及十分罕见，它属于塞特（𓃩），是他在天空中的咆哮。约公元前1550年，雅赫摩斯国王（𓇹𓄟𓋴）在卡纳克（الكرنك）立下「风暴碑」，碑文记载一场可怕的风暴席卷底比斯（𓌀𓏏𓊖）：天昏地暗，大雨倾盆，声响盖过人群的喧嚣，坟墓坍塌，尸体被冲出。国王修复了神庙与国土，以此表明法老能让世界重归秩序。",
  "egyptians:birth": "一位母亲蹲在两块绘有梅斯赫奈特（𓄟𓋴𓐍𓈖𓏏）面容的分娩砖上，这位女神还将决定孩子的命运。接生婆念诵咒语，用一根刻着塔沃里特（𓏏𓄿𓅨𓂋𓏏）和贝斯（𓃀𓋴）的象牙魔杖绕房间划一圈，把恶魔挡在外面。许多孩子活不过第一年。可谁知道这个孩子将来会成为什么人呢：书吏、祭司，或者有朝一日成为像哈特谢普苏特（𓄂𓏏𓈙𓊪𓋴𓅱𓏏）那样的法老。",
  "egyptians:death": "死后七十天，书吏阿尼（𓇋𓈖𓇋）的木乃伊被竖立在墓门口。一位戴豺狼面具的祭司扶着它，另一位祭司用锛子触碰它的嘴，这就是「开口仪式」，好让死者能重新进食和说话。职业哭丧人往头上撒土，放声哀嚎。在「双真理大厅」里，他的心脏将与玛阿特（𓌳𓄿𓏏𓆄）的羽毛一同称量。",
  "babylonians:hunt": "想象：巴比伦猎人蹚进南方沼泽的芦苇丛，在船与船之间张开大网，捕捉被猎犬惊起的水鸟和野猪。那时狮子仍在河流之乡出没，猎狮是国王的职责，证明他在守护自己的羊群。一位猎人带着野猪归来，先把一部分交给神庙，再把余下的拿到巴比伦（𒆍𒀭𒊏𒆠）的集市上出售。",
  "babylonians:battle": "约公元前1763年，巴比伦（𒆍𒀭𒊏𒆠）的汉谟拉比（𒄩𒄠𒈬𒊏𒁉）筑坝拦住底格里斯河的河水，随后开闸放水，冲垮了拉尔萨（𒌓𒀕𒆠）的城墙，那里的老国王瑞姆辛（𒊑𒅎𒀭𒂗𒍪）已统治了六十年。埃什南纳、马里（𒈠𒊑𒆠）和拉尔萨相继陷落。一个小小的城邦成了帝国；在一块玄武岩石碑上，汉谟拉比不只把自己描绘成征服者，更是为大地带来公正的牧者。",
  "babylonians:gather": "沿着运河，椰枣树成排而立；到了收获季节，男人们用绳索攀上树干，砍下沉甸甸的果串。汉谟拉比（𒄩𒄠𒈬𒊏𒁉）的法典为与园主分享椰枣的园丁定下了规矩。大麦堆满了马尔杜克（𒀭𒀫𒌓）神庙的粮仓，书吏把账目压印在湿润的泥板上。好年景意味着城中家家户户都有面包和啤酒。",
  "babylonians:ritual": "一位巴鲁占卜师宰杀一只完美无瑕的羊羔，在太阳神沙玛什（𒀭𒌓）和风暴神阿达德（𒀭𒅎）面前将它剖开。他研究羊肝上的纹路与褶皱，与泥塑肝脏模型和长长的预兆泥板逐一比对。若此征兆出现，国王必将得胜。国王出征、营建、婚娶，无不先行问卜。羊羔的肝脏，就是众神书写的泥板。",
  "babylonians:rain": "美索不达米亚南部雨水稀少，生活依赖幼发拉底河供水的运河。农夫们看着河水随远山融雪而上涨，天文学家则在塔庙上观测星辰，每夜写下他们的《天文日志》：月亮、行星、天气、大麦的价格。为了等待变化，他们记录天空长达六个多世纪。",
  "babylonians:flood": "在《吉尔伽美什史诗》（𒀭𒄑𒉋𒂵𒎌）的第十一块泥板上，乌特纳皮什提姆讲述了众神如何决定淹死人类。埃阿（𒀭𒂍𒀀）隔着一道芦苇墙低声警告：拆掉你的房子，造一艘船。风暴肆虐了六天七夜，连众神都像狗一样瑟缩。风暴平息后，他放出一只鸽子、一只燕子，最后放出一只乌鸦，乌鸦再也没有回来。",
  "babylonians:wind": "在巴比伦新年庆典上诵读的创世史诗《埃努玛·埃利什》（𒂊𒉡𒈠𒂊𒇺）中，马尔杜克（𒀭𒀫𒌓）带着七股风迎战海怪提亚马特：恶风、旋风、飓风。当她张口要吞下他时，他把风灌进她的身体，将她劈成两半，造出天与地。大风暴是神的武器，可怕，却创造秩序。",
  "babylonians:fire": "公元前689年，亚述国王辛那赫里布（𒀭𒌍𒉽𒈨𒌍𒋢）因巴比伦（𒆍𒀭𒊏𒆠）屡次反叛而大怒，洗劫全城，焚烧房屋与神庙，又引运河之水淹没废墟。他夸口说自己把这里变成了一片草地。巴比伦人为他们的城市哀悼，马尔杜克（𒀭𒀫𒌓）的神像也被掳往亚述。十年后，辛那赫里布的亲生儿子以撒哈顿（𒀭𒀸𒋩𒉽𒀸）开始重建这座城，希望平息众神之怒。",
  "babylonians:thunder": "风暴之主阿达德（𒀭𒅎）骑着公牛，手握叉状闪电。当雷声滚过巴比伦（𒆍𒀭𒊏𒆠）上空，书吏们便查阅预兆丛书《埃努玛·阿努·恩利尔》：若阿达德在此月打雷，则收成丰饶，或敌人将至。雷声并非偶然，而是一条讯息，国王的学者们会写信向他解释其中的含义。",
  "babylonians:birth": "巴比伦的母亲们惧怕拉玛什图（𒀭𒆷𒈦𒌅），这个女魔会偷走婴儿、带来高烧。产房四周挂着帕祖祖（𒀭𒉺𒍪𒍪）的护身符，这个狗脸恶魔被选来驱赶她。接生婆呼唤女神宁胡尔萨格（𒀭𒊩𒌆𒄯𒊕）。这个孩子将来会在泥板书舍学习楔形文字，成为书吏，还是会成为河上的商人？家人只祈求他能活下来。",
  "babylonians:death": "死者下到「尘土之屋」伊尔卡拉（𒅕𒆗𒆷），在那里以泥土为食、以羽毛为衣。巴比伦人把亲人葬在自家地板下面，每月举行基斯普仪式时，家人为他们浇水、摆上面包，呼唤他们的名字。没有供奉的鬼魂会四处游荡，侵扰生者。纪念亡者是家中日常的责任，而不只是某一天的事。",
  "assyrians:hunt": "约公元前645年，尼尼微（𒌷𒉌𒉡𒀀）的亚述巴尼拔（𒀸𒋩𒆕𒀀）王宫：狮子从笼中被放进士兵围成的场地。国王站在战车上放箭，再用长矛将它们了结。大英博物馆的浮雕上，一头垂死的母狮拖着瘫痪的后腿。这是一种王室仪式：国王守护国土，抵御混沌。雕刻者给予狮子的怜悯，或许比他们本意要多。",
  "assyrians:battle": "公元前701年，辛那赫里布（𒀭𒌍𒉽𒈨𒌍𒋢）围攻犹大（יהודה）的拉吉（לכיש）。亚述工兵用石块筑起攻城坡道；在弓箭手掩护下，攻城槌沿坡道推上去，守军则向下投掷火把。城池陷落。尼尼微（𒌷𒉌𒉡𒀀）的浮雕上，一家家人带着家当走向流放之路。亚述军队是那个时代组织最严密的军队，而它希望每一位进入王宫的访客都看到这一切。",
  "assyrians:gather": "想象：在亚述城（𒀸𒋩𒆠）周围靠雨水灌溉的平原上，农夫们用青铜镰刀收割大麦，一名王室官员在一旁看着，要为军队取走他那一份。从远方迁来的俘虏在他们身边劳作，说着阿拉米语。亚述纳西尔帕二世曾夸耀自己在尼姆鲁德建起园林，种下从历次征战中收集来的树木和种子；而这一季的收成，又将供养下一季的战争。",
  "assyrians:ritual": "当一次月食威胁到国王以撒哈顿（𒀭𒀸𒋩𒉽𒀸）的性命时，亚述学者们让一个替身国王登上王位：一个平民被披上王袍，而真正的国王则扮作农夫藏了起来。长达一百天里，凶兆可能落在这个替身身上。写给国王的书信显示出他的恐惧，以及学者们小心翼翼的安慰：危险终会过去。",
  "assyrians:rain": "亚述北部依靠的是雨水，而非运河。冬雨一旦失约，庄稼就会枯萎，行省总督的书信便纷纷送到国王面前：滴雨未落，百姓挨饿。一些研究者认为，一场漫长的干旱在帝国最后几十年里加速了它的衰弱。祭司向阿达德（𒀭𒅎）求雨；农夫们眼看着云从扎格罗斯山飘来，又飘走。",
  "assyrians:flood": "公元前612年，米底人和巴比伦人围攻尼尼微（𒌷𒉌𒉡𒀀）。后世的一种传说（《那鸿书》（נחום）中也有回响）称，河闸被打开，王宫随之消融。无论是否真有洪水冲破城墙，尼尼微在那一年陷落了，强大的帝国在一代人之内土崩瓦解。对亚述人来说，那就是世界的末日。",
  "assyrians:wind": "想象：亚述大军行进途中，一场沙尘暴从叙利亚草原滚滚而来。士兵们裹住脸，马匹掉转尾巴背对着风，战车纵队停了下来。负责记录战役的书吏不会提到这件事，亚述年鉴只记载胜利。但每个士兵都会记得沙粒的刺痛，和那漫长的、什么也看不见的一天。",
  "assyrians:fire": "公元前612年，尼尼微（𒌷𒉌𒉡𒀀）陷入火海。亚述巴尼拔（𒀸𒋩𒆕𒀀）的王宫倒塌，大火把他宏大图书馆中成千上万块泥板烧得坚硬，其中就有《吉尔伽美什史诗》（𒀭𒄑𒉋𒂵𒎌）。帝国在那场烈焰中灭亡，它的文字却因此得以保存，在废墟中静静等待，直到19世纪40至50年代被莱亚德和拉萨姆发掘出来。",
  "assyrians:thunder": "想象：征战季节，雷声滚过亚述城（𒀸𒋩𒆠），城墙上的一名士兵问他的长官：阿达德（𒀭𒅎）是不是发怒了？宫廷学者们早已在给国王写信：若月亮位于某宫时阿达德打雷，国王的敌人必将败北。只要有专家在旁解读，亚述人便信赖雷声。",
  "assyrians:birth": "想象：在尼尼微（𒌷𒉌𒉡𒀀）的一户人家，临产的母亲紧握着帕祖祖（𒀭𒉺𒍪𒍪）护身符，接生婆念诵着对付拉玛什图（𒀭𒆷𒈦𒌅）的咒语。父亲是名士兵，正随国王出征在外。这孩子将来会是书吏、商人，还是又一个士兵？家人盼望生个儿子，而母亲只盼自己能活着看到孩子长大。",
  "assyrians:death": "亚述王室的葬礼遵循古老的仪式：国王的遗体安放在旧都亚述城（𒀸𒋩𒆠）的石棺中，陪葬有油、食物和珍贵物品。一篇文献描述了国王以撒哈顿（𒀭𒀸𒋩𒉽𒀸）的送葬者以及随他下葬的礼物。鬼魂必须由子孙通过基斯普供奉来供养，否则便会四处游荡，饥饿而危险。",
  "sumerians:hunt": "想象：拂晓时分，在乌尔（𒋀𒀊𒆠）附近的沼泽里，苏美尔渔夫撑着芦苇船穿行于水道之间，叉鲤鱼、张网捕鸭。城中南纳（𒀭𒋀𒆠）神庙从每一次渔获中抽取份额，记在泥板上。年长的猎人仍在讲述吉尔伽美什（𒀭𒄑𒉋𒂵𒎌）和恩奇都（𒀭𒂗𒆠𒄭）如何前往雪松林，杀死了它的守护者洪巴巴（𒄷𒉿𒉿），并猜想众神是否真的宽恕了他们。",
  "sumerians:battle": "约公元前2450年，拉格什（𒉢𒁓𒆷𒆠）的安那吐姆（𒂍𒀭𒈾𒁺）与邻城温马（𒄑𒆵𒆠）为争夺一片名为古埃迪纳（𒄘𒂔𒈾）的肥沃土地而开战。他的「鹫碑」上，士兵们组成盾牌与长矛紧密相连的方阵，踏过敌人的尸体前进，秃鹫叼走了首级。围绕那条边界沟渠的战争延续了好几代人，这是我们能读到的最早的边界争端。",
  "sumerians:gather": "一篇约写于公元前1700年、名为《农夫训诫》的苏美尔文献，是父亲给儿子的忠告：留心洪水，小心开启运河闸门，备好耕牛，在大麦倒伏前收割。收割者三人一组劳作。接着是打谷场、扬场，再向啤酒女神宁卡西献上祷告，因为大麦已足够酿酒了。",
  "sumerians:ritual": "每年在乌尔（𒋀𒀊𒆠），月神南纳（𒀭𒋀𒆠）都会在他的塔庙中接受肥羊、椰枣和黄油的供奉。约公元前2300年，阿卡德（𒀀𒂵𒉈𒆠）的萨尔贡（𒊬𒊒𒄀）之女恩赫杜安娜（𒂗𒃶𒌌𒀭𒈾）在那里担任大祭司，并为伊南娜（𒀭𒈹）写下颂歌，她是已知最早留下姓名的作者。祭司们观察月亮的弯角和飞鸟的轨迹，询问这一年是否吉祥。答案要在静默中求得。",
  "sumerians:rain": "在苏美尔（𒆠𒂗𒂠），天空很少下雨，大地仰赖底格里斯河与幼发拉底河。在《乌尔哀歌》（𒋀𒀊𒆠）中，恩利尔（𒀭𒂗𒆤）的风暴席卷全城，田里没有雨水，畜群没有青草。几个世纪的灌溉让盐分慢慢渗入田地。农夫们从种小麦改种大麦，等待一个始终没有到来的好时光。",
  "sumerians:flood": "在苏美尔的朱苏德拉（𒍣𒌓𒋤𒁺）故事中，众神决定降下洪水。恩基（𒀭𒂗𒆠）向这位虔诚的国王发出警告；洪水在大地上肆虐七天七夜，一艘大船在水面上颠簸。随后，太阳神乌图（𒀭𒌓）的光芒照了进来。朱苏德拉向他跪拜，获赐永生。《苏美尔王表》甚至把历史分为洪水之前与洪水之后。",
  "sumerians:wind": "约写于公元前2000年的《乌尔哀歌》（𒋀𒀊𒆠）哀悼一场毁灭了城市的大风暴，那是恩利尔（𒀭𒂗𒆤）的风暴：埃兰人如风而至，死者横陈街头，如同熔化的青铜。女神宁伽尔（𒀭𒊩𒌆𒃲）恳求众神让它停下，但风暴并未止息。这首诗是一整座城市为自己哀哭的声音。",
  "sumerians:fire": "想象：一个干燥的夏夜，大火席卷了乌鲁克（𒌷𒀕）城墙外的芦苇房屋。芦苇烧起来像稻草一样，不到一个时辰，整个街区便化为灰烬。邻居们从运河提来一罐罐水，一位祭司祈求火神吉比尔平息怒火。到了早晨，人们已在沼泽里割下新的芦苇，像祖先那样重新盖房。",
  "sumerians:thunder": "苏美尔风暴神伊什库尔（𒀭𒅎）驾云而行，在群山之上咆哮。他的雷声能带来北方丘陵所需的雨水，也能带来毁坏庄稼的冰雹。在颂歌里，他是一头野牛。想象：拉格什（𒉢𒁓𒆷𒆠）城外的一位农夫听到他的隆隆声，望向东方，不知伊什库尔带来的是祝福还是威胁。",
  "sumerians:birth": "大地之母、女神宁胡尔萨格（𒀭𒊩𒌆𒄯𒊕）在母腹中塑造孩子。一段苏美尔咒语把分娩中的孩子比作一艘满载珍贵货物的船，祈求众神让它平安靠岸。许多母亲和婴儿死去了。然而家人仍在憧憬：这孩子会成为学习楔形文字的书吏，或许还会成为另一个三分之二是神的吉尔伽美什（𒀭𒄑𒉋𒂵𒎌）。",
  "sumerians:death": "约公元前2500年，在乌尔（𒋀𒀊𒆠），王后普阿比下葬时发间饰着金叶，随葬有里拉琴、车辆和数十名侍从，他们似乎与她一同死去，一排排躺在伦纳德·伍利发掘的「大死亡坑」中。普通人的葬礼则简单得多：地板下的一座墓，一只杯子和一个盘子，好让他们在黑暗的冥界不致挨饿。",
  "hittites:hunt": "想象：在安纳托利亚高原上，赫梯猎人带着鹰和猎犬骑马出猎，追逐鹿和野羊。阿拉加许于克的一幅浮雕上，一位猎人面对一头雄鹿，一头狮子正扑向公牛。雄鹿是乡野守护神的圣兽，猎人每次猎获后，都会在岩石神龛留下一部分以表感谢。",
  "hittites:battle": "公元前1274年，卡迭石，这一次从赫梯一方看。国王穆瓦塔利二世用假探子引诱拉美西斯二世上钩，随后派出约2500辆战车渡河，冲入埃及营地。这个圈套几乎得手。十六年后，哈图西里三世（𒄩𒀜𒌅𒅆𒇷）与拉美西斯签订了已知最早的和平条约，如今条约的复制品就挂在联合国。双方都宣称获得了荣耀，但和平得以维持。",
  "hittites:gather": "在哈图沙（𒌷𒄩𒀜𒌅𒊭）周围的高地上，农夫们赶在短暂的夏天结束前收割二粒小麦和大麦。山坡上的葡萄园渐渐成熟，哈图沙巨大的粮仓可以储存供数千人食用的粮食。赫梯法典列出了一头牛、一只羊、一量酒的价格。丰收节上人们敬奉特里皮努（𒀭𒋼𒇷𒉿𒉡），这位神曾在愤怒中消失，把万物生长也一并带走。",
  "hittites:ritual": "赫梯祭司通过神谕向众神提出只需回答「是」或「否」的问题：观察飞鸟、查看羊的内脏，还有KIN（𒆥）神谕，即由一位老妇人移动符号的一种游戏。约公元前1320年瘟疫期间，国王穆尔西里二世（𒈬𒌨𒅆𒇷）一遍又一遍地追问众神为何发怒，并写下他的祷文：我必须为父亲的什么罪孽赎罪？每一个答案都被记录下来。",
  "hittites:rain": "特里皮努（𒀭𒋼𒇷𒉿𒉡）神话讲述了一位在盛怒中消失的神。雾气遮住了窗户，烟雾充满了屋子，谷物不再生长，牲畜和人都不再生育。众神四处寻找，直到一只蜜蜂发现他睡在草地上，把他蜇醒。一场仪式把他迎回了家。赫梯人懂得等待世界重获生机意味着什么。",
  "hittites:wind": "想象：一场风暴从本都山脉扑向哈图沙（𒌷𒄩𒀜𒌅𒊭），撕扯着大神庙的屋顶，把储藏室里的泥板吹得四散。祭司们求问神谕：哈梯风暴神（𒌷𒄩𒀜𒋾）是否发怒了？老人们说，这是特舒卜又在与巨龙伊卢扬卡（𒈲𒅋𒇻𒅀𒀭𒅗）搏斗，正如每年春天的普鲁利（𒁍𒊒𒌌𒇷）节所讲述的那样。",
  "hittites:fire": "约公元前1180年，哈图沙（𒌷𒄩𒀜𒌅𒊭）被遗弃并焚毁。考古学家发现了被毁的大神庙和卫城。是外敌入侵、干旱，还是朝廷先行撤离？这个曾与埃及分庭抗礼的帝国的都城陷入黑暗，赫梯文字也随之消失。废墟中被烧硬的数千块泥板保存了他们的法律与祷文，等待三千多年后的考古学家来发现。",
  "hittites:thunder": "哈梯风暴神（𒌷𒄩𒀜𒋾）塔尔洪纳（𒀭𒋻𒄷𒌦𒈾）乘坐一辆由名叫塞里和胡里的公牛拉的战车。他是众神之王，而哈梯的国王是他的管家。哈图沙（𒌷𒄩𒀜𒌅𒊭）上空响起雷声，意味着神就在此处。在普鲁利（𒁍𒊒𒌌𒇷）节上，祭司们诵述他如何在女神伊娜拉（𒀭𒄿𒈾𒊏）的帮助下杀死巨蛇伊卢扬卡（𒈲𒅋𒇻𒅀𒀭𒅗），确保大地繁荣。",
  "hittites:birth": "记录在基祖瓦特纳（𒌷𒆠𒄑𒍪𒉿𒀜𒈾）泥板上的赫梯分娩仪式，描述了一张分娩凳、一位念诵咒语的接生婆，以及献给为新生儿纺织命运的母亲女神们的祭品。家人在屋外等候。这孩子将来会成为宫廷书吏、士兵，还是女祭司？女神们早已知晓；家人只能怀着希望。",
  "hittites:death": "赫梯国王去世时，人们说他已成了神。他的遗体被火化，前后历时十四天，人们用银钳拾起他的骨殖，浸入油中，裹上精美的布，安放在一座石屋里的椅子上。每天都有供奉，国王的像受到敬拜，宫廷按照泥板所保存的严格次序举哀。",
  "phoenicians:hunt": "想象：在比布鲁斯（𐤂𐤁𐤋）上方覆盖着雪松的山坡上，腓尼基猎人追逐鹿和野山羊；而山下的海岸边，他们的同胞在猎捕另一种猎物：骨螺。成千上万只螺壳被碾碎，制成比黄金还贵重的推罗紫染料。作坊里弥漫着腐烂贝类的恶臭，但海那边的国王们将身披这种颜色。",
  "phoenicians:battle": "公元前332年，岛城推罗（𐤑𐤓）拒绝向亚历山大（Ἀλέξανδρος）大帝打开城门。整整七个月，亚历山大的工兵在海中修筑堤道，推罗人则派出火船攻击，并在城墙上奋战。城破之后，数千人被杀，数万人沦为奴隶。那条堤道至今犹存：推罗已不再是一座岛。",
  "phoenicians:gather": "想象：在西顿（𐤑𐤃𐤍）背后的山丘上，一家家人采收橄榄和葡萄，榨出油和酒，装进双耳瓶运上船。腓尼基人首先是商人，因此每一季收成都会变成贸易货物。一位父亲教儿子用新的字母记数，这套字母将传到希腊乃至更远的地方：aleph（𐤀）、beth（𐤁）、gimel（𐤂）。",
  "phoenicians:ritual": "船只启航前，船长会带着礼物前往推罗（𐤑𐤓）的麦勒卡特（𐤌𐤋𐤒𐤓𐤕）神庙，或去敬奉阿施塔特（𐤏𐤔𐤕𐤓𐤕）。希罗多德（Ἡρόδοτος）曾造访这座神庙，看到两根柱子，一根是黄金的，一根是在夜里发光的祖母绿。水手们祈问：前往加迪尔（𐤂𐤃𐤓）的航程能否平安归来？沿岸神龛里留下的小陶像和油灯，记录着他们默默的祈求。",
  "phoenicians:rain": "想象：在同一海岸的城市乌加里特（𐎜𐎂𐎗𐎚），巴力（𐤁𐤏𐤋）神话讲述风暴神如何被死神莫特（𐤌𐤕）吞下，于是有一段时间滴雨不降。腓尼基农夫知道，干燥的夏季是等待的季节。当秋天第一批云从海上飘来，人们便说巴力从冥界回来了。",
  "phoenicians:flood": "公元2世纪的作家琉善（Λουκιανός）这样描述：每当雨水使比布鲁斯（𐤂𐤁𐤋）附近的阿多尼斯（Ἄδωνις）河涨水，河水就被山中富含铁质的泥土染成红色。人们说那是被野猪杀死的阿多尼斯的血，妇女们在阿多尼斯节（Ἀδώνια）上为他哀悼。这场洪水既是悲伤，也是新生：神随春天归来。",
  "phoenicians:wind": "想象：一艘从推罗（𐤑𐤓）出发、满载雪松木和紫布的腓尼基船，在塞浦路斯外海遭遇冬季狂风。船员降下帆，把货物抛入海中，向巴力（𐤁𐤏𐤋）和麦勒卡特（𐤌𐤋𐤒𐤓𐤕）祈祷。阿什凯隆（𐤀𐤔𐤒𐤋𐤍）和马萨龙附近的沉船表明，许多船再也没有回来。抵达港口的人献上祭品，多年后仍在讲述这段经历。",
  "phoenicians:fire": "想象：在西顿（𐤑𐤃𐤍）港，一艘船上的焦油着了火，火焰沿着拥挤的码头从一条船甲板跳到另一条船上。水手们砍断缆绳，把燃烧的船推向开阔水面。玻璃匠和染工们也纷纷赶来。腓尼基人靠海为生，失去一支船队就意味着失去一季的贸易。",
  "phoenicians:thunder": "风暴神巴力·哈达德（𐤁𐤏𐤋 𐤄𐤃𐤃）驾云而行，投掷闪电。在乌加里特诗歌中，他建造了一座有窗的宫殿，窗户一打开，他的声音，也就是雷声，便震动大地，令群山颤抖。在腓尼基水手听来，雷声是那位既能拯救他们、也能让他们葬身海底的神的声音。",
  "phoenicians:birth": "想象：比布鲁斯（𐤂𐤁𐤋）一位商人的妻子正在分娩，她的丈夫远航去了迦太基（𐤒𐤓𐤕𐤇𐤃𐤔𐤕）或加迪尔（𐤂𐤃𐤓）。接生婆呼唤阿施塔特（𐤏𐤔𐤕𐤓𐤕），床头挂着一枚埃及侏儒神贝斯的小护身符。这孩子将来会是水手、书吏，还是像建立迦太基的埃莉莎那样，成为一座新城的创建者？",
  "phoenicians:death": "1923年，考古学家发现了约公元前1000年比布鲁斯（𐤂𐤁𐤋）国王阿希拉姆（𐤀𐤇𐤓𐤌）的石棺。棺盖上刻有最早的腓尼基字母铭文之一：诅咒任何打扰此墓的人。石棺侧面雕刻着哀悼的妇女，她们撕扯头发、捶打胸口。腓尼基人放声哀哭，希望亡者能安息。",
  "palmyrans:hunt": "想象：帕尔米拉弓箭手骑马从绿洲出发，进入叙利亚草原追猎瞪羚和野驴。他们是著名的射手，后来曾为罗马（Roma）效力，足迹从达契亚直到不列颠（Britannia）。一位年轻猎人带着他的第一只瞪羚，穿过柱廊大街回家，像父亲当年那样，在大神庙里将一份献给贝尔（𐡡𐡫）。",
  "palmyrans:battle": "公元272年，曾把帕尔米拉（𐡶𐡣𐡬𐡴）打造成从埃及延伸到安纳托利亚的帝国的女王芝诺比娅（𐡡𐡶𐡦𐡡𐡩），在安条克（Ἀντιόχεια）附近、随后又在埃米萨（Ἔμεσα）迎战皇帝奥勒良（Aurelianus）。她的重骑兵，即「克利巴纳里」铁甲骑兵，发起冲锋，却被罗马人的佯退拖得精疲力竭。芝诺比娅骑骆驼向波斯逃去，却在幼发拉底河（Εὐφράτης）边被擒。她的不屈至今仍在叙利亚受到传颂。",
  "palmyrans:gather": "埃夫卡泉（𐡠𐡱𐡳𐡠）在沙漠中央灌溉着棕榈、橄榄和石榴园。但帕尔米拉（𐡶𐡣𐡬𐡴）真正的收获是贸易：来自幼发拉底河（Εὐφράτης）的商队带来丝绸、香料和珍珠。一部公元137年以希腊文和阿拉米文刻成的税法，列出了从奴隶到香油等各种货物的税额。在这里，所谓收获，就是清点骆驼。",
  "palmyrans:ritual": "在贝尔（𐡡𐡫）神的节日里，公元32年落成的大神庙的祭司们举行宴会。兄弟会成员凭小陶筹入场，斜倚在卧榻上共餐。人们通过占卜与祈祷，向贝尔以及日神雅尔希博尔（𐡩𐡴𐡧𐡡𐡥𐡫）和月神阿格利博尔（𐡰𐡢𐡫𐡡𐡥𐡫）询问商队能否平安归来。这座神庙屹立了将近两千年，直到2015年。",
  "palmyrans:rain": "帕尔米拉（𐡶𐡣𐡬𐡴）依靠绿洲的泉水和周围山丘上储集雨水的蓄水池为生。想象：在一个干旱之年，商队首领们聚集在广场上，商议在水井可能干涸之时，是否还要派骆驼穿越沙漠。在孤注一掷之前，他们等待着云，也等待着来自幼发拉底河（Εὐφράτης）的消息。",
  "palmyrans:wind": "想象：一场沙尘暴从沙漠中升起，吞没了这座商队之城。柱廊消失在昏黄的空气中，骆驼跪下低头，商人们躲进商队客栈。风暴可能持续数日，把行进在旷野上的商队掩埋。柱廊两侧的雕像所表彰的商队首领们，正是因带领旅人穿越这样的风暴而声名远扬。",
  "palmyrans:fire": "芝诺比娅（𐡡𐡶𐡦𐡡𐡩）战败后，帕尔米拉（𐡶𐡣𐡬𐡴）于公元273年再次反叛。奥勒良（Aurelianus）卷土重来，洗劫全城并焚毁了部分城区。太阳神庙的财宝遭到劫掠。帕尔米拉再也没能恢复昔日荣光。曾经是商路主人的市民们，眼看着自己的财富化为灰烬，这座城市也渐渐沦为一座小小的沙漠戍所。",
  "palmyrans:thunder": "想象：在一个难得的冬夜，雷声滚过沙漠，雨水注满了绿洲周围的蓄水池和干河谷。帕尔米拉人感谢天空之主巴尔沙明（𐡡𐡰𐡫𐡵𐡬𐡭），他的神庙就坐落在柱廊附近。沙漠中的人们知道，一场风暴既能带来山洪，也能带来一整年的水，因此他们怀着敬畏迎接它。",
  "palmyrans:birth": "想象：帕尔米拉（𐡶𐡣𐡬𐡴）一户商人家里生了个女孩，一位年老的姑母说，芝诺比娅（𐡡𐡶𐡦𐡡𐡩）也出生在这里，是本地人家的女儿，后来成了敢于挑战罗马（Roma）的女王。筋疲力尽的母亲笑了。父亲想到种种风险：高烧、沙漠、战争。尽管如此，一家人仍向贝尔（𐡡𐡫）献上乳香，怀抱梦想。",
  "palmyrans:death": "帕尔米拉人把死者葬在城外高高的塔墓和地下墓室里，每具遗体安放在一个壁龛中，用雕刻的肖像封住。那些面孔平静地向外凝望，佩戴着珠宝，以阿拉米文写下自己的名字：呜呼，某某之子某某。许多这样的半身像保存在博物馆中。家人们会在墓中聚宴，以纪念他们。",
  "minoans:hunt": "想象：在克里特（Κρήτη）的山中，年轻人带着弓和猎犬猎捕克里特野山羊，那是一种长着修长弯角的野山羊，它的角是制作复合弓的珍贵材料。克诺索斯（𐀒𐀜𐀰）著名的斗牛壁画则展现了另一种较量：少年们在冲来的公牛背上翻腾，与岛上最危险的动物共舞。",
  "minoans:battle": "米诺斯人留下的战争图像少得出奇，他们的宫殿也没有高大的城墙；或许舰队就是他们的防线。想象：米诺斯战船在克里特（Κρήτη）附近驱赶劫掠者，船员奋力划桨、放箭。约公元前1450年，迈锡尼希腊人接管了克诺索斯（𐀒𐀜𐀰），米诺斯的克里特渐渐变成了一个希腊世界。",
  "minoans:gather": "在克诺索斯（𐀒𐀜𐀰），比人还高的大陶瓮——皮托斯瓮（pithoi）——储存着橄榄油、葡萄酒和谷物。出土于阿基亚特里亚达（Αγία Τριάδα）的「收割者之瓶」描绘了一列农民肩扛农具、放声歌唱的队伍，领头的男子摇着叉铃。这是古代艺术中最欢快的场景之一：收获就是一场节庆。",
  "minoans:ritual": "在尤克塔斯山（Γιούχτας）等山顶圣所，米诺斯人点燃篝火，留下人和动物的小陶像，或许是在祈求疗愈与庇护。1979年，考古学家在阿内莫斯皮利亚（Ανεμόσπηλια）发现一座约公元前1700年毁于地震的神庙，祭坛上似乎躺着一名年轻男子。在那最后的时刻，祭司们向神灵祈求了什么，已无从知晓。",
  "minoans:rain": "想象：克里特（Κρήτη）一个干旱的夏天，农民们登上山顶圣所，留下陶塑小像，点起火堆，祈求女神降雨。橄榄树挺了过来，谷物却枯萎了。他们向南望海，向北望着锡拉（Θήρα）上空的云，等待着。一个世纪后，他们未曾想象的巨变正是从那个方向到来。",
  "minoans:flood": "约公元前1600年，锡拉（Θήρα）火山，即圣托里尼，发生了人类历史上规模最大的喷发之一。阿克罗蒂里（Ακρωτήρι）城被掩埋，不过居民似乎及时逃离了。海啸可能冲击了克里特（Κρήτη）北岸，火山灰飘散到整个爱琴海（Αἰγαῖον）。有人认为，柏拉图（Πλάτων）笔下亚特兰蒂斯（Ἀτλαντίς）的故事正是由此萌芽。",
  "minoans:wind": "想象：一场大风暴横扫爱琴海（Αἰγαῖον），满载象牙和黄金从埃及归来的米诺斯船只拼命驶向科莫斯（Κομμός）港。船帆撕裂，桨手们与巨浪奋力搏斗。米诺斯人是海上的主宰，阿克罗蒂里（Ακρωτήρι）壁画中的船只神气十足，但每个家庭都知道，大海随时可能夺走自己的儿子。",
  "minoans:fire": "约公元前1450年，大火席卷了克里特（Κρήτη）的宫殿。在克诺索斯（𐀒𐀜𐀰），烈焰烧硬了用线形文字B写成的泥板——那是当时统治此地的迈锡尼希腊人的文字——反而使他们记录绵羊、橄榄油和奴隶的清单得以保存。费斯托斯（𐀞𐀂𐀵）和扎克罗斯（Ζάκρος）的宫殿也被焚毁。无论是战争还是天灾，一个时代在火焰中落幕。",
  "minoans:thunder": "想象：雷声滚过伊达山（Ἴδη），克里特人说，那位年轻的神又在山洞里诞生了。后世希腊人相信，宙斯（Ζεύς）婴儿时被藏在克里特的一个洞穴中，名为库瑞忒斯（Κουρῆτες）的武士们敲击盾牌，好让他的父亲听不到他的啼哭。也许米诺斯人早已在风暴中听见了神的声音。",
  "minoans:birth": "想象：克里特一座庄园里，一位母亲在家族女性的帮助下分娩，一尊手持蛇的女神陶像守护着这个家。米诺斯艺术中，女性常以女祭司和领袖的形象出现。家人们猜想，这个女孩将来会不会在宫殿圣所侍奉神灵，或是在克诺索斯（𐀒𐀜𐀰）的庭院里跃牛起舞。",
  "minoans:death": "阿基亚特里亚达（Αγία Τριάδα）出土的一具约公元前1400年的彩绘石棺描绘了一场葬礼：女人们在两柄双面斧之间向容器中倾倒祭品，一名男子弹奏里拉琴，一头公牛被献祭躺在桌上，死者站在自己的墓前，接受船和牲畜等赠礼。这是了解米诺斯人如何祭奠亡者最清晰的一扇窗。",
  "greeks:hunt": "在《奥德赛》（Ὀδύσσεια）中，年轻的奥德修斯（Ὀδυσσεύς）与外祖父的儿子们在帕尔纳索斯山（Παρνασσός）猎捕一头巨大的野猪。野猪猛冲过来，在他膝盖上方划开一道伤口，随后才被他杀死。几十年后，当他乔装回到家中，老奶妈欧律克勒亚（Εὐρύκλεια）正是凭这道伤疤认出了他。对希腊人（Ἕλληνες）来说，狩猎是对年轻人的考验，留下的印记讲述着他的故事。",
  "greeks:battle": "马拉松（Μαραθών），公元前490年。约一万名雅典人（Ἀθηναῖοι）和普拉提亚人（Πλαταιεῖς）在平原上迎战波斯大军。将军米太亚德（Μιλτιάδης）削弱中路、加强两翼；重装步兵冒着箭雨跑完最后一段距离，两翼合拢，包围了波斯人。192名雅典人阵亡，葬在至今仍矗立于此的土冢中。曾亲身参战的埃斯库罗斯（Αἰσχύλος）最引以为傲的就是那一天。",
  "greeks:gather": "赫西俄德（Ἡσίοδος）约于公元前700年写成的《工作与时日》（Ἔργα καὶ Ἡμέραι）是一部农事历：昴星团（Πλειάδες）升起时开始收割，落下时开始犁地。他告诫懒惰的弟弟佩耳塞斯（Πέρσης），众神把生计藏了起来，不让人类轻易得到，唯有劳作才能换来。秋天采摘橄榄，夏末在大桶里踩葡萄，再在树荫下喝上一杯酒。",
  "greeks:ritual": "在德尔斐（Δελφοί），皮提亚（Πυθία）坐在阿波罗（Ἀπόλλων）神庙的三足鼎上，说出神的答复。公元前480年，惊恐于波斯入侵的雅典人（Ἀθηναῖοι）得到神谕：一道木墙将拯救他们。地米斯托克利（Θεμιστοκλῆς）主张，这道墙指的就是他们的战船。于是他们转战海上，在萨拉米斯（Σαλαμίς）取得了胜利。人们来到德尔斐，为战争、殖民和婚姻求问。",
  "greeks:rain": "干旱的年份里，希腊农民向宙斯（Ζεύς）祈雨。马可·奥勒留记下了雅典人的祷词：下雨吧，下雨吧，亲爱的宙斯，降在雅典人（Ἀθηναῖοι）的田地上。农民们留意着伊米托斯山（Ὑμηττός）上空聚集的云，那是雨将到来的征兆。一整年的农事都在等待秋雨，它要么恰好及时落下，要么根本不来。",
  "greeks:flood": "丢卡利翁（Δευκαλίων）与皮拉（Πύρρα）是希腊的洪水故事：宙斯（Ζεύς）厌恶人类的邪恶，便发洪水淹没世界。丢卡利翁得到父亲普罗米修斯（Προμηθεύς）的警告，造了一只箱子，漂流九天后在帕尔纳索斯山（Παρνασσός）登陆。神谕让他们把母亲的骨头扔到身后，于是他们扔出石头，石头变成了新的人类。希腊人（Ἕλληνες）还会指出帕尔纳索斯山上他们登陆的地方。",
  "greeks:wind": "在《奥德赛》（Ὀδύσσεια）中，风神埃俄罗斯（Αἴολος）给了奥德修斯（Ὀδυσσεύς）一个装着所有风暴之风的口袋，只留下温和的西风送他回家。眼看伊塔卡（Ἰθάκη）已近在眼前，他的船员以为袋里装着黄金，打开了口袋。狂风呼啸而出，把他们吹回了大海彼端。对希腊人（Ἕλληνες）来说，风暴可能来自众神，也可能源于自己的愚蠢。",
  "greeks:fire": "公元前356年，一个名叫赫罗斯特拉特（Ἡρόστρατος）的人放火烧毁了以弗所（Ἔφεσος）的阿耳忒弥斯（Ἄρτεμις）神庙——世界七大奇迹之一，只为让自己声名远扬。以弗所人（Ἐφέσιοι）判他死罪，并禁止任何人提及他的名字，但史家还是把它记了下来。传说大火燃起的那一夜，正是亚历山大大帝（Ἀλέξανδρος ὁ Μέγας）出生之夜，而阿耳忒弥斯当时正忙于照看这场分娩，无暇顾及神庙。",
  "greeks:thunder": "雷霆之神宙斯（Ζεύς），他的闪电由库克洛普斯（Κύκλωπες）锻造。被雷击中的地方会成为圣地，被围起来不许触碰。当雷声滚过奥林匹亚（Ὀλυμπία），希腊人（Ἕλληνες）便感到神就在眼前，那里盛大的节庆正是为他而办。在《伊利亚特》（Ἰλιάς）中，宙斯在伊达山（Ἴδη）上打雷，示意他偏向哪一方。雷声就是讯息。",
  "greeks:birth": "希腊人分娩时有接生婆和家中女眷陪伴，并向阿耳忒弥斯（Ἄρτεμις）和厄勒梯亚（Εἰλείθυια）祈祷。第五或第七天，孩子在「绕火礼」（Ἀμφιδρόμια）中被抱着绕家中火塘行走，第十天取名。欧里庇得斯（Εὐριπίδης）笔下的美狄亚（Μήδεια）说，她宁愿上三次战场，也不愿生一个孩子。可谁知道这个男孩会不会成为伯里克利（Περικλῆς），或是苏格拉底（Σωκράτης）呢。",
  "greeks:death": "遗体被清洗、穿戴整齐，停放在家中进行「停灵礼」（prothesis），女人们围在一旁哀哭，撕扯头发。随后在黎明前举行「出殡」（ekphora）：送葬队伍伴着笛声与哭丧者走向墓地。死者口中放一枚钱币，用来付给卡戎（Χάρων），渡过冥河斯堤克斯（Στύξ）。彩绘陶瓶上描绘着这些场景。此后数代人都会带着油和丝带前来扫墓。",
  "athenians:hunt": "雅典人色诺芬（Ξενοφῶν）曾随「万人军」远征，他写过一部《狩猎论》（Κυνηγετικός），讲述带猎犬追捕野兔。他描写猎犬如何在黎明时嗅到气味，网如何横张在小径上，猎人们如何奔跑在阿提卡（Ἀττική）的山丘间。在他看来，狩猎能为战争和美德训练年轻人：耐心、坚韧与敏捷的判断。",
  "athenians:battle": "萨拉米斯（Σαλαμίς），公元前480年9月。波斯人（𐎱𐎠𐎼𐎿）已经焚毁了卫城（Ἀκρόπολις），雅典人（Ἀθηναῖοι）站在船上，望着城市上空升起的浓烟。地米斯托克利（Θεμιστοκλῆς）把波斯舰队诱入狭窄的海峡，在那里，数量优势反而成了弱点。希腊三列桨战船猛力冲撞，削断敌船的桨。曾参加此战的埃斯库罗斯（Αἰσχύλος）后来写下《波斯人》（Πέρσαι），从敌人的视角想象这场失败。",
  "athenians:gather": "橄榄是雅典娜（Ἀθηνᾶ）赐给雅典（Ἀθῆναι）的礼物，她正是凭此在与波塞冬（Ποσειδῶν）的争城比赛中获胜。乡间矗立着神圣的橄榄树，称为「莫里埃」（μορίαι），其油装满泛雅典娜节（Παναθήναια）赛会的奖品双耳瓶。收获是辛苦活儿，要用棍子敲打树枝。砍倒一棵神圣橄榄树，可能招致流放乃至死刑。",
  "athenians:ritual": "每年秋天，成千上万的人沿着圣道（Ἱερὰ Ὁδός）从雅典（Ἀθῆναι）走到厄琉息斯（Ἐλευσίς），参加德墨忒尔（Δημήτηρ）与珀耳塞福涅（Περσεφόνη）的秘仪。入会者发誓保守秘密，而且守得如此忠实，以至于我们至今仍不知道他们看到了什么。身为入会者的西塞罗说，他们学会了快乐地活着，并怀着更好的希望死去。整个队伍笼罩在静默的敬畏之中。",
  "athenians:rain": "公元前430年，与斯巴达（Σπάρτη）交战期间，雅典（Ἀθῆναι）城内挤满了从乡间逃来的难民，瘟疫随之爆发。修昔底德（Θουκυδίδης）染病后幸存，他描述了高烧、干渴，以及堆在神庙里的尸体。伯里克利（Περικλῆς）本人也死于此疫。雅典人（Ἀθηναῖοι）等待着战争、瘟疫和命运的转机。他们的世界再也没有完全恢复。",
  "athenians:flood": "想象：一场冬季风暴让刻菲索斯河（Κηφισός）和伊利索斯河（Ἰλισσός）漫过河岸，淹没了阿提卡（Ἀττική）的低洼田地和城市边缘。农民失去了种子，凯拉米克斯（Κεραμεικός）的陶匠们把陶器搬往高处。雅典人（Ἀθηναῖοι）想起，波塞冬（Ποσειδῶν）因输给雅典娜（Ἀθηνᾶ）而恼怒，曾经淹没过特里亚平原（Θριάσιον πεδίον）。",
  "athenians:wind": "雅典广场上罗马时代的风之塔刻有八位化身为飞翔人物的风神：寒冷的北风玻瑞阿斯（Βορέας）吹着海螺号，西风仄费罗斯（Ζέφυρος）撒着鲜花。公元前480年，一场风暴摧毁了部分波斯舰队，雅典人（Ἀθηναῖοι）便祭祀玻瑞阿斯，相信这位因俄瑞堤伊亚（Ὠρείθυια）而与他们结为姻亲的北风回应了他们的祈祷。",
  "athenians:fire": "公元前480年，薛西斯（𐎧𐏁𐎹𐎠𐎼𐏁𐎠）率领的波斯人（𐎱𐎠𐎼𐎿）攻占雅典（Ἀθῆναι），焚毁了卫城（Ἀκρόπολις）上的神庙。在萨拉米斯（Σαλαμίς）观望的雅典人（Ἀθηναῖοι）发誓不再重建，以作纪念。三十年后，伯里克利（Περικλῆς）打破誓言，建起了帕特农神庙（Παρθενών）。后来考古学家发现了雅典人在大火后掩埋的残破雕像，即所谓「波斯废墟」。",
  "athenians:thunder": "在阿里斯托芬（Ἀριστοφάνης）的喜剧《云》（Νεφέλαι）中，苏格拉底（Σωκράτης）告诉一个农夫，雷声并非宙斯（Ζεύς），而是云彩相撞、破裂所致。观众哄堂大笑，但这出戏反映了一种真实的焦虑：哲学家们在质疑神灵。公元前399年，苏格拉底以不敬神和腐蚀青年的罪名受审，饮下了毒芹汁。在雅典（Ἀθῆναι），雷声是一个信仰问题。",
  "athenians:birth": "孩子出生后第十天，雅典家庭会设宴为其取名，常以祖父之名命名。门上挂橄榄枝花环表示生了男孩，挂一簇羊毛表示女孩。伯里克利（Περικλῆς）约生于公元前495年；他的母亲阿加丽斯特（Ἀγαρίστη）梦见自己生下了一头狮子。没有人知道一个新生儿将来是会领导雅典（Ἀθῆναι），还是会在开春之前死于一场高烧。",
  "athenians:death": "伯罗奔尼撒战争（Πελοποννησιακὸς πόλεμος）期间，雅典（Ἀθῆναι）每年冬天都会为阵亡者举行国葬。遗骨按部落分装在柏木棺中，每部落一具，另设一具空棺献给失踪者。公元前431年，伯里克利（Περικλῆς）发表了修昔底德（Θουκυδίδης）所记载的《葬礼演说》（Ἐπιτάφιος）：整个大地都是名人的坟墓。哀悼成了对这座城邦本质的宣示。",
  "spartans:hunt": "接受「阿高盖」（agoge）训练的斯巴达男孩被刻意少给食物，并被鼓励去偷；被抓住就要挨打。普鲁塔克（Πλούταρχος）讲过一个男孩把偷来的狐狸藏在斗篷下，任由它啃咬自己的肚子也不肯暴露，最终默默死去。带着著名的拉科尼亚猎犬打猎，既为战争训练了他们，也为公共食堂提供了食物。",
  "spartans:battle": "温泉关（Θερμοπύλαι），公元前480年8月。列奥尼达国王（Λεωνίδας）率三百斯巴达人（Σπαρτιᾶται）及数千盟军，扼守狭窄的关隘抵御薛西斯（𐎧𐏁𐎹𐎠𐎼𐏁𐎠）。整整两天，波斯大军一波波撞碎在希腊人的盾牌上。随后，当地人厄菲阿尔特斯（Ἐφιάλτης）给波斯人（𐎱𐎠𐎼𐎿）指出了一条山间小路。列奥尼达遣走大部分盟军，战斗到最后一人。墓志铭写道：过客啊，请告诉斯巴达人，我们遵从他们的法令，长眠于此。",
  "spartans:gather": "斯巴达公民不种地，种地的是希洛人（εἵλωτες）。这些被奴役的美塞尼亚人（Μεσσήνιοι）和拉科尼亚人（Λάκωνες）耕种田地，向斯巴达主人缴纳固定份额的大麦、葡萄酒和橄榄油。监察官每年都要正式向希洛人宣战，可见斯巴达人（Σπαρτιᾶται）对他们有多么畏惧。收成养活了士兵，却建立在恐惧之上。",
  "spartans:ritual": "斯巴达人（Σπαρτιᾶται）以虔诚著称：每次开战前，国王都要献祭并解读征兆；在神圣节日期间，他们不会出兵。公元前479年的普拉提亚（Πλάταιαι）战役中，征兆不吉，斯巴达人便站在箭雨下等待，直到国王保萨尼阿斯（Παυσανίας）向赫拉（Ἥρα）祈祷，征兆转为吉利。直到那时，他们才发起冲锋。",
  "spartans:rain": "公元前490年，雅典（Ἀθῆναι）恳求斯巴达（Σπάρτη）援助，共同在马拉松（Μαραθών）抵抗波斯人（𐎱𐎠𐎼𐎿）。斯巴达人（Σπαρτιᾶται）答应了，却说正值卡尔涅亚节（Κάρνεια），要等到满月才能出兵。他们在战役结束后第二天才赶到，察看了波斯人的尸体，并称赞了雅典人（Ἀθηναῖοι）。斯巴达人的等待是宗教之事，哪怕世界等不起。",
  "spartans:flood": "想象：泰格托斯山（Ταΰγετος）的冬雨使欧罗塔斯河（Εὐρώτας）暴涨，在斯巴达（Σπάρτη）城下漫过河岸，那里正是「阿高盖」男孩们采芦苇铺床的地方。男孩们一如既往，不用刀，徒手从水中拔起芦苇。对斯巴达人（Σπαρτιᾶται）来说，就连河水泛滥也不过是又一次耐力考验。",
  "spartans:wind": "想象：在泰格托斯山（Ταΰγετος）的山坡上，一场冬季风暴横扫训练场，一年只发一件斗篷、没有鞋穿的斯巴达男孩们默默地挤在一起。教官们在一旁看着。抱怨会让他们蒙羞。普鲁塔克（Πλούταρχος）说，斯巴达男孩学会忍受寒冷与饥饿，好让战场上没有什么能令他们意外。",
  "spartans:fire": "想象：闪电击中斯巴达（Σπάρτη）卫城上的一座神庙，公民们冲去救火，祭司们则忙着解读征兆。斯巴达没有城墙，并以士兵就是城墙而自豪，但火是长矛无法对付的敌人。长老们前往德尔斐（Δελφοί）求问神谕：是哪位神灵发怒了。",
  "spartans:thunder": "公元前464年，一场大地震袭击斯巴达（Σπάρτη），摧毁了城市的大部分，据说还夺去了许多年轻人的生命。希洛人（εἵλωτες）趁机起义。疲于应对的斯巴达人（Σπαρτιᾶται）向雅典（Ἀθῆναι）求援，随后又心生猜疑，把雅典军队打发回家，由此开启了最终导致伯罗奔尼撒战争（Πελοποννησιακὸς πόλεμος）的裂痕。大地如雷鸣般咆哮。",
  "spartans:birth": "据普鲁塔克（Πλούταρχος）记载，斯巴达新生儿要被抱到长老面前接受检查。健康的就抚养长大；体弱的，据说会被弃置在泰格托斯山（Ταΰγετος）附近一个叫阿波忒泰（Ἀποθέται）的地方。现代史家怀疑这种做法的普遍程度。据说母亲们会用葡萄酒给新生儿洗澡，以测试其体质。希望与恐惧同时守在摇篮边。",
  "spartans:death": "普鲁塔克（Πλούταρχος）说，按斯巴达法律，只有战死的男人和死于分娩的女人才能在墓碑上刻名。哀悼时间很短，只有十一天，而且必须克制。然而国王去世时，全国上下都要大声哀哭，希洛人（εἵλωτες）也被迫哀嚎。一位母亲对儿子说：要么带着你的盾牌回来，要么躺在盾牌上回来。",
  "macedonians:hunt": "在韦尔吉纳，据信属于腓力二世（Φίλιππος Β΄）的陵墓里有一幅王家狩猎彩绘饰带：骑马和徒步的猎手手持长矛，在森林中追逐狮子、野猪和熊，画面中央骑马的年轻人或许就是亚历山大（Ἀλέξανδρος）。在马其顿（Μακεδονία），一个男人只有在不用网独力杀死一头野猪之后，才能在宴会上斜倚而卧。",
  "macedonians:battle": "高加米拉（Γαυγάμηλα），公元前331年10月。亚历山大（Ἀλέξανδρος）在一片为战车而选定的平原上，迎战大流士三世（𐎭𐎠𐎼𐎹𐎺𐎢𐏁）和庞大的波斯军队。他率伙友骑兵（Ἑταῖροι）向右翼运动，在波斯阵线上撕开一道缺口，随即直扑大流士，后者仓皇逃走。波斯帝国就此倾覆。亚历山大年仅二十五岁，他的士兵将追随他一路打到印度。",
  "macedonians:gather": "想象：在奥林匹斯山（Ὄλυμπος）脚下马其顿（Μακεδονία）的青翠山谷中，农民们收割小麦、采摘葡萄，伐木工则砍伐松树和冷杉用来造船——这是马其顿最重要的出口物。这些家庭的许多儿子正随亚历山大（Ἀλέξανδρος）远在亚洲。收成由老人、妇女和孩子们完成，他们寄出书信，询问亲人何时归来。",
  "macedonians:ritual": "公元前332年，亚历山大（Ἀλέξανδρος）冒险穿越利比亚沙漠，前往锡瓦求问阿蒙神谕。据一些记载，大祭司称他为宙斯-阿蒙（Ζεὺς Ἄμμων）之子。亚历山大从未透露自己问了什么；他写信给母亲奥林匹娅丝（Ὀλυμπιάς），说要当面告诉她。他还没来得及这样做就去世了。",
  "macedonians:rain": "公元前326年，在印度的希发西斯河（Ὕφασις）畔，行军八年的马其顿军队拒绝再往前走。季风雨已经下了七十天，盔甲生锈，士兵们思乡心切。亚历山大（Ἀλέξανδρος）在帐篷里赌气三天，等着他们回心转意。他们没有改变主意。他只好掉头返回。",
  "macedonians:flood": "想象：一场暴雨后，阿克西奥斯河（Ἀξιός）淹没了佩拉（Πέλλα）附近的平原，王都的港湖也漫溢出来。麦田泡在水中。马其顿人（Μακεδόνες）早已习惯河谷生活；这是艰难的一年，但年轻的国王腓力（Φίλιππος）很快就会兴修排水工程和防御工事，把他贫弱的王国变成希腊（Ἑλλάς）最强大的国家。",
  "macedonians:wind": "公元前325年，亚历山大（Ἀλέξανδρος）率领部分军队从印度穿越格德罗西亚沙漠（Γεδρωσία）返回。阿里安（Ἀρριανός）记载，一场突如其来的风暴引发山洪，冲走了营地以及随军的妻儿；还有灼热的狂风和沙暴。数千人死于干渴与酷热。这是整个远征中最残酷的一次行军，而亚历山大与士兵同甘共苦。",
  "macedonians:fire": "公元前330年，在波斯的礼仪之都波斯波利斯（Περσέπολις），亚历山大（Ἀλέξανδρος）的部下在一场醉宴后焚毁了薛西斯（𐎧𐏁𐎹𐎠𐎼𐏁𐎠）的宫殿。有人说这是为雅典（Ἀθῆναι）被焚复仇；雅典名妓泰伊丝（Θαΐς）在一旁怂恿。普鲁塔克（Πλούταρχος）说，亚历山大很快就后悔了。烧焦的废墟至今仍矗立在伊朗。",
  "macedonians:thunder": "普鲁塔克（Πλούταρχος）说，在与腓力（Φίλιππος）成婚的前一夜，奥林匹娅丝（Ὀλυμπιάς）梦见一道雷电击中她的子宫，一团大火从中蔓延开来。腓力后来梦见自己用一枚狮子印封住了她的子宫。预言者说，她怀上了一个像狮子一样勇敢的儿子。亚历山大（Ἀλέξανδρος）从小就相信，自己也许是宙斯（Ζεύς）之子。",
  "macedonians:birth": "公元前356年7月，亚历山大（Ἀλέξανδρος）生于佩拉（Πέλλα）。普鲁塔克（Πλούταρχος）说，就在同一天，腓力（Φίλιππος）接连收到三个消息：他的将军帕曼纽（Παρμενίων）击败了伊利里亚人（Ἰλλυριοί），他的马在奥林匹亚（Ὀλυμπία）夺冠，他的儿子出生了。预言者说，在三重胜利中降生的儿子将战无不胜。没有人料到他会走得那么远，也没有人料到他会那么年轻就死去。",
  "macedonians:death": "公元前323年6月，亚历山大（Ἀλέξανδρος）在巴比伦去世，年仅三十二岁，他的将领们为争夺遗体而反目。一辆华丽的灵车花了两年才造好。托勒密（Πτολεμαῖος）劫走灵车，把它带到埃及；亚历山大里亚（Ἀλεξάνδρεια）的陵墓曾有凯撒和奥古斯都前来拜谒，但其位置如今已经失传。一年前，亚历山大本人为好友赫费斯提翁（Ἡφαιστίων）之死悲痛不已，下令剪去马鬃以示哀悼。",
  "romans:hunt": "公元80年，提图斯皇帝为弗拉维圆形剧场（Amphitheatrum Flavium）——即罗马斗兽场——揭幕，举办了长达一百天的赛会；约九千头动物在「斗兽表演」（venationes）中被杀。狮子、熊、大象和鸵鸟在五万名观众面前遭到猎杀。这些动物从帝国各地捕获而来，从美索不达米亚到毛里塔尼亚。有些罗马人（Romani），比如西塞罗，觉得这种屠杀令人厌倦；而大多数观众则在欢呼呐喊。",
  "romans:battle": "坎尼，公元前216年8月2日。汉尼拔（𐤇𐤍𐤁𐤏𐤋）让中军向后弯曲，同时他的非洲步兵和骑兵从两侧合围罗马军团。约五万名罗马人（Romani）在一个下午内阵亡，其中包括一名执政官和八十名元老。罗马（Roma）没有投降。元老院（Senatus）禁止公开哀悼超过三十天，组建新的军团，又继续战斗了十四年。",
  "romans:gather": "老加图（Cato Maior）约于公元前160年写成的《农业志》（De Agri Cultura）讲述了经营农庄的方法：如何榨橄榄油，如何酿酒，奴隶生病时该喂什么（少喂一点）。在罗马（Roma），来自埃及和西西里（Sicilia）的谷物由船运抵奥斯提亚，「粮食配给」（annona）养活了城中的穷人。丰收节祭祀谷神刻瑞斯，农神节则以宴饮为一年收尾。",
  "romans:ritual": "任何公共行动之前，罗马的占卜官都要观察天空：鸟的飞行，圣鸡的举动。公元前249年，执政官普布利乌斯·克劳狄乌斯·普尔喀在德雷帕纳（Δρέπανα）海战前得知圣鸡不肯进食。他勃然大怒，把它们扔进海里：那就让它们喝水吧。结果他损失了整支舰队。罗马人（Romani）把这个教训记了好几个世纪。",
  "romans:rain": "公元79年8月24日，维苏威火山喷发，庞贝上空一片昏暗。小普林尼（Plinius Minor）在海湾对岸的米塞努姆目睹了这一切，他描述了一朵形如伞松的云，以及人们犹豫着是逃是留的等待。他的舅舅老普林尼（Plinius Maior）驾船去营救朋友，死在斯塔比伊的海滩上。火山灰如雪般飘落，世界没有等待。",
  "romans:flood": "台伯河（Tiberis）一次又一次淹没罗马（Roma）。塔西佗说，公元15年，河水暴涨，灌满了城中低洼地带，房屋倒塌，人被淹死。元老院（Senatus）讨论过改道其支流，但上游城镇抗议说，河流的位置是神灵定下的。罗马人（Romani）学会了与台伯河的脾气共处；教堂墙上的刻痕至今仍标记着历次洪水的水位。",
  "romans:wind": "公元前255年，罗马人战胜迦太基（𐤒𐤓𐤕𐤇𐤃𐤔𐤕）之后，一支三百多艘船的罗马舰队在西西里（Sicilia）的卡马里纳（Καμάρινα）外海遭遇风暴。执政官们无视领航员的警告，紧贴海岸航行，大部分船只撞碎在礁石上。数万人溺亡。这是古代最惨重的海难之一；罗马人（Romani）又建造了一支新舰队。",
  "romans:fire": "公元64年7月18日夜，大竞技场附近燃起大火，烧了整整六天。罗马十四个城区中，三个被彻底摧毁，七个严重受损。当时身在安提乌姆的尼禄赶回城中，向无家可归者开放了自己的花园。有传言说，他在城市燃烧时吟唱着特洛伊（Troia）的陷落。塔西佗说，他把罪责推给了基督徒。",
  "romans:thunder": "罗马人（Romani）仔细解读雷电：被雷击中的地方是神圣的，要围起来，称为「雷击圣地」（bidental）。祭司们解读雷电的方向和时机。公元前44年凯撒遇刺前的种种凶兆中，就有风暴和天空中的怪光。他的妻子卡尔普尼娅梦见了灾祸。凯撒还是去了元老院（Senatus），并在三月十五日（Idus Martiae）死去。",
  "romans:birth": "罗马新生儿被放在父亲面前的地上，父亲可以把孩子抱起，表示接纳其进入家族。男孩在第九天、女孩在第八天迎来「净化日」（dies lustricus），孩子接受净化、取名，并戴上护身符「布拉」（bulla）。公元前63年，盖乌斯·屋大维出生在帕拉丁山（Palatium）上的一座小房子里，他后来成为奥古斯都。当时没有人能预见到这一点。",
  "romans:death": "罗马贵族去世后，送葬队伍蜿蜒走向广场。演员们戴着他祖先的蜡制面具（imagines），让逝去的执政官和将军们再次与他同行。他的儿子在讲坛上致悼词。波利比乌斯（Πολύβιος）认为，这是一个年轻人所能见到的最激励人心的景象。随后，遗体在城墙外火化。",
  "carthaginians:hunt": "迦太基（𐤒𐤓𐤕𐤇𐤃𐤔𐤕）在北非的森林中捕捉野象，训练它们作战。想象：阿特拉斯山麓的猎人把一群大象赶进围栏，挑出幼象，慢慢牵往城墙里那座可容纳三百头大象的巨大象厩。一头捕获的大象，抵得上一百名士兵。",
  "carthaginians:battle": "公元前218年，汉尼拔（𐤇𐤍𐤁𐤏𐤋）率约四万人和三十七头大象翻越阿尔卑斯山（Alpes），许多人和象葬身于风雪、悬崖和山地部落之手。波利比乌斯（Πολύβιος）说，他在山口向饥饿的士兵们指点意大利（Italia）的平原，给他们希望。随后便是特雷比亚河、特拉西梅诺湖（Lacus Trasimenus）和坎尼的胜利。汉尼拔在意大利转战十五年，却始终没能攻下罗马（Roma）。",
  "carthaginians:gather": "迦太基人马戈（𐤌𐤂𐤍）写过一部著名的农学专著，共二十八卷。公元前146年迦太基（𐤒𐤓𐤕𐤇𐤃𐤔𐤕）陷落后，罗马元老院（Senatus）下令将其译成拉丁文，这是唯一幸免于难的迦太基书籍。迦太基人在突尼斯肥沃的庄园里种植橄榄、葡萄、无花果和石榴。加图曾在元老院展示一颗新鲜的迦太基无花果，警告大家敌人离得多近、又多么富庶。",
  "carthaginians:ritual": "迦太基人崇拜巴力·哈蒙（𐤁𐤏𐤋 𐤇𐤌𐤍）和塔尼特（𐤕𐤍𐤕），在重大行动之前献上祭品求问神意。在考古学家称为「托斐特」（tophet）的圣所里，数以千计盛有焚烧过的婴儿骨骸的小瓮，与献给塔尼特的石碑一起被埋在地下。学者们至今仍在争论：它们究竟是如希腊和罗马作家所说的儿童献祭，还是夭折婴儿的墓地。",
  "carthaginians:rain": "公元前241年第一次布匿战争结束后，迦太基（𐤒𐤓𐤕𐤇𐤃𐤔𐤕）不得不向罗马（Roma）支付巨额赔款，拿不到报酬的雇佣兵随即叛乱。整整三年，这座城市被自己从前的士兵围困，只能等待。波利比乌斯（Πολύβιος）称之为他所知最野蛮的战争。迦太基人坚持着，等待哈米尔卡·巴卡（𐤇𐤌𐤋𐤒𐤓𐤕 𐤁𐤓𐤒）平定叛乱，他最终做到了。",
  "carthaginians:flood": "想象：一场冬季风暴让巴格拉达斯河漫过河岸，淹没了迦太基（𐤒𐤓𐤕𐤇𐤃𐤔𐤕）城下平原上的农庄。农民们把家人转移到山上，等待洪水退去。后来，这条河淤积改道，使曾经是港口的乌提卡（𐤏𐤕𐤒）远离了海岸。迦太基人知道，河流会重新塑造大地。",
  "carthaginians:wind": "想象：一艘迦太基商船绕过赫拉克勒斯之柱（Ἡρακλέους στῆλαι），沿非洲海岸南下，正如约公元前500年航海家汉诺（𐤇𐤍𐤀）所做的那样。一场来自大西洋的风暴袭来。船员们向塔尼特（𐤕𐤍𐤕）和巴力（𐤁𐤏𐤋）祈祷，舵手则让船顺风而行。《汉诺航海记》讲述了岸上的火光，以及探险者称为「大猩猩」的多毛之人。",
  "carthaginians:fire": "公元前146年春。经过三年围城，小西庇阿攻入迦太基（𐤒𐤓𐤕𐤇𐤃𐤔𐤕）。比尔萨山周围的街巷激战了六天，房屋陷入火海。幸存的五万迦太基人沦为奴隶。站在西庇阿身旁的波利比乌斯（Πολύβιος）看到他望着燃烧的城市落泪，吟诵荷马（Ὅμηρος）的诗句：总有一天，神圣的特洛伊（Ἴλιος）也将灭亡。他想到的是罗马（Roma）。",
  "carthaginians:thunder": "想象：雷声滚过突尼斯湾，迦太基舰队停泊在圆形军港「科同」（cothon）中，那里可容纳约二百二十艘战船。瞭望兵在港心岛上的统帅塔楼里注视着天空。海上的雷声意味着神在说话；人们去问巴力·哈蒙（𐤁𐤏𐤋 𐤇𐤌𐤍）神庙的祭司，这对战事预示着什么。",
  "carthaginians:birth": "汉尼拔（𐤇𐤍𐤁𐤏𐤋）约生于公元前247年，是哈米尔卡·巴卡（𐤇𐤌𐤋𐤒𐤓𐤕 𐤁𐤓𐤒）之子。李维（Livius）说，他九岁时随父亲前往西班牙之前，被要求在祭坛前发誓，永远不做罗马（Roma）的朋友。想象：迦太基（𐤒𐤓𐤕𐤇𐤃𐤔𐤕）的一户人家里，一个新生命降临，家人们思忖着，这孩子长大后是会背负这样的誓言，还是能在和平中度日。",
  "carthaginians:death": "迦太基人把死者葬在城市周围山丘上凿岩而成的墓室和竖井中，随葬油灯、护身符、剃刀，以及用来吓退恶魔的小面具。考古学家在墓地中发现了面目狰狞的面具，以及刻有祭司和女祭司形象的石碑。2016年，一项针对比尔萨山出土的一具年轻男子骨骼的研究发现了欧洲血统，提醒人们这座城市的世界是何等广阔。",
  "aztecs:hunt": "在克乔利月（Quechōlli），墨西加人（Mēxihcah）会在萨卡特佩克山举行盛大的狩猎仪式，以纪念狩猎之神、云蛇米斯科亚特尔（Mixcōātl）。猎人们花好几天制作箭矢，然后排成长长的一列，驱赶鹿、兔子和郊狼穿过山坡。萨阿贡的报告人描述了猎人们满载猎物归来，以及授予捕获最多者的荣誉。",
  "aztecs:battle": "1520年6月30日夜，西班牙人（españoles）及其特拉斯卡拉（Tlaxcaltēcah）盟军试图沿特拉科潘（Tlacōpan）堤道悄悄撤出特诺奇蒂特兰（Tenōchtitlan）。一个打水的女人看见了他们，发出警报。墨西加（Mēxihcah）武士乘独木舟从两侧发起攻击；数百名西班牙人和数千名盟军被黄金压得沉入水中，或溺毙或战死。西班牙人称之为「悲痛之夜」（Noche Triste），墨西加人则称之为一场胜利。",
  "aztecs:gather": "在特斯科科湖（Tetzcohco）上的「浮动园圃」奇南帕（chinampas）里，一家家人收获玉米、豆子、南瓜、辣椒和苋菜。令贝尔纳尔·迪亚斯惊叹不已的特拉特洛尔科（Tlatelōlco）大集市上，堆满了农产品、火鸡、可可和黑曜石。在韦伊·托索斯特利（Huēyi Tōzōztli）丰收节期间，年轻女子把玉米穗送到玉米女神奇科梅科阿特尔（Chicōmecōātl）的神庙，祈求来年的种子得到祝福。",
  "aztecs:ritual": "每隔52年，两套历法会重新回到同一天，这时墨西卡人（Mēxihcah）担心世界可能就此终结。所有的火都被熄灭。在「新火之夜」，祭司们登上星之山，守望昴星团（tianquiztli）越过天顶。一旦星团越过，便在一名俘虏的胸膛上点燃火焰，再由奔跑者把火种送到每一户的灶台。最后一次新火仪式举行于1507年。",
  "aztecs:rain": "每年春天，墨西卡人（Mēxihcah）都焦急地等待雨神特拉洛克（Tlāloc）降下雨水。1454年，即「一兔年」（Ce Tōchtli）的旱灾与饥荒被人们世代铭记：有人为了换取玉米，把自己卖给托托纳克人为奴。在阿特尔卡瓦洛（Ātlcahualo）节期间，人们在山上向雨之精灵特拉洛克众（tlālohqueh）献祭。雨终于落下时，整个谷地都松了一口气。",
  "aztecs:flood": "约1500年，统治者阿维索特尔（Āhuitzotl）不顾劝告，修建了一条从科约阿坎（Coyōhuahcān）泉水通往特诺奇蒂特兰（Tenōchtitlan）的引水渠。水势太猛，竟淹没了全城。房屋倒塌，奇南帕园圃被淹，据说阿维索特尔本人在逃生时也撞伤了头。此前，特斯科科（Tetzcohco）的内萨瓦尔科约特尔（Nezahualcoyōtl）曾修筑一道大堤，保护城市免受湖水侵袭。",
  "aztecs:wind": "风神埃埃卡特尔（Ehēcatl）是羽蛇神克察尔科亚特尔（Quetzalcōātl）的一种化身，他用气息为雨神们清扫道路。他的神庙呈圆形，让风可以无阻地环绕而行。在《太阳传说》中，第二个世界「风之太阳」毁于飓风，那个世界的人都变成了猴子。一场大风暴提醒着墨西卡人（Mēxihcah）：世界是会终结的。",
  "aztecs:fire": "在西班牙人到来之前的几年里，墨西卡人（Mēxihcah）记录下种种怪异的征兆。其中之一是维齐洛波奇特利的神庙无故起火，人们泼的水越多，火就烧得越旺。白天出现了彗星。夜里有女人哭喊：我的孩子们，我们必须远走他乡。萨阿贡的讲述人把这些回忆为末日的预兆。",
  "aztecs:thunder": "特拉洛克（Tlāloc）在雨神的乐园特拉洛坎（Tlālōcān）统治一切。雷声是他的助手特拉洛克众（tlālohqueh）敲击水罐发出的声音。被雷击死或溺水而亡的人不火化而是土葬，他们会前往四季如春的特拉洛坎。湖上的雷暴令人畏惧，却也预示着滋养玉米的雨水。",
  "aztecs:birth": "墨西卡（Mēxihcah）婴儿出生时，接生婆会高呼战斗的呐喊：母亲打了一场仗，抓到了一名俘虏。死于分娩的母亲被尊为战士，称作莫西瓦奎茨克（mocihuaquetzqueh）。接生婆会告诉男婴，他真正的家在战场上。孩子的名字取决于托纳尔波瓦利（tōnalpōhualli）历中的日符；占卜师据此判断他的命运是吉是凶。",
  "aztecs:death": "墨西卡人（Mēxihcah）相信，死者的去处取决于他们怎样死去，而不是怎样活着。大多数人前往米克特兰（Mictlān），要在一只小狗的引导下，穿过九层地界，走上四年。遗体被包裹起来，连同祭品一起火化，骨灰则被保存。此后四年里，家人在忌日供奉食物。战死沙场的勇士则去陪伴太阳。",
  "mayans:hunt": "在《波波尔·乌》（Popol Wuj）中，英雄双胞胎乌纳普（Junajpu）和斯巴兰克（Xb'alanke）是吹箭狩猎的高手。他们把傲慢的鸟魔「七金刚鹦鹉」（Wuqub' Kaqix）从树上射落，打掉了他的牙齿。佩滕森林里的玛雅猎人用长矛和吹箭捕猎鹿、西貒和火鸡，进入森林之前，他们要先请求百兽之主的许可。",
  "mayans:battle": "公元562年，与强大的卡拉克穆尔结盟的卡拉科尔（Uxwitza'）城，在一场「星战」中击败了强大的蒂卡尔（Yax Mutul）。这种战役的时机依金星而定。蒂卡尔国王瓦克·禅·卡维尔大概被俘并被献祭，此后一百多年里，那里再没有竖起任何纪念碑。直到695年，蒂卡尔国王哈萨乌·禅·卡维尔击败了卡拉克穆尔。玛雅的战争，是各大家族之间旷日持久的较量。",
  "mayans:gather": "在《波波尔·乌》（Popol Wuj）中，众神曾试图用泥土和木头造人，却一再失败，直到他们把黄色和白色的玉米磨成面团，捏出了第一批真正的人。玛雅农民至今仍在米尔帕田里种植玉米、豆子和南瓜。收获时，家家户户把最先成熟的玉米穗献给大地和祖先。对玛雅人来说，玉米不只是食物，而是血肉。",
  "mayans:ritual": "在玛雅诸王国，国王亲自放血，与祖先对话。在公元709年的亚斯奇兰（Pa' Chan）24号门楣上，卡巴尔·肖克夫人将一根带刺的绳子穿过自己的舌头，伊察姆纳赫·巴拉姆国王在她头顶举着火炬。在下一块门楣上，一条幻象之蛇从染血纸张燃起的烟雾中升起，一位祖先从蛇口中现身说话。",
  "mayans:rain": "约公元800年至1000年间，南部低地的玛雅大城一座接一座被废弃。湖泊沉积物显示出一连串严重的干旱。曾宣称能借助恰克带来雨水的国王们，再也做不到了。想象：科潘的一位农民在旱季中等待，望着迟迟不肯落雨的云，最终决定带着家人北迁。",
  "mayans:flood": "在《波波尔·乌》（Popol Wuj）中，众神用一场黑雨洪水毁灭了没有心、没有头脑的木头人。他们的牲畜和陶罐反过来攻击他们，他们的狗开口说话，幸存者变成了猴子。随后众神再次尝试，用玉米造人。这场洪水是一次净化，是迈向更好创世的一步。",
  "mayans:wind": "玛雅词语 hurakan 源自基切人的神乌拉坎（Juraqan），他是独腿的造物主与风暴之神，英语中的 hurricane（飓风）一词便由此而来。在《波波尔·乌》（Popol Wuj）中，他是降下洪水的「天之心」（Uk'u'x Kaj）。每年秋天，来自加勒比海的飓风席卷尤卡坦。想象：图卢姆附近的一个村庄躲进石头建筑里，等待乌拉坎过境，渔民们把独木舟拖到远离岸边的地方。",
  "mayans-late:fire": "想象：旱季里，一位玛雅农民在播种前焚烧清理好的田地，玛雅农民至今仍是如此。烟雾在森林上空升起，一位萨满，即「日之守护者」（aj q'ij），在焚烧前向大地献上祭品。火是循环的一部分：玉米将从灰烬中生长。1562年，修士迭戈·德·兰达在马尼焚烧了玛雅典籍，玛雅人为之哭泣。",
  "mayans-late:thunder": "雨神恰克用闪电之斧劈开云层，释放雨水。他长鼻子的面具布满了乌斯马尔和卡巴的建筑。直到今天，尤卡坦的农民仍举行「恰恰克」（Ch'a Chaak）仪式，献上玉米饮品求雨，男孩们被绑在祭坛腿上，像青蛙一样呱呱叫。雷声，就是恰克来到了田间。",
  "mayans:birth": "在帕伦克（Lakamha'），十字神庙的铭文讲述了基尼奇·哈纳布·帕卡尔于公元603年诞生的故事。他十二岁登基，统治了68年。想象：一个玛雅家庭把新生儿带到守日人那里，守日人根据260天的历法解读孩子的生日。这孩子将来会成为统治者、书吏，还是农夫？历法会给出线索。",
  "mayans:death": "1952年，阿尔贝托·鲁斯在帕伦克（Lakamha'）铭文神庙中打开一道隐秘的阶梯，发现了公元683年去世的基尼奇·哈纳布·帕卡尔之墓。他躺在一具巨大的石棺中，脸戴玉面具；石棺盖上雕刻着他坠入，或从冥界巨口中升起的形象。普通玛雅人则葬在自家地板下，离家人很近。",
  "incas:hunt": "印加人（Inka）举行一种盛大的王家围猎，称为「查库」（chaku）。成千上万的男子围成一个方圆数公里的人墙，慢慢收拢，把骆马、原驼和鹿驱赶到中央。骆马剪毛后放归，它们细软的毛归印加王所有。猛兽被杀死，部分鹿被取作肉食。如今秘鲁仍在举行查库。",
  "incas:battle": "1532年11月16日，在卡哈马卡，刚刚战胜兄长瓦斯卡尔（Waskar）的萨帕·印加（Sapa Inka）阿塔瓦尔帕（Atawallpa）乘坐肩舆进入广场，身边跟随着数千名手无寸铁的侍从。巴尔维德修士递给他一本日课经，他将其扔到地上。皮萨罗的168名手下随即用火枪和火炮开火，骑马冲锋，擒获了阿塔瓦尔帕。仅仅一个下午，就有数千名安第斯人被杀。",
  "incas:gather": "在印加（Inka）帝国，收成属于三方：神灵、印加王和社群。梯田沿山坡层层攀升，冻干的马铃薯「楚纽」（ch'uñu）储存在沿路分布的数千座「科尔卡」（qollqa）仓库中。五月的艾穆赖（Aymuray）节庆祝玉米丰收，人们唱着歌把玉米运回家。印加王亲自在圣田里犁下第一道犁沟。",
  "incas:ritual": "卡帕科查（Qhapaq Hucha）：在危难之时或新王即位时，从帝国各地挑选出的孩子被带到库斯科（Qusqu），再被领上高峰，献给山神。1999年，人们在海拔近6700米的尤耶亚科火山上发现了三名这样的孩子，他们保存得极好，仿佛只是睡着了。他们的家人因此受到尊崇。对印加人（Inka）来说，这是最崇高的献礼，把帝国与山神「阿普」（apus）紧紧相连。",
  "incas:rain": "在安第斯山区，印加人（Inka）修建天文塔，每年六月观察昴星团，即「科尔卡」（Qullqa）。星光明亮，雨水就会充沛；星光暗淡，就会干旱。现代研究者发现这确实灵验：厄尔尼诺年份高空会出现稀薄的云层，使星光变暗。安第斯农民至今仍在六月观察昴星团，以决定何时种马铃薯。",
  "incas:flood": "想象：一个厄尔尼诺年份给海岸带来暴雨，安第斯山下的河流泛滥，冲毁了田地和道路。印加（Inka）官员打开仓库赈济百姓。安第斯神话讲述了一场远古洪水「乌努·帕查库蒂」（unu pachakuti），是维拉科查（Wiraqucha）降下的，用来毁灭最初的巨人，之后他在的的喀喀湖（Titiqaqa）重新造人。",
  "incas:wind": "想象：一场冬季风暴席卷高原草地普纳，王家大道上的一名信使「恰斯基」（chaski）顶着狂风和冻雨奔向下一个驿站，包里装着一串结绳记事的基普（khipu）。这种接力每天可把消息传送240公里。在驿站「坦普」（tampu）里，他交出消息，便瘫倒在火边。道路不能停。",
  "incas:fire": "1536年，曾被西班牙人扶立为傀儡的曼科·印加（Manqu Inka）起兵反抗，率大军围攻库斯科（Qusqu）。他的战士把裹着燃烧棉花的烧红石块投向茅草屋顶，全城陷入火海。困在两座建筑里的西班牙人孤注一掷，向萨克塞瓦曼（Saksaywaman）要塞发起冲锋。围城以失败告终，曼科退往比尔卡班巴（Willkapampa）。",
  "incas:thunder": "雷神伊亚帕（Illapa）手持投石索和棍棒。雷声是他投石索的爆响，闪电是他衣裳的闪光，雨水则是他从妹妹手中的水罐里倾倒出来的，而她身在银河之中。被雷击中而幸存的人，被认为是被选中成为医者的人。双胞胎也被视为伊亚帕的孩子。",
  "incas:birth": "印加（Inka）孩子要到断奶后，约两岁时，才在「鲁图奇库伊」（rutuchikuy），即第一次剪发礼上取名，亲戚们剪下一绺头发并赠送礼物。孩子的头发和指甲会被保存起来。约1418年出生的帕查库蒂（Pachakutiq），把一个小王国变成了美洲最大的帝国。想象：库斯科（Qusqu）附近村庄里的一位母亲，盼望着自己的儿子能活到那一天。",
  "incas:death": "印加（Inka）诸王并不真正死去。他们的木乃伊「马尔基」（mallki）留在宫殿里，由仆人侍奉，享用饮食，参与决策咨询，还被抬去参加节庆。每个王族世系「帕纳卡」（panaka）负责照料自己的祖先。西班牙人对此大为震惊。平民也被安置在洞穴或「丘尔帕」墓塔中，家人在节日里带着奇恰酒和食物前去探望。",
  "haudenosaunee:hunt": "秋天收获过后，豪德诺索尼（Rotinonhsión:ni）男子离开长屋村落前往猎场，一去往往数月，在今天纽约州一带的森林里追踪白尾鹿。猎人感谢动物的灵魂，并分享猎物的肉。在集会开始时诵读的《感恩辞》（Ohén:ton Karihwatéhkwen），感谢那些至今仍献身为人类食物的动物。",
  "haudenosaunee:battle": "1779年，乔治·华盛顿下令发动沙利文远征，进攻与英国结盟的豪德诺索尼（Rotinonhsión:ni）诸族。美军烧毁了四十多座城镇、果园，以及玉米、豆子和南瓜田。许多家庭逃往尼亚加拉堡，在那里熬过了一个可怕的冬天。华盛顿在塞内卡人（Onöndowá'ga:）中被称为「哈诺达加尼亚斯」（Hanodagá:nyas），意为「城镇毁灭者」，这个名字至今仍被铭记。",
  "haudenosaunee:gather": "「三姐妹」，即玉米、豆子和南瓜，种在同一个土堆里共同生长：玉米给豆子提供攀爬的支柱，豆子滋养土壤，南瓜为地面遮荫。田地归女性所有，收获也由她们主持；氏族母亲的话在议事会上举足轻重。在青玉米仪式上，人们为玉米的成熟而感恩。",
  "haudenosaunee:ritual": "仲冬时节，豪德诺索尼人（Rotinonhsión:ni）举行一年中最长的仪式，感恩并开启新的循环。人们分享并解读梦境，因为梦可以揭示灵魂所需。各医疗会社履行其职责。人们诵读《感恩辞》（Ohén:ton Karihwatéhkwen），问候人们、大地、水、植物、动物、风、月亮、太阳、星辰以及造物主（Shonkwaia'tíson）。",
  "haudenosaunee:rain": "想象：一个干旱的夏天，田里的玉米叶卷曲起来，长老们聚集在长屋中诵读《感恩辞》（Ohén:ton Karihwatéhkwen），感谢带来雨水的祖父们，雷神（Ratiwé:ras）。人们等待着，望着湖面上方的西边天空。当第一滴雨落在树皮屋顶上时，孩子们冲进了雨中。",
  "haudenosaunee:flood": "想象：春天的融雪使杰纳西河水暴涨，淹没了一个塞内卡（Onöndowá'ga:）村庄附近的低洼田地。家家户户把玉米种子搬到高处。在豪德诺索尼（Rotinonhsión:ni）的创世故事中，天空女从天而降，落入一个水的世界，动物们潜入水底带上泥土，把它放在一只乌龟的背上。大地就在那里生长起来：龟岛。",
  "haudenosaunee:wind": "在豪德诺索尼（Rotinonhsión:ni）传统中，风之精灵在《感恩辞》（Ohén:ton Karihwatéhkwen）中受到尊崇：四方之风带来季节的更替，并使空气洁净。想象：一场来自安大略湖的秋季大风暴撕扯着长屋的榆树皮，家家户户移到中央的火塘边一起熬过风暴，老人们彻夜讲着故事。",
  "haudenosaunee:fire": "豪德诺索尼（Rotinonhsión:ni）联盟的建立，源于和平缔造者与海华沙（Ayenwatha）把五个交战的民族团结在和平大树之下。中央议事之火在奥农达加燃烧，大议事会至今仍在那里召开。说「火已点燃」，意思是议事会正在开会。长屋中的火是一个家庭，而奥农达加的火则是整个联盟。",
  "haudenosaunee:thunder": "雷神（Hinon）是住在西方的祖父们，他们带来浇灌庄稼的雨水。他们在《感恩辞》中受到尊崇。春天，人们一听到第一声雷鸣，就举行仪式欢迎雷神归来，感谢他们即将带来的雨水，也感谢他们把有害的生灵镇压在地下。",
  "haudenosaunee:birth": "豪德诺索尼（Rotinonhsión:ni）社会是母系社会：孩子属于母亲的氏族，如龟、狼、熊或其他氏族，酋长由氏族母亲选出。做决定时要为未来的七代人着想。想象：一个孩子在长屋中出生，氏族母亲把他抱在怀里，思索着这个孩子将为第七代人传承些什么。",
  "haudenosaunee:death": "酋长去世时，要举行吊唁仪式：心境清明的民族前来安慰悲伤的民族，为他们卸下哀痛，让他们能够重新看清、听清、说清。这一仪式可以追溯到和平缔造者，他曾在海华沙（Ayenwatha）失去女儿们之后安慰过他。只有在这之后，才会推举新的酋长。悲伤由整个联盟共同分担，而不是独自承受。",
  "lakota:hunt": "在有马之前，拉科塔人（Lakȟóta）徒步猎捕野牛；有了马之后，他们成为北部大平原上了不起的骑马猎手。野牛狩猎由营地警察「阿基奇塔」（akíčhita）组织，他们防止任何人提前冲出、惊散牛群。野牛（tȟatȟáŋka）提供了肉，皮用来做帐篷，角做勺子，筋做线。感恩是狩猎的一部分。",
  "lakota:battle": "1876年6月25日，乔治·卡斯特中校在小大角河畔，即拉科塔人所称的「油草河」（Pȟežísla Wakpá），袭击了一座拉科塔（Lakȟóta）、夏延和阿拉帕霍人的大营地。由疯马（Tȟašúŋke Witkó）、加尔（Phizí）等人率领的战士发起反击，卡斯特及其整个营两百多人全部阵亡。坐牛（Tȟatȟáŋka Íyotake）曾梦见士兵纷纷倒落营中。这是抵抗的巅峰时刻。",
  "lakota:gather": "初夏，拉科塔（Lakȟóta）妇女采集野生草原芜菁「廷普辛拉」（tȟíŋpsiŋla），用削尖的木棍挖出来，编成串晾干。夏末，她们采摘苦樱桃，把它与野牛肉和油脂一起捣成肉饼「瓦斯纳」（wasná），以备过冬。苦樱桃成熟之月（Čhaŋpȟásapa Wí）是丰饶的时节。",
  "lakota:ritual": "太阳舞（Wiwáŋyaŋg Wačhípi）是拉科塔人（Lakȟóta）最重要的仪式，于仲夏为族人的福祉而举行。舞者立下誓愿，献出自身的苦痛，好让族人得以存续。政府于1883年禁止了这一仪式；它在暗中延续，并在20世纪重新公开举行。寻求异象（haŋbléčheya）则是独自在山丘上为求得异象而哭求。",
  "lakota:rain": "1889年，鬼舞（Wanáǧi Wačhípi）从派尤特先知沃沃卡那里传到了拉科塔人（Lakȟóta）中。他教导说，只要人们跳舞，死者就会归来，野牛会重现，白人会消失。在保留地上忍饥挨饿、土地被条约割裂的拉科塔家庭跳起舞来，等待世界改变。政府对此心怀恐惧，最终酿成了悲剧。",
  "lakota:wind": "想象：一场冬季暴风雪席卷平原，拉科塔（Lakȟóta）营地躲在一处长满三角叶杨的河谷中的帐篷里。火光渐弱，孩子们裹着野牛皮袍入睡，祖母们讲述着恶作剧蜘蛛伊克托米（Iktómi）的冬日故事。冬季年历，那张画满岁月的兽皮，会把这一年记为大雪之冬。",
  "lakota:fire": "想象：夏末，一场草原大火在风的驱赶下横扫大草原，比马跑得还快。侦察兵向营地报警，家家户户迅速拆下帐篷转移到河边，或者放一把逆火，烧出一片安全地带。平原诸民族也懂得用火，他们焚烧草地，好让新草长出来喂养野牛。",
  "lakota:thunder": "雷之存在瓦金扬（Wakíŋyaŋ）住在西方。梦见他们的拉科塔人（Lakȟóta）会成为「赫约卡」（heyókȟa），一种凡事反着做的神圣小丑：别人哀悼时他大笑，夏天里他发抖。黑麋鹿（Heȟáka Sápa）九岁时得到伟大的异象，他见到了雷之存在。雷是 wakȟáŋ：神圣、强大而危险。",
  "lakota:birth": "1831年，一个男孩在大河（Grand River）畔出生，取名「跳獾」；年轻时作为战士，他承袭了父亲的名字 Tȟatȟáŋka Íyotake，即坐牛。想象：在平原上的一顶帐篷里，一位母亲正在分娩，祖母们准备好一个串珠乌龟护身符，用来存放脐带。这个孩子会成为族人的领袖吗？她们向瓦坎·坦卡（Wakȟáŋ Tȟáŋka）祈祷。",
  "lakota:death": "1890年12月29日，在伤膝河（Čhaŋkpé Ópi Wakpála），第七骑兵团的士兵向大脚（Sitȟáŋka）率领的米尼孔朱（Mnikȟówožu）拉科塔人（Lakȟóta）队伍开火。约250至300名男女老幼遇难。尸体冻在雪地里，躺了好几天。黑麋鹿（Heȟáka Sápa）说：一个民族的梦想在那里死去了。如今，后人每年十二月举行大脚纪念骑行，让这份哀痛延续下去。",
  "americans:hunt": "1902年11月，西奥多·罗斯福总统到密西西比州猎熊。向导们把一头黑熊拴在柳树上让他射击，他却拒绝了，称这样做有失体育精神。一位漫画家把这一幕画了下来；布鲁克林（Breuckelen）的一位店主做了一只毛绒熊，并请求允许把它叫作「泰迪的熊」。罗斯福还设立了国家森林和国家公园，保护猎人们所热爱的一切。",
  "americans:battle": "葛底斯堡，1863年7月1日至3日。第三天，约12500名南军士兵发起皮克特冲锋，穿过一片开阔地，冲向公墓岭上的北军中央阵地。炮火和步枪火力将他们成片撂倒，生还者不到一半。三天之内，约5万人阵亡、负伤或失踪。同年11月，林肯发表了两分钟的演说：这个国家，在上帝的庇佑下，将获得自由的新生。",
  "americans:gather": "1621年，普利茅斯的定居者在第一次收获之后，与约九十名万帕诺亚格（Wôpanâak）男子及其首领马萨索伊特（Ousamequin）一起举行了为期三天的宴会，万帕诺亚格人带来了五头鹿。若没有万帕诺亚格人的帮助，尤其是斯匡托（Tisquantum）的帮助，殖民者恐怕难以存活。对许多原住民来说，11月的第四个星期四如今也是「全国哀悼日」，自1970年起每年在普利茅斯举行。",
  "americans:ritual": "想象：1969年阿波罗11号发射前夜，全美各地的家庭围坐在电视机前，许多人低头祈祷。1968年平安夜，正在绕月飞行的阿波罗8号乘组曾朗读《创世记》。美国人对未来充满希望，也为其中的风险而担忧。对一个信仰多元的国家来说，那一夜是一场共同的祈祷。",
  "americans:rain": "20世纪30年代，干旱加上不当的耕作，把南部大平原变成了「尘暴区」。1935年4月14日「黑色星期日」，一堵沙尘之墙滚过俄克拉何马州和得克萨斯州，白昼变成了黑夜。一家家人年复一年地等待雨水。数十万人离乡前往加利福尼亚。伍迪·格思里唱起《So Long, It's Been Good to Know Yuh》，多萝西娅·兰格则用相机记录下他们的面容。",
  "americans:flood": "1889年5月31日，宾夕法尼亚州约翰斯敦上游的南福克大坝在连日降雨后溃决。一堵裹挟着树木、房屋和火车车厢的水墙冲进小镇，造成2209人死亡。这座大坝属于匹兹堡富有实业家们组成的一个俱乐部。克拉拉·巴顿和刚成立不久的红十字会赶来，一待就是五个月，这是红十字会的第一次大规模救援行动。",
  "americans:wind": "2005年8月29日，卡特里娜飓风袭击墨西哥湾沿岸。在新奥尔良（La Nouvelle-Orléans），防洪堤决口，全城80%被淹。人们在屋顶上和超级巨蛋体育馆里等了好几天才等来救援。死亡人数超过1800人。散落到全国各地的音乐人、厨师和家庭纷纷回来重建家园，「第二线」游行又回到了街头。",
  "americans:fire": "1871年10月8日夜，德科文街上奥利里（Ó Laoghaire）家的谷仓里或附近燃起了一场火。在强风的推动下，大火穿过满城的木结构建筑，芝加哥大火烧了整整两天，毁掉了三平方英里以上的城区，使10万人无家可归。这座城市用石头、钢铁和雄心重建起来；世界上第一批摩天大楼就在这里拔地而起。",
  "americans:thunder": "据说，1752年6月，本杰明·富兰克林和儿子威廉在费城的雷雨中放风筝，风筝线上系着一把钥匙。当线上的纤维竖立起来、钥匙迸出火花时，他证明了闪电就是电。随后他发明了避雷针，美国城市上空的雷声也就不那么可怕了，成了科学已经解开的谜题。",
  "americans:birth": "1809年2月12日，在肯塔基州一间只有一个房间的小木屋里，南希·汉克斯·林肯生下了一个儿子，取名亚伯拉罕。在他九岁时，她便去世了。那间木屋里没有人能想到，这个孩子将带领国家度过内战，并终结奴隶制。每一个美国孩子的出生都带着一点这样的希望：任何人都可能成为任何人。",
  "americans:death": "1865年4月林肯遇刺后，一列送葬火车载着他的遗体，从华盛顿驶往伊利诺伊州斯普林菲尔德，全程1654英里，重走了他当年赴任总统的路线。数百万人伫立在铁路旁目送列车经过，许多人在夜里点起篝火守候。如今在新奥尔良（La Nouvelle-Orléans），爵士葬礼由铜管乐队伴随行进，去墓地时奏缓慢的圣歌，归来时奏欢快的乐曲。",
  "mexicans:hunt": "想象：在塔拉乌马拉山区，拉拉穆里（Rarámuri）跑者用古老的方式猎鹿，连续追赶数小时，直到猎物筋疲力尽。在北方的庄园里，查罗骑手在「查雷阿达」（charreada）中套牛，这项源于牧场劳作的运动成为了国家运动。墨西哥的狩猎和放牧，融合了原住民的耐力与从西班牙传来的骑术。",
  "mexicans:battle": "1862年5月5日，在普埃布拉，伊格纳西奥·萨拉戈萨将军率领装备简陋的墨西哥军队，击败了当时号称世界最精锐的法国远征军。法军冒雨向洛雷托和瓜达卢佩两座要塞发起仰攻，被打退下来。法国后来占领了墨西哥城（Ciudad de México），但「五月五日节」成为墨西哥敢于对抗帝国的象征。",
  "mexicans:gather": "在米尔帕田里，墨西哥农民把玉米、豆子和南瓜种在一起，就像他们的祖先数千年来所做的那样；墨西哥把玉米、巧克力、辣椒、番茄和香草带给了世界。每个地区都有自己的玉米：蓝的、红的、黑的、白的。女人们在黎明时分研磨碱化玉米（nixtamal），做玉米饼。20世纪40年代，诺曼·博洛格在索诺拉开展的小麦研究开启了绿色革命。",
  "mexicans:ritual": "每年12月12日，数百万朝圣者来到墨西哥城（Ciudad de México）的瓜达卢佩圣母大殿（Basílica de Guadalupe），许多人跪行前来，敬拜圣母。据传，1531年她在特佩亚克山（Tepeyacac）向胡安·迭戈（Cuauhtlatoatzin）显现，说的是纳瓦特尔语。午夜时分，马里亚奇乐队唱起《小晨曲》（Las Mañanitas）。人们向她祈求健康、工作、平安过境和孩子们的未来。",
  "mexicans:rain": "1910年，在统治了三十多年的波菲里奥·迪亚斯治下，墨西哥等待着变革。弗朗西斯科·马德罗于11月20日号召革命。在南方，埃米利亚诺·萨帕塔率领要求土地的农民起义：「土地与自由」（Tierra y Libertad）。漫长的等待终于爆发为长达十年的革命，夺去了大约一百万人的生命，也重塑了墨西哥。",
  "mexicans:flood": "殖民时期，建在排干湖泊之上的墨西哥城（Ciudad de México）一次又一次遭受水灾。1629年的一场大洪水让全城泡在水下长达五年；数千人死亡，许多人迁居他处。西班牙人开挖了韦韦托卡排水渠（Desagüe de Huehuetoca），以排空谷地的积水，这项工程持续了几个世纪。如今，由于地下含水层被抽干，这座城市仍在不断下沉。",
  "mexicans:wind": "2023年10月，飓风奥蒂斯在不到一天的时间里从热带风暴增强为5级飓风，毫无预警地袭击了阿卡普尔科。酒店和民房被撕开，海湾里的船只沉没。一家家人在废墟中等待救援。以自己的港口为傲的阿卡普尔科人，第二天早上就开始清理街道。",
  "mexicans:fire": "每年在墨西哥，复活节前夜，人们在街头焚烧塞满烟花的纸浆犹大像。在烟花之都图尔特佩克，每年三月举行烟花节（Feria de la Pirotecnia），纪念圣约翰·德·迪奥斯，烟花扎成的「小公牛」（toritos）在人群中横冲直撞。在墨西哥，火既是欢庆，也是危险。",
  "mexicans:thunder": "1985年9月19日早上7点19分，一场8.0级地震伴着雷鸣般的轰响袭击了墨西哥城（Ciudad de México）。建筑物倒塌，数千人遇难。政府反应迟缓，邻里们便自发组织救援队；「鼹鼠」救援队（topos）徒手在瓦砾中挖掘。2017年的同一天，就在一次演习之后，又一场地震来袭，救援队再次出动。",
  "mexicans:birth": "想象：瓦哈卡的一户人家生了一个女婴，祖母用一条披巾（rebozo）把她裹起来，并向瓜达卢佩圣母（Virgen de Guadalupe）点燃一支蜡烛。她将来会成为医生，会像弗里达·卡罗那样成为艺术家，还是会北上打工？一家人筹划着她的洗礼，以及多年后的十五岁成人礼（quinceañera），满怀期望。",
  "mexicans:death": "11月1日和2日是亡灵节（Día de Muertos），家家户户用万寿菊、蜡烛、糖骷髅、亡灵面包和逝者生前爱吃的食物搭起祭坛（ofrendas）。在帕茨夸罗和米斯基克，人们在墓地里彻夜守灵，伴着音乐和故事。万寿菊的花瓣指引亡魂回家。在这里，死亡不只是悲伤：它也是一场团聚。",
  "mapuche:hunt": "想象：在阿劳卡尼亚的森林里，一名马普切猎人追捕小巧的普度鹿（püdü），并在山坡上追猎原驼（luan），身上带着名为「拉基」（laki）的流星索，即坠有重物的投掷绳。进入森林之前，他要先请求「恩根」（ngen），即林木与水域的精灵主人的允许。在南洋杉林中，一家家人采集大颗的松子（ngülliw）。",
  "mapuche:battle": "1553年12月25日，马普切军事首领「托基」（toki）劳塔罗（Leftraru）率众袭击图卡佩尔（Tukapel）要塞。他曾给佩德罗·德·瓦尔迪维亚当过马夫，学会了西班牙人的战术。瓦尔迪维亚被俘并被处死。马普切人抵抗西班牙人长达三个多世纪；比奥比奥河成了边界。阿隆索·德·埃尔西利亚的史诗《阿劳卡纳》赞颂了他们的勇气。",
  "mapuche:gather": "想象：秋天，马普切家庭攀上安第斯山坡，从南洋杉上采集松子（ngülliw）。这是一种主食，可以煮食、烤食，也可以磨成粉。这些树被称为「佩文」（pewen），是神圣的；佩文切人（Pewenche），意为「佩文之民」，便因此得名。孩子们在大树下玩耍，长老们在一旁挑拣松子。",
  "mapuche:ritual": "恩吉拉顿（Nguillatun / Ngillatun）是马普切人最盛大的社群祈祷仪式，向恩格内琴（Ngenechen / Ngünechen）祈求丰收、雨水、健康与平衡。族人带着供品围聚在「雷威」（rewe）——一根雕刻的木柱旁。马奇（machi），即灵性治疗者，敲击昆特伦鼓（kultrun / kultrung），在恍惚中攀上雷威。许多家庭会连续数日参与祈祷。",
  "mapuche:rain": "想象：智利南部连年干旱，特木科（Temuko）附近的一个马普切社群——河流因干旱和松树、桉树种植园而日渐枯瘦——聚集起来举行恩吉拉顿（Ngillatun），祈求降雨。长者们回忆起河水满溢的年月。他们祈祷着，等待着，望着云从太平洋上飘来。",
  "mapuche:flood": "马普切传说讲述了一场远古洪水：海蛇凯凯菲卢（Kaykay Filu）掀起洪水要淹没人类，陆地之蛇特伦特伦菲卢（Trengtreng Filu）则抬高山丘，让人们攀上去避难。1960年5月22日，有记录以来最强的地震——9.5级——在瓦尔迪维亚附近发生，海啸席卷海岸。许多马普切人仿佛再一次看到了双蛇之间古老的争斗。",
  "mapuche:wind": "想象：一场来自太平洋的冬季风暴横扫阿劳卡尼亚，压弯森林，撕扯着茅草屋顶的房屋「鲁卡」（ruka）。一家人围坐在永不熄灭的中央火塘旁，长者讲述「埃佩乌」（epew），即古老的故事。在马普切人眼中，风是有生命的力量之一。",
  "mapuche:fire": "想象：干旱与松树种植园助长了夏季山火，大火席卷智利南部。一个马普切社群眼看着自己的森林和田地燃烧，圣地也受到威胁。年轻人组成救火队，冲进浓烟保护房屋和老人。这场火让一场围绕土地的漫长斗争浮出水面。",
  "mapuche:thunder": "想象：雷声在比亚里卡火山（Rukapillan）和亚伊马火山之间回荡，马普切长者说，这是皮扬（pillan）——火山与祖先的灵——在说话。皮扬既受尊崇又令人敬畏，与雷鸣、闪电和火山喷发相联系。社群可能会请教马奇，以了解这场风暴对他们意味着什么。",
  "mapuche:birth": "想象：阿劳卡尼亚的一座马普切鲁卡里，一个婴儿降生，祖母最先用马普敦贡语——这片土地的语言——对他说话。家人想起劳塔罗（Leftraru）：他约生于1534年，少年时被西班牙人掳走，后来归来领导自己的族人。有人希望这个孩子将来守护这片土地；也有人只祈求他健康、自由地长大。",
  "mapuche:death": "马普切人去世后，社群会举行「埃卢文」（eluwün），一场可能持续数日的葬礼。人们聚在一起，讲述逝者的事迹，分享食物。遗体被安放在独木舟形的棺木「万波」（wampo）中，抬往墓地，坟上可能立起一尊雕刻的木像「切马穆」（chemamüll）。逝者向西远行，渡过大海。",
  "muisca:hunt": "想象：在波哥大（Bacatá）高原上，穆伊斯卡（Muysca）猎人追逐白尾鹿，并在湖泊周围捕捉豚鼠和野鸭。猎鹿受到限制，有人说那是贵族的专属。猎人们带着投矛器和网，村落首领会分得一份猎物。肉在宴会上分享，佐以玉米啤酒奇恰（fapqua）。",
  "muisca:battle": "1537年，西班牙征服者贡萨洛·希门尼斯·德·克萨达率领疲惫不堪的部下，从马格达莱纳河攀上穆伊斯卡（Muysca）高地。齐帕（psihipqua）蒂斯克苏萨奋起抵抗，但于1538年被杀。洪萨的扎克克穆恩查托查被俘。富藏黄金与盐的穆伊斯卡联盟在两年之内覆灭。",
  "muisca:gather": "穆伊斯卡人（Muysca）以盐闻名，他们在锡帕基拉和内莫孔用陶罐煮卤水制盐。盐饼连同祖母绿、棉布和黄金一起被贩运到哥伦比亚各地。穆伊斯卡农民在梯田和垄田上种植玉米、马铃薯和藜麦。丰收与盐业贸易使他们成为安第斯地区最富庶的民族之一。",
  "muisca:ritual": "每当新的齐帕（psihipqua）即位，穆伊斯卡人（Muysca）都会在瓜塔维塔湖举行仪式：继承人全身涂满金粉，乘木筏被划到湖心，他和随从们将黄金和祖母绿献给湖水。这一仪式催生了「黄金国」（El Dorado）的传说。1969年发现的穆伊斯卡金筏，就以黄金再现了这一场景。",
  "muisca:rain": "穆伊斯卡人（Muysca）等待雨季、观察天象，他们的祭司「奇奎」（chyquy）掌管着一部依据月亮和太阳制定的历法。想象：在一个漫长的旱季，巴卡塔的人们列队前往一座圣湖，带着「通霍」（tunjo）——小小的黄金人像——作为供品祈雨。祭司们斋戒，守候征兆。",
  "muisca:flood": "在穆伊斯卡（Muysca）传说中，神祇奇布查昆迁怒于人类，用洪水淹没了波哥大（Bacatá）高原。人们向博奇卡祈祷，博奇卡踏着彩虹现身，用金杖击打岩石，开出一道缺口让洪水流走：这就是特肯达马瀑布（Salto del Tequendama）。奇布查昆被罚用双肩扛起整个世界；每当他换肩，大地便会震颤。",
  "muisca:wind": "想象：寒风扫过帕拉莫（páramo）——穆伊斯卡（Muysca）村落上方的高山荒原——带来雾气和雨水。一家人待在圆形房屋里，在火边织着棉质披毯。帕拉莫的湖泊是神圣的，从那里吹下来的风受到敬重，被视为高处的信使。",
  "muisca:fire": "索加莫索，古称苏加穆西（Sugamuxi），是穆伊斯卡人（Muysca）宏伟的太阳神庙所在地。据说1537年，西班牙士兵举着火把劫掠神庙时意外引燃了它，大火烧了好几天。如今，索加莫索考古博物馆中矗立着一座复建的神庙。对穆伊斯卡人而言，那是失去了他们最神圣的地方。",
  "muisca:thunder": "想象：雷声滚过波哥大高原，穆伊斯卡人（Muysca）说那是众神的声音。文化英雄博奇卡曾教会他们纺织与律法，并赐予他们彩虹。暴风雨过后出现的彩虹库恰维拉（Cuchavira），被视为他庇护的象征。临产的妇女和病人都会向库恰维拉祈祷。",
  "muisca:birth": "想象：在一个穆伊斯卡（Muysca）村落里，一位妇女分娩，家人向母神巴丘埃献上供品——传说她怀抱孩子从伊瓜克湖（Laguna de Iguaque）中升起，繁衍了世间的人类。这个孩子将来会成为酋长，成为在隐居中修习多年的祭司，还是制盐人？家人献上一尊小小的黄金通霍。",
  "muisca:death": "穆伊斯卡（Muysca）贵族死后被制成木乃伊，风干后用精美的棉质披毯包裹，连同黄金和祖母绿一起安放在洞穴或神庙中。有些木乃伊会被抬上战场以鼓舞士气。哀悼者连日吟唱挽歌，并饮奇恰（fapqua）以示怀念。平民则与他们的工具和陶罐一同下葬，为来世做好准备。",
  "tupi:hunt": "巴西沿海的图皮猎人手持比自己还高的弓，悄无声息地穿行于大西洋森林中，猎取貘、西猯和猴子。1557年曾在图皮南巴人中生活的法国人让·德·莱里，描述了他们高超的箭术，以及他们满载而归、与全村分享猎物时的喜悦。",
  "tupi:battle": "1554年，德国炮手汉斯·施塔登在圣维森特附近被图皮南巴人俘虏。他被告知自己将在一场仪式中被吃掉——这是受敬重的敌人的命运。他写道，自己凭着机智和祈祷撑过了九个月，直到一艘法国船将他赎回。他的书于1557年出版，生动详尽地描述了图皮南巴人的战争与仪式。",
  "tupi:gather": "每年，图皮家庭都会砍伐并焚烧一片森林，种植木薯、玉米和豆类；草木灰使土壤肥沃，几年之后森林又会长回来。在这里，火是日常生活，而非灾难。妇女们把木薯擦成碎末，再用长长的编织筒「蒂皮蒂」（tipiti）挤出其中的毒汁，制成木薯粉（farinha），这种粉至今仍在巴西各地食用。",
  "tupi:ritual": "图皮人的巫师「帕热」（pajé）往来于各村之间，与神灵交谈，他摇动葫芦沙锤马拉卡（mbaraká），烟草的烟雾弥漫四周。村民们询问战事是否顺利、收成是否丰饶。若泽·德·安谢塔等耶稣会传教士用图皮语写作，试图取代帕热；而图皮语作为巴西的通用语，延续了好几个世纪。",
  "tupi:rain": "一些图皮-瓜拉尼民族迁徙不息，寻找「伊维·马拉·埃伊」（Yvy Marã Ey），即「无恶之地」——一个没有死亡和苦难的地方。被称为「卡拉伊」（karaí）的先知带领整个村落踏上漫长旅程，向大海或西方进发，等待世界的改变。这类运动在瓜拉尼人中一直持续到20世纪。他们盼望的不是好天气，而是一个新世界。",
  "tupi:flood": "在法国修士安德烈·特韦于16世纪50年代记录的一则图皮南巴神话中，一场大洪水淹没了大地，只有两兄弟和他们的妻子爬上一棵高高的棕榈树得以幸存。图皮南巴人和他们的对手都是他们的后代。洪水是诸民族的起点，也是他们之间仇怨的开端。",
  "tupi:wind": "想象：一场夏季风暴从大西洋袭来，图皮南巴村落里棕榈叶覆顶的长屋在风中摇晃。吊床——图皮人的发明，后来被全世界借用——来回摆动。一家人围聚在火旁，孩子们紧紧依偎着母亲，老人们说，那是雷神图潘（Tupã）的声音。",
  "tupi:fire": "九月，旱季将尽，一个图皮村落焚烧新开的田地。男人们几个月前就已伐倒树木；如今干透的木头被点燃，烟雾升到森林上空，全村人都在一旁观望。草木灰将滋养木薯。刀耕火种是寻常的生活，是森林养育人们的方式；几年之后他们迁往别处，森林又会长回来。",
  "tupi:thunder": "对图皮-瓜拉尼诸民族来说，图潘（Tupã）是雷的声音。耶稣会传教士到来后，用「图潘」来称呼上帝，这个用法至今仍保留在瓜拉尼语中。想象：沿海村落里，一个小女孩第一次听到雷声，跑向祖母，祖母告诉她，那是图潘正从森林上空经过。",
  "tupi:birth": "让·德·莱里写道，图皮南巴人的孩子出生时，父亲用牙齿咬断脐带，随后在吊床上一连躺上好几天，休养、禁食、接待访客，仿佛是他自己生了孩子——这种习俗称为「拟娩」（couvade）。孩子会得到一个名字，有时取自某位祖先或一位受敬重的敌人。",
  "tupi:death": "1557年曾在图皮南巴人中生活的让·德·莱里，看到妇女们为逝者哀号数小时，历数他的事迹：他打猎多么出色，作战多么英勇。遗体被弯成坐姿，埋进圆形的坑里，有时装在一只大陶瓮中，并随葬食物和遗物。此后数日，人们仍留下食物、守着火堆，以驱赶恶灵艾尼安（Anhanga）。",
  "egyptians:siege": "米吉多（מגדו），公元前1457年。迦南诸王公闭守城中，图特摩斯三世（𓅝𓄟𓋴）命令士兵砍伐果园，在城外环绕修筑一道木墙。整整七个月，无人进出。城内，粮罐见底，孩子们日渐消瘦；城外，由农夫转为士兵的埃及人在酷热中等待。最终，王公们出城投降，并送出儿子作为人质。",
  "egyptians:triumph": "埃巴纳之子雅赫摩斯（𓇹𓄟𓋴），一名来自埃尔卡布城（𓈖𓐍𓃀𓊖）的士兵，约在公元前1520年把自己的生平刻在了墓壁上。他曾在河船上作战，带着俘虏泅水，七次获颁英勇金赏——在全军面前将金苍蝇挂上他的脖子。归乡后，他获赐田地和仆人。他的孙子、书吏帕赫里保存了这段故事，好让家族永不忘记。",
  "egyptians:build": "约公元前2560年，一位名叫梅雷尔的督察为他手下约四十人的队伍记了一本工作日志。这批在瓦迪贾尔夫（وادي الجرف）发现的纸草，记录了他们数月间用船把白色石灰岩从图拉采石场运过泛滥的平原、送往吉萨（الجيزة），用于建造胡夫（𓐍𓅱𓆑𓅱）金字塔。各个工队给自己起了诸如「胡夫之友」之类的名字，吃面包、喝啤酒、吃牛肉，伴着高喊的号子齐力拉动石橇。",
  "egyptians:voyage": "约公元前1470年，五艘船奉哈特谢普苏特（𓄂𓏏𓈙𓊪𓋴𓅱𓏏）之命驶向蓬特之地（𓊪𓅱𓈖𓏏𓈉）。它们沿红海南下数周，直到出现一片满是高脚屋和香树的海岸。代尔巴哈里（الدير البحري）的浮雕描绘了蓬特女王、一袋袋没药、被搬上船的狒狒和乌木，还有装在篮子里的活香树——它们将被种进底比斯（𓌀𓏏𓊖）阿蒙神（𓇋𓏠𓈖）的花园。水手们称蓬特为「神之地」。",
  "egyptians:festival": "当天狼星索普代特（𓋴𓊪𓂧𓏏𓇼）先于太阳升起，新年便开始了：这就是「韦佩特·伦佩特」（𓄋𓊪𓏏𓆳𓏏），即「岁之开启」。不久之后是献给哈托尔（𓉡）的醉酒节。它纪念拉神（𓂋𓂝𓇳𓀭）如何用染红的啤酒骗过暴怒的母狮塞赫迈特（𓋴𓐍𓅓𓏏），让她沉沉睡去，醒来后化为温柔的哈托尔。人们彻夜饮酒，击鼓摇响叉铃，黎明时被唤醒，前来瞻仰女神。",
  "egyptians:games": "在贝尼哈桑（بني حسن）约绘于公元前1900年的岩墓墙壁上，数百对摔跤手相互抓握、举起、摔倒对方，每一个招式都被逐步描绘出来。摔跤既是士兵的训练，也是村民的乐趣。傍晚，人们玩塞尼特棋（𓊃𓈖𓏏𓏠），在三十个方格上移动棋子；后来这种游戏成了灵魂的旅程，图坦卡蒙（𓇋𓏠𓈖𓏏𓅱𓏏𓋹）便带了四副棋盘进入陵墓。",
  "egyptians:drought": "约公元前2150年，尼罗河的洪水一次又一次未能如期到来，莫阿拉（المعلا）的总督安赫提菲在墓中写道：整个上埃及都在饥饿中死去，人们甚至吃掉自己的孩子。他夸耀自己养活了本州百姓，还把粮食分给邻州。无论他的夸耀是否属实，普通农夫都记得那些年月——那是大河遗忘了他们的时候。",
  "egyptians:quake": "公元前27年，一场地震撼动了底比斯（𓌀𓏏𓊖），震裂了阿蒙霍特普三世（𓇋𓏠𓈖𓊵𓏏𓊪）两尊巨大坐像中的一尊。此后每到黎明，这块破裂的石头便会发出奇异的声响，或许是露水受热蒸发所致。希腊和罗马的旅行者称之为门农（Μέμνων）在向母亲黎明女神问好，并在雕像腿上刻下诗句。约公元200年雕像被修复后，它便永远沉寂了。",
  "egyptians:plague": "约公元前1145年去世的拉美西斯五世（𓇳𓄟𓋴𓇓），其木乃伊脸上仍留有脓疱疤痕，这或许是已知最古老的天花迹象。连国王都可能死于此病，村庄自然也难以幸免。疫病流行时，人们向塞赫迈特（𓋴𓐍𓅓𓏏）祈祷——这位母狮女神既降下瘟疫，也能遏止瘟疫；她的瓦布祭司挨家挨户，充当医生和驱魔人。",
  "egyptians:wedding": "想象：在底比斯（𓌀𓏏𓊖）附近的一个村庄里，新娘的家具、亚麻布和铜锅被装上驴背，穿过小巷送往丈夫家。埃及人没有在神庙举行的婚礼；结婚就是搬到一起生活，之后或许会请书吏写一份契约，列明妻子带来的财物，若两人分开，这些仍归她所有。邻居们唱歌拍手，祝愿这对新人多子多孙。",
  "babylonians:siege": "巴比伦（𒆍𒀭𒊏𒆠），公元前650年至前648年。在两位王室兄弟之间的战争中，这座城市被亚述巴尼拔（𒀸𒋩𒆕𒀀）的军队围困。那几个月留下的泥板买卖契约显示，大麦价格涨到了无法企及的地步。一些家庭为求活命卖掉了孩子，书信中提到街头的饥饿与疾病。城破之时，城中的国王死于燃烧的宫殿，幸存者们重新开始生活。",
  "babylonians:triumph": "约公元前1100年，国王尼布甲尼撒一世把马尔杜克（𒀭𒀫𒌓）神像从埃兰迎回——数十年前它被掳到了那里。诗歌描述了神的归来：来自东方的道路，大开的城门，人们哭泣着、歌唱着，看马尔杜克重新进入他的埃萨吉拉神庙（𒂍𒊕𒅍）。对巴比伦人来说，神的缺席意味着混乱；他的归来意味着世界重回正轨。",
  "babylonians:build": "尼布甲尼撒二世写道，他重建马尔杜克（𒀭𒀫𒌓）的大塔庙埃特曼安吉时，亲自背了一筐土，还让儿子们搬运金砖和银砖。成千上万的工人烧制了数百万块砖，砖上印着国王的名字，用沥青砌筑。制砖工一边把黏土压进模子一边歌唱，高塔在平坦的大地上拔地而起。",
  "babylonians:voyage": "希罗多德（Ἡρόδοτος）描述过一种圆形的船：在柳条框架上绷上兽皮，从山区顺幼发拉底河漂流而下直到巴比伦（𒆍𒀭𒊏𒆠）。每条船上载着几桶棕榈酒和一两头驴。到了巴比伦，船员们卖掉货物，拆掉船只卖掉木料，然后把兽皮驮上驴背，步行返回上游再造新船。因为河水只往一个方向流。",
  "babylonians:festival": "尼萨努月（𒌚𒁈），即春季的第一个月，巴比伦（𒆍𒀭𒊏𒆠）庆祝新年阿基图节。一连十一天，祭司们诵读创世史诗《埃努玛·埃利什》（𒂊𒉡𒈠𒂊𒇺）。大祭司掌掴国王的脸颊；如果国王流下眼泪，马尔杜克（𒀭𒀫𒌓）便心满意足。随后，众神的雕像被抬着沿游行大道穿过蓝色琉璃砖的伊什塔尔门，人群夹道观看。",
  "babylonians:games": "公元前177年，一位名叫伊提-马尔杜克-巴拉图的巴比伦书吏写下了乌尔王族局戏（𒋀𒀊𒆠）的规则，而这种游戏那时已有两千多年历史。玩家掷出羊距骨，让棋子沿二十个方格竞速，落在玫瑰花格上会带来好运。泥板甚至把方格与预兆和命运联系起来。从巴比伦（𒆍𒀭𒊏𒆠）到克里特再到印度，都出土过这种棋盘，人们在市集和家中玩它。",
  "babylonians:drought": "在史诗《阿特拉哈西斯》（𒀜𒊏𒄩𒋛）中，众神厌烦了人类的喧闹，降下旱灾：阿达德（𒀭𒅎）扣住雨水，河水不涨，田地因盐碱而发白，人们年复一年地挨饿。巴比伦人知道这不只是故事。每当运河干涸，神庙的粮仓便供养全城，书吏们则记下高昂的粮价。",
  "babylonians:quake": "想象：夜里，巴比伦（𒆍𒀭𒊏𒆠）的大地震动，默尔克斯区一座泥砖房屋的墙壁裂开了。早上，这家人查阅预兆集《舒玛·阿卢》：如果大地在这个月震动，接下来会发生什么？占卜师为国王写下报告，祭司举行「南布尔比」（namburbi）仪式以消解凶兆，这家人则重新砌起破裂的墙。",
  "babylonians:winter": "巴比伦天文学家数百年间坚持写天文日志，每晚记录星辰和行星，也记录天气：雨、风、霜，还有大麦的价格和河水的水位。有些冬天，他们记下了严寒。想象：特贝图月，黎明时椰枣树上结着白霜，一家人挤在烧着棕榈叶的陶火盆旁取暖。",
  "babylonians:plague": "在史诗《埃拉》（𒀭𒀴𒊏）中，瘟疫与战争之神在巴比伦尼亚四处游荡，不分善恶地杀戮，直到他的谋士伊舒姆（𒀭𒄿𒋳）把他安抚下来。巴比伦人把这首诗的诗句抄在小小的泥制护身符上，在瘟疫流行时挂在家中，相信只要家里存有这首诗，瘟神便会绕道而过。一家人守在家中，祈祷埃拉放过他们。",
  "babylonians:wedding": "在巴比伦（𒆍𒀭𒊏𒆠），新郎向新娘的父亲送上聘礼「泰尔哈图」（terhatum），新娘则带着嫁妆出嫁，嫁妆始终归她本人所有。两家设宴庆贺，在一些文献中，新郎还会把油倒在新娘头上。汉谟拉比（𒄩𒄠𒈬𒊏𒁉）的法律保护妻子：如果丈夫无故抛弃她，就必须归还她的嫁妆。想象：她步入新家时，乐师们弹奏着里拉琴。",
  "assyrians:siege": "尼尼微（𒌷𒉌𒉡𒀀），公元前612年。这座当时世上最伟大的城市，城墙周长达十二公里，被巴比伦和米底的军队团团包围。守军坚持了三个月，直到霍斯尔河泛滥，冲垮了部分城墙。城市陷入火海。考古学家在城门处发现了最后一批守军倒下时留下的骸骨。先知那鸿（נחום）记述了尼尼微的陷落，亚述人则哀悼他们失去的城市。",
  "assyrians:triumph": "公元前879年，亚述纳西尔帕二世建成新都卡尔胡（𒆗𒄷），并举行了为期十天的盛宴，一块石碑记录了此事：宾客多达69,574人，其中有工人、外国宾客和城中百姓。他们吃掉了数以千计的绵羊、牛和瞪羚，喝掉了数以千计罐的啤酒和葡萄酒。石碑结尾写道：我给他们饮食，为他们沐浴，让他们平安喜乐地回家。",
  "assyrians:build": "辛那赫里布（𒀭𒌍𒉽𒈨𒌍𒋢）在尼尼微（𒌷𒉌𒉡𒀀）的宫殿浮雕上，描绘了工人用木橇拖运一尊巨大带翼公牛像的场景。数百人拉着绳索，另一些人推动撬杠，监工高声吆喝，一人站在公牛像顶上喊着节拍。辛那赫里布还在杰尔万修建了一座石砌渡槽，把山泉引入城中的花园。他的铭文说，他让尼尼微如群星般璀璨。",
  "assyrians:voyage": "约公元前1900年，来自亚述城（𒀸𒋩𒆠）的商人率领驴队翻山越岭，前往安纳托利亚的卡内什（𒅗𒉌𒅖），驮着锡和羊毛织物。旅程大约需要六周。他们的数千封信件保存至今：留在亚述城纺织布匹的妻子们写信给远方的丈夫，索要白银、打听消息，盼他们早日回家。当卡内什的城墙映入眼帘，这趟旅程便到了终点。",
  "assyrians:festival": "在亚述城（𒀸𒋩𒆠），新年阿基图节时，阿舒尔神（𒀭𒀸𒋩）的雕像被列队抬往城墙外的阿基图神殿，随后又凯旋而归。乐师们弹奏竖琴、敲击鼓，国王身着特制的礼袍。想象：一户乡下人家进城过节，神像经过时，他们正在市集上买面包和无花果。",
  "assyrians:games": "萨尔贡二世在豪尔萨巴德（خورسباد）的王宫里，卫兵们大概常常感到无聊。在城门处巨大带翼公牛像的石座上，刻着二十方格游戏的棋盘——这正是古代近东各地流行的同一种游戏。想象：傍晚，两名卫兵蹲在城门口，掷着羊距骨移动棋子，公牛像在他们头顶静静注视。",
  "assyrians:drought": "想象：尼尼微（𒌷𒉌𒉡𒀀）周边的旱作农田里，大麦全靠冬雨滋养，而雨水已连续第二年没有到来。官员们写信给国王：收成很差，百姓正迁往河边的城镇。王室书信中确实有庄稼歉收和蝗灾的记录，占卜师们向风暴之神阿达德（𒀭𒅎）询问，他是否还会再降下雨水。",
  "assyrians:quake": "亚述学者把天上地下的每一个征兆都写信报告给国王。有一封信报告了一次地震，并依据预兆集解释其含义。想象：在尼尼微（𒌷𒉌𒉡𒀀），一户人家的墙壁裂开，一只陶罐掉落摔碎；第二天，祭司们举行仪式，让凶兆避开国王和国土。",
  "assyrians:winter": "公元前714年，萨尔贡二世率军穿越扎格罗斯山脉，向乌尔米耶湖进发。他写给阿舒尔神（𒀭𒀸𒋩）的长信描述了被冰雪和云雾笼罩的山峰，以及陡峭到士兵们只能手脚并用攀爬的小路。士兵们劈开森林，扛着战车翻越山口。对他们来说，这是寒冷、恐惧，以及望见山下平原之前漫长的等待。",
  "assyrians:plague": "亚述的名年官编年史以一位官员的名字为每一年命名，其中记载了公元前765年亚述城（𒀸𒋩𒆠）发生瘟疫，公元前759年再次暴发。那些年里还发生了叛乱和日食。对亚述城的百姓来说，那是恐惧的岁月：众神发怒了，一家家埋葬亲人，祭司们举行净化仪式。",
  "assyrians:wedding": "中亚述法律记载，新郎家会给新娘的父亲送去礼物，并举行宴会，宴上新郎把油倒在新娘头上，或用盘子端来食物。已婚妇女在街上要戴面纱。想象：在亚述城（𒀸𒋩𒆠）附近的一个村庄里，新娘带着布匹和首饰作嫁妆来到新家，邻居们唱歌击鼓。",
  "sumerians:siege": "乌尔（𒋀𒀊𒆠），约公元前2004年。来自埃兰（𒉏𒈠𒆠）和山地的敌人包围了这座城市，《乌尔哀歌》记下了此后的情景：没有面包，没有啤酒，人们横卧街头，如同干涸池塘里的鱼，母亲抛下了孩子。城墙陷落时，月神南纳（𒀭𒋀𒆠）的神庙燃起大火。诗中，女神宁伽尔（𒀭𒊩𒌆𒃲）为她的城市哭泣，苏美尔人也随她哭泣了一代又一代。",
  "sumerians:triumph": "约公元前2500年制作的乌尔军旗（𒋀𒀊𒆠），一面描绘战争，另一面描绘战后的景象：一场宴会。坐着的男人们举起酒杯，仆人们牵来牛羊、送上鱼，一位乐师弹奏着饰有牛头的里拉琴，一位歌者站在他身旁。对乌尔人来说，胜利就意味着这些：宴席、音乐，以及平安归家。",
  "sumerians:build": "约公元前2125年，拉格什的古地亚（𒉢𒁓𒆷𒆠）为宁吉尔苏神（𒀭𒊩𒌆𒄈𒋢）重建了埃宁努神庙。他的泥筒铭文描述道：全城得到净化，没有人口出恶言，母亲不责骂孩子。古地亚亲手制作了第一块砖，当它完好地脱出模子时，人们欢欣鼓舞。工人们伴着鼓声搬运一筐筐泥土。",
  "sumerians:voyage": "乌尔（𒋀𒀊𒆠）的船只沿海湾南下，前往迪尔蒙（𒉌𒋾𒆠）和马干（𒈣𒃶𒈾𒆠）购买铜。约公元前1750年，一位名叫埃-纳西尔的商人收到一位名叫南尼的顾客写来的愤怒泥板：你给了我劣质的铜，还轻慢了我的信使。这封投诉背后，是一整个海上世界：等待顺风的水手，长满椰枣树的岛屿，还有马干出产铜矿的群山。",
  "sumerians:festival": "乌尔（𒋀𒀊𒆠）每年两次为月神南纳（𒀭𒋀𒆠）举行阿基提节（𒀉𒆠𒋾）。神像乘船前往城外的阿基提神殿，再列队返回，人群带着供品排列在运河两岸。想象：孩子们看着火把照亮的神船缓缓驶过，歌者吟唱着只有神庙乐师才会的颂歌。",
  "sumerians:games": "约公元前2090年，乌尔（𒋀𒀊𒆠）国王舒尔吉（𒀭𒂄𒄀）夸耀说，他在一天之内从尼普尔（𒂗𒆤𒆠）跑到乌尔再跑回来，约160公里，只为在同一天于两座城市庆祝节日。无论真假，苏美尔人都热爱竞技：青铜小像描绘了互相抓住对方腰带的摔跤手，乌尔王陵中还有镶嵌贝壳和青金石的游戏棋盘。",
  "sumerians:drought": "约公元前2020年，随着乌尔（𒋀𒀊𒆠）王国日渐衰弱，大麦变得稀缺。写给国王伊比-辛（𒀭𒄿𒉈𒀭𒂗𒍪）的信中提到，粮价涨到平时的六十倍，还有一位总督只能到遥远的上游去买粮。数百年的灌溉也让田地因盐碱而泛白。城里，人们在神庙粮仓前排起长队，等待领取大麦配给。",
  "sumerians:quake": "想象：一阵震动传遍尼普尔（𒂗𒆤𒆠）城，埃库尔神庙（𒂍𒆳）的泥砖墙上出现了裂缝。祭司们担心风与大地之神恩利尔（𒀭𒂗𒆤）发怒了。面包师和织工离开作坊，跑到街上。事后，神庙得到修缮，人们唱起颂歌来平息神的心。",
  "sumerians:winter": "在苏美尔诗歌《夏与冬》中，兄弟俩埃梅什和恩滕争论谁更有用。冬天恩滕说，是他带来洪水、注满运河，让鱼和鸟繁衍，让羊羔出生。夏天埃梅什则夸耀收获。最终，恩利尔神（𒀭𒂗𒆤）判冬天获胜。想象：寒夜里，农夫们围着火堆听这场辩论。",
  "sumerians:plague": "想象：热病在伊辛城（𒉌𒋛𒅔𒆠）蔓延，一家家把小小的陶狗送到治愈女神宁伊辛娜（𒀭𒊩𒌆𒅔𒋛𒈾）的神庙。狗是她的圣兽，考古学家在她的神庙周围发现了狗的墓葬。医者「阿苏」（asu）配制草药，驱邪师「阿希普」（ashipu）念诵咒语。人们祈求女神派她的狗把疾病赶走。",
  "sumerians:wedding": "苏美尔情歌讲述了伊南娜（𒀭𒈹）和牧人杜姆兹（𒀭𒌉𒍣）的故事：新娘沐浴，戴上珠宝，在门口等候，他带着牛奶和奶油作礼物到来。在普通人家，新郎家把礼物和食物送到新娘家，两家共享宴席。想象：新娘离开父亲的家时，朋友们唱起这些古老的歌。",
  "hittites:siege": "一块赫梯泥板讲述了约公元前1650年围攻乌尔舒（𒌷𒌨𒋗）的经过。国王坐镇营中，围城旷日持久，一拖数月：将军们懈怠，攻城槌坏了，土坡也没有筑完。国王怒斥：你们为何不战？对士兵们来说，这是等待、寒冷和饥饿，还有国王的怒火，直到城市终于陷落。",
  "hittites:triumph": "想象：征战季结束后，大军翻越山口回到哈图沙（𒌷𒄩𒀜𒌅𒊭）。国王首先前往神庙，感谢与他并肩出征的众神，献上面包、啤酒和羊。归来的士兵们在狮子门受到家人迎接，乐师们弹奏里拉琴、敲响鼓，全城欢庆。",
  "hittites:build": "赫梯人在哈图沙（𒌷𒄩𒀜𒌅𒊭）用巨石筑起城墙，城门由石狮和斯芬克斯守卫，城垒下还有一条名为耶尔卡皮的长长石砌隧道。想象：工人们用木橇把石块拖上山坡，唱着歌保持节拍；石匠雕琢着狮子的鬃毛，书吏们清点工人的面包配给。",
  "hittites:voyage": "约公元前1210年，饥荒蔓延赫梯（𒌷𒄩𒀜𒋾）全境，赫梯国王写信给沿海的乌加里特（𐎜𐎂𐎗𐎚）国王：派一艘船，载两千份粮食，运到乌拉港。这是生死攸关的事。想象：在高原上的一个村庄里，人们一连数周等待船只的消息，等待满载粮食的车队翻山而来。",
  "hittites:festival": "普鲁利节（𒁍𒊒𒌌𒇷）是在圣城奈里克（𒌷𒉈𒊑𒅅）举行的春季节日，用来迎接新年。祭司们吟诵风暴神与巨蛇伊卢扬卡（𒈲𒅋𒇻𒅀𒀭𒅗）搏斗的故事：巨蛇先打败了风暴神，女神伊娜拉（𒀭𒄿𒈾𒊏）设宴把巨蛇灌醉，风暴神才得以将它杀死。大地由此更新，节日庆祝的正是丰饶的回归。",
  "hittites:games": "赫梯的节庆文献记载了各种竞技：赛跑、赛马、摔跤和掷石。在某个节日里，青年们赛跑，胜者会得到国王赏赐的一件斗篷。想象：村民们聚集在哈图沙（𒌷𒄩𒀜𒌅𒊭）城外的草地上观看，为自己支持的人欢呼，胜者披着斗篷，骄傲地回家。",
  "hittites:drought": "一则赫梯神话讲述农业之神特利皮努（𒀭𒋼𒇷𒉿𒉡）一怒之下离去。浓雾遮住窗户，炉火窒息，母羊不认羊羔，庄稼不长，神与人都在挨饿。众神四处寻找，最后是一只蜜蜂发现他正在熟睡。每逢旱灾和饥荒，人们便吟诵这则神话，祈求丰饶归来。",
  "hittites:quake": "安纳托利亚自古就是多地震之地。想象：在赫梯腹地的一座小城里，房屋的墙壁摇晃，有些倒塌了。祭司们求问神谕：是哪位神发怒了，又是为什么？他们献上面包和葡萄酒，从羊肝上解读征兆，人们则用石头地基和木构架重建家园。",
  "hittites:winter": "在安纳托利亚中部的高原上，冬季漫长而多雪。赫梯国王会停止征战，回到哈图沙（𒌷𒄩𒀜𒌅𒊭）参加冬季的节庆。想象：白雪覆盖城中的屋顶，一家人围坐在火炉边，烧着木柴和干粪，讲着故事，牛群则在畜栏里取暖。",
  "hittites:plague": "约公元前1320年，国王穆尔西里二世（𒈬𒌨𒅆𒇷）向众神祈祷：瘟疫已在哈梯（𒌷𒄩𒀜𒋾）肆虐了二十年。它是随一场战争的俘虏而来的。他的祷文被记录在泥板上，恳求众神止住死亡。他追问是何罪孽招致此灾，并忏悔了父亲违背誓言之事。每个村庄的人们都与他一同祈祷，等待疫病结束。",
  "hittites:wedding": "赫梯法律中提到「库萨塔」（kusata），即新郎家付给新娘家的聘礼。聘礼付清后，便举行宴席，新娘搬到丈夫家中。想象：在哈图沙（𒌷𒄩𒀜𒌅𒊭）附近的一个村子里，新娘家准备了面包和啤酒，歌手们一路歌唱，送她前往新家。",
  "phoenicians:siege": "公元前332年，推罗（𐤑𐤓）。这座岛城拒绝向亚历山大（Ἀλέξανδρος）打开城门，亚历山大便跨海修筑一条石堤以抵达城下。推罗人奋战了七个月，派出火船焚烧攻城塔，又派潜水者割断锚绳。城墙最终陷落时，数千人丧生，许多人被卖为奴隶。那条石堤至今仍将推罗与陆地相连。",
  "phoenicians:triumph": "想象：一场艰苦的海战之后，船队回到西顿（𐤑𐤃𐤍），帆上满是补丁，整个港口的人都奔向码头。家人们在桨手中寻找熟悉的面孔。船长们把战利品的第一份献给埃什蒙（𐤀𐤔𐤌𐤍）和阿施塔特（𐤏𐤔𐤕𐤓𐤕）。当晚全城设宴，里拉琴和双管笛的乐声从屋顶上飘扬而起。",
  "phoenicians:build": "据《圣经》记载，推罗（𐤑𐤓）王希兰（𐤇𐤓𐤌）送去雪松木和能工巧匠，帮助在耶路撒冷（ירושלים）修建圣殿。工人们在黎巴嫩山中砍伐雪松，把木材拖到海边，扎成木筏，沿海岸漂运。想象：伐木工人一边唱歌，一边看着巨大的树干倒下，滚向大海。",
  "phoenicians:voyage": "据希罗多德（Ἡρόδοτος）记载，约公元前600年，腓尼基水手奉法老尼科二世之命，从红海出发环航非洲。每年秋天他们登岸播种，等到收获后再继续航行。三年后，他们经由赫拉克勒斯（Ἡρακλῆς）之柱返回。他们报告说，向西航行时太阳在他们的右边；希罗多德对此表示怀疑，而这恰恰证明他们确实完成了航行。",
  "phoenicians:festival": "每年春天，推罗（𐤑𐤓）都会庆祝「唤醒节」（ἔγερσις），唤醒城市之主麦勒卡特（𐤌𐤋𐤒𐤓𐤕）。据说这位神会死去又复活：人们焚烧他的偶像，随后将他唤醒。想象：推罗人带着熏香和鹌鹑等祭品挤满神庙庭院，乐师们奏乐，祭司宣告麦勒卡特已经复活。",
  "phoenicians:games": "据《马加比二书》记载，希腊化时代的推罗（𐤑𐤓）每五年举行一次竞技会，以纪念赫拉克勒斯-麦勒卡特（𐤌𐤋𐤒𐤓𐤕），各城都派来使团。想象：推罗青年在海滩上赛跑，在沙地上摔跤，水手们为港口里的赛船下注，胜者手持棕榈枝穿过人群。",
  "phoenicians:drought": "约瑟夫斯（Ἰώσηπος）引用以弗所（Ἔφεσος）的米南德（Μένανδρος）的记载说，推罗（𐤑𐤓）王伊托巴力（𐤀𐤕𐤁𐤏𐤋）在位时曾发生大旱，整整一年滴雨未下，直到国王祈祷后才雷声响起。想象：蓄水池干涸，推罗人等待着从大陆驶来的运水船，妇女们在阿施塔特（𐤏𐤔𐤕𐤓𐤕）神庙中祈祷。",
  "phoenicians:quake": "想象：在比布鲁斯（𐤂𐤁𐤋），一场强烈的地震震裂了古老神庙的墙壁，海水从港口退去，又化作巨浪扑向船只。渔民们奔向高处。事后，人们向城市的女主人巴阿拉特·格巴尔（𐤁𐤏𐤋𐤕 𐤂𐤁𐤋）献祭，并用巨大的石块重建城墙。",
  "phoenicians:winter": "冬天大海是「关闭」的：风暴让航行变得危险，腓尼基的船只都被拖上西顿（𐤑𐤃𐤍）和推罗（𐤑𐤓）的岸边。想象：水手们整个冬天修补船帆和绳索，用沥青填塞船壳的缝隙，讲述远方港口的故事，等待春天大海重新开放，船队再次驶向塞浦路斯和迦太基（𐤒𐤓𐤕𐤇𐤃𐤔𐤕）。",
  "phoenicians:plague": "西顿（𐤑𐤃𐤍）附近矗立着治愈之神埃什蒙（𐤀𐤔𐤌𐤍）的神庙，庙中的水池由一眼圣泉供水。病人来此沐浴，父母们则留下孩子的石像，以感谢神让孩子痊愈。想象：瘟疫流行时，一家家人挤在神庙的水池边向埃什蒙祈祷，祭司们则吟唱并焚香。",
  "phoenicians:wedding": "想象：在推罗（𐤑𐤓），新郎家把紫色布料和白银作为礼物送到新娘家。新娘戴着金耳环和玻璃珠项链，在乐声中被送往新家。腓尼基妇女佩戴精美繁复的首饰。新人向阿施塔特（𐤏𐤔𐤕𐤓𐤕）和巴力（𐤁𐤏𐤋）祈求多子多孙，在海边过上平安的生活。",
  "palmyrans:siege": "公元272年，奥勒良（Aurelianus）的军队包围了帕尔米拉（𐡶𐡣𐡬𐡴）。粮食日渐短缺，女王芝诺比娅（𐡡𐡶𐡦𐡡𐡩）骑着快骆驼悄悄出城，奔向幼发拉底河（Εὐφράτης），希望搬来救兵，却在河边被擒。城市打开了城门。对帕尔米拉人来说，那几个星期意味着恐惧、饥饿，以及等待皇帝如何处置他们。",
  "palmyrans:triumph": "想象：商队护卫在一场与沙漠劫匪的战斗中获胜归来，骆驼上满载着夺回的货物。商人们在柱廊中为他们立像，并刻下铭文表彰他们的首领。当晚全城设宴，有乐师和舞者助兴，一家家人聚在宴会厅里庆祝平安。",
  "palmyrans:build": "公元32年，帕尔米拉（𐡶𐡣𐡬𐡴）人为宏伟的贝尔（𐡡𐡫）神庙举行献殿，神庙的柱子由金黄色的石灰岩砌成。工匠们从附近的采石场开采石料，石雕匠雕出柱头和饰带，上面刻着骆驼、神祇和祭品。想象：工人们一边唱歌，一边用木制起重机吊起石块，孩子们在阴凉处观看。",
  "palmyrans:voyage": "帕尔米拉的商队穿越沙漠抵达幼发拉底河（Εὐφράτης），再顺流而下到达海湾边的卡拉克斯（Χάραξ），有些人还继续乘船前往印度。铭文表彰了像索阿多斯这样保护商人的商队首领。想象：在沙漠中跋涉数周之后，商队望见了绿洲的棕榈林，全城的人都出来迎接他们。",
  "palmyrans:festival": "在尼散月（𐡮𐡩𐡯𐡭），帕尔米拉（𐡶𐡣𐡬𐡴）以游行和献祭庆祝贝尔（𐡡𐡫）节。人们以宴饮团体「马尔泽亚」（𐡬𐡴𐡦𐡧𐡠）为单位聚会，以小小的陶制筹码作为赴宴的入场券。想象：宾客们斜倚在神庙庭院的卧榻上吃喝，乐师奏乐，祭司焚香献祭。",
  "palmyrans:games": "想象：在一个节日里，帕尔米拉（𐡶𐡣𐡬𐡴）的青年们在城外商队聚集的平原上赛马、赛骆驼。帕尔米拉的弓箭手和骑手闻名遐迩，人群在城墙上欢呼。胜者获得一顶棕榈叶编成的冠冕，他的家人则邀请邻居们赴宴。",
  "palmyrans:drought": "帕尔米拉（𐡶𐡣𐡬𐡴）的生计仰赖埃夫卡泉（𐡠𐡱𐡳𐡠），这眼泉水由亚尔希博尔神（𐡩𐡴𐡧𐡡𐡥𐡫）守护。想象：在干旱之年，泉水减少，园圃枯萎。人们在泉边祈祷焚香，商队从幼发拉底河（Εὐφράτης）运来粮食，一家家人定量用水，等待冬雨降临。",
  "palmyrans:quake": "想象：一场地震撼动了帕尔米拉（𐡶𐡣𐡬𐡴），柱廊的一些柱子倒在街上。人们惊恐地冲出家门。事后，石匠们重新开工，竖起倒下的柱子，修复神庙，祭司们则献祭以平息众神之怒。",
  "palmyrans:plague": "约公元165年，一场大瘟疫——安东尼瘟疫——席卷了罗马帝国东部。想象：在帕尔米拉（𐡶𐡣𐡬𐡴），疫病随商队而来，一家家人将死者葬入城外的塔墓，墓中死者的雕像肖像凝望着外面。幸存的人们向贝尔（𐡡𐡫）和亚尔希博尔（𐡩𐡴𐡧𐡡𐡥𐡫）祈祷，祈求全城安康。",
  "palmyrans:wedding": "想象：一位帕尔米拉新娘戴着金耳环、项链和面纱，就像城中墓葬肖像里的妇女那样，被送往丈夫家。两家签下婚约，举行宴席。乐师奏乐，宾客歌唱，祝愿新人长寿、多子多孙。",
  "minoans:siege": "想象：约公元前1450年的克诺索斯（𐀒𐀜𐀰）。王宫没有高大的城墙，大海一向是它的屏障。如今，地平线上出现了无人认得的船只，海岸沿线燃起大火。一家家人带着油罐和孩子躲进山里，王宫中堆满巨大陶瓮的古老储藏室被抛在身后。等他们回来时，王宫已被焚毁。",
  "minoans:triumph": "锡拉岛（Θήρα）阿克罗蒂里（Ακρωτήρι）出土的《船队壁画》描绘了一支船队驶入港城的情景。人们从窗口和屋顶探身观看，海豚在船边跃起，船只装饰着花环。无论是远航归来还是凯旋，这都是一幅归乡的画面。想象：母亲们奔向码头，全岛庆祝船队平安归来。",
  "minoans:build": "考古学家在克诺索斯（𐀒𐀜𐀰）的石块上发现了刻下的记号：双斧、星形和三叉戟，可能是不同工匠队的标志。王宫有采光井、楼梯、排水道和彩绘墙壁。想象：石匠从山中开采石膏，木匠安装上粗下细的木柱，工人们一边唱歌，一边把石块拖到位。",
  "minoans:voyage": "在底比斯的埃及维西尔雷赫米尔墓中，来自凯夫提乌（很可能就是克里特（Κρήτη））的人们捧着礼物：高大的来通杯、铜锭和彩饰花瓶。他们借着北风横渡开阔的大海，航行五天或更久才抵达埃及。想象：一个年轻水手第一次看到尼罗河三角洲，惊叹于这片没有山的土地。",
  "minoans:festival": "在约公元前1500年的阿吉亚·特里亚达（Αγία Τριάδα）《收获者瓶》上，一群男子肩扛农具列队行进，张口高歌。其中一人摇着叉铃，有些人似乎在大笑。这是古代艺术中最欢乐的场景之一：一场丰收节，一支歌唱的农夫队伍，庆祝繁重劳作的结束。",
  "minoans:games": "克诺索斯（𐀒𐀜𐀰）的《跳牛壁画》描绘了一名青年在冲来的公牛背上翻筋斗，另外两人从旁协助，其中一人抓住牛角。印章石和青铜像上也有同样大胆的跳跃。无论是体育还是神圣仪式，这都是岛上最盛大的竞技，当公牛低下头时，观众都屏住了呼吸。",
  "minoans:drought": "想象：干燥的冬天之后又是干燥的夏天，梅萨拉（Μεσαρά）平原的泉水日渐减少。王宫储藏室里盛满粮食和橄榄油的巨大陶瓮成了全岛的希望。官员们用线形文字A在泥板上记录配给，人们则攀上山顶圣所，留下小小的陶塑，祈求降雨。",
  "minoans:quake": "约公元前1600年，锡拉岛（Θήρα）火山爆发，这是人类历史上最猛烈的喷发之一。在阿克罗蒂里（Ακρωτήρι），此前的地震已向居民发出警告，他们离开了：被掩埋的城镇里没有发现一具遗体，只有火山灰下的床铺、陶罐和彩绘墙壁。海浪和火山灰波及克里特（Κρήτη），岛上的世界从此再也不复从前。",
  "minoans:winter": "想象：伊达山（Ἴδη）和白山（Λευκά Όρη）的山顶积着雪，风暴封闭了大海。船只被拖上海滩，水手们留在家中。村子里，一家人围坐在炉火旁，纺织羊毛，压榨最后一批橄榄，讲述公牛和山之女神的故事。",
  "minoans:plague": "一份现藏伦敦的埃及医学纸草书中，记有一段对抗「亚洲病」的咒语，用凯夫提乌语写成，而凯夫提乌正是埃及人对克里特（Κρήτη）的称呼。这是我们所知极少数的米诺斯语词汇之一。想象：在一座克里特小镇里，一位治疗者对着患病的孩子吟诵这段咒语，母亲在门边守候。",
  "minoans:wedding": "想象：一位米诺斯新娘身穿荷叶边长裙，佩戴金饰，被送往丈夫家，妇女们围成圆圈起舞，一位里拉琴手走在前面。壁画中的妇女身着节日盛装，在橄榄林中跳舞。两家人享用葡萄、橄榄、鱼和蜂蜜，并举起葡萄酒为新人祝酒。",
  "greeks:siege": "公元前429年至公元前427年，普拉提亚（Πλάταια）。这座小城被斯巴达人（Σπαρτιᾶται）和底比斯人（Θηβαῖοι）修筑的双层围墙团团围住。在一个暴风雨的冬夜，约两百名普拉提亚人（Πλαταιεῖς）借梯子翻越围墙出逃，每人只在左脚穿鞋，以便在泥地里站稳。其余的人坚守到饥饿迫使他们投降。修昔底德（Θουκυδίδης）满怀哀伤地讲述了这个故事。",
  "greeks:triumph": "公元前480年萨拉米斯（Σαλαμίς）海战之后，人们举行了庆祝胜利的典礼。据说年少的索福克勒斯（Σοφοκλῆς）当时还是个孩子，他赤身涂油，手持里拉琴，领着少年合唱队高唱凯歌。对希腊人（Ἕλληνες）而言，这是欢乐，也是如释重负：家园、神庙和亲人都保全了下来。",
  "greeks:build": "约公元前530年，墨伽拉（Μέγαρα）的工程师欧帕里诺斯（Εὐπαλῖνος）在萨摩斯岛（Σάμος）凿穿一座山，开凿隧道为城市引水。两队人马从两侧同时开工，在中间会合，隧道全长一千多米，偏差却很小。希罗多德（Ἡρόδοτος）称之为希腊人（Ἕλληνες）最伟大的工程之一。想象：两队人听到对方的锤声时，欢呼起来。",
  "greeks:voyage": "约公元前631年，饱受干旱之苦的锡拉岛（Θήρα）人得到德尔斐（Δελφοί）神谕，要他们去利比亚（Λιβύη）建城。两船年轻人抽签后向南航行。起初他们失败了，想要返回家乡，却被人用石头赶了回去。他们再次尝试，在山中找到一眼泉水，并在那里建立了昔兰尼（Κυρήνη）。",
  "greeks:festival": "在酒神狄俄尼索斯（Διόνυσος）的春季节日花月节（Ἀνθεστήρια）上，人们打开新酒的酒坛。三岁的孩子头戴花冠，得到一种叫「科埃斯」的小酒壶，壶上画着孩子们游戏的图案。成年人举行饮酒比赛。在节日的最后一天，人们相信亡灵会出来游荡，于是在门上涂抹沥青。",
  "greeks:games": "公元前448年，奥林匹亚（Ὀλυμπία）。罗得岛（Ῥόδος）的狄亚戈拉斯（Διαγόρας）本人就是伟大的奥运拳击手，此刻他看着两个儿子双双夺冠。儿子们把他扛在肩上穿过人群，一个斯巴达人（Σπαρτιάτης）高喊：「现在就死吧，狄亚戈拉斯，因为你永远登不上奥林匹斯山（Ὄλυμπος）。」这些竞技只为荣誉：奖品不过是一顶野橄榄枝编成的冠冕。",
  "greeks:drought": "埃伊纳岛（Αἴγινα）的人们传说，一场大旱袭击了整个希腊，神谕说只有最虔诚的埃阿科斯（Αἰακός）才能结束它。他登上山顶向宙斯（Ζεύς）祈祷，于是大雨降临。那座山顶上建有一座宙斯圣所。想象：每逢旱年，农夫们带着祭品登山，望着山顶上空是否有云。",
  "greeks:quake": "公元前373年的一个冬夜，地震袭击了科林斯（Κόρινθος）湾畔的赫利刻（Ἑλίκη），海水吞没了全城，无一人幸存。此后数百年间，旅人们都说能看到水下的废墟，还有波塞冬（Ποσειδῶν）的青铜像依然矗立在海底，钩住渔民的渔网。",
  "greeks:winter": "农民诗人赫西俄德（Ἡσίοδος）告诫人们提防勒奈翁月（Ληναιών）：这是剥牛皮般的恶劣日子，北风从色雷斯（Θρᾴκη）吹来，在海上咆哮。「无骨者」在没有炉火的家中啃着自己的脚。他说，待在屋里吧，穿上柔软的斗篷和长长的束腰外衣，用衬了毛毡的牛皮做凉鞋。",
  "greeks:plague": "保萨尼亚斯（Παυσανίας）记载，阿卡迪亚（Ἀρκαδία）的菲伽利亚（Φιγάλεια）人在巴赛（Βάσσαι）为救助者阿波罗（Ἀπόλλων Ἐπικούριος）建造了一座神庙，因为他曾将他们从瘟疫中拯救出来。这座神庙至今仍矗立在山上。想象：疫病流行时，一家家人带着祭品攀上山坡，一边唱着献给阿波罗的颂歌，云朵在他们脚下飘过。",
  "greeks:wedding": "婚礼当天，希腊新娘要用一种叫「洛特罗弗罗斯」的高罐从圣泉取水沐浴。宴席过后，新郎握住她的手腕，在火炬光中用马车将她接回家，朋友们唱着婚歌。到了门口，她要吃一个榅桲或一颗枣，宾客们则抛撒坚果和干果。",
  "athenians:siege": "公元前405年至公元前404年，雅典（Ἀθῆναι）。舰队在羊河（Αἰγὸς ποταμοί）覆没之后，斯巴达战船封锁了比雷埃夫斯（Πειραιεύς），雅典遭到海陆围困。色诺芬（Ξενοφῶν）描述人们忍饥挨饿，许多人饿死在街头。城市投降后，长墙（Μακρὰ Τείχη）在吹笛女的乐声中被拆毁，胜利者宣称希腊（Ἑλλάς）的自由从此开始。",
  "athenians:triumph": "公元前490年，马拉松（Μαραθών）。雅典人（Ἀθηναῖοι）在平原上击败波斯军队，随即当天行军返回雅典（Ἀθῆναι）保卫城市。传说一名跑者赶到集市广场，说了一句「欢庆吧，我们胜利了」，便倒地身亡。192名雅典阵亡者被葬在战场上的一座土丘中，土丘至今犹存。埃斯库罗斯（Αἰσχύλος）希望自己的墓碑上只写他曾在那里作战。",
  "athenians:build": "普鲁塔克（Πλούταρχος）描述了建造帕特农神庙（Παρθενών）的各行各业：木匠、雕塑家、铜匠、石匠、染工、金匠、象牙匠、画师和筑路工。厄瑞克忒翁神庙（Ἐρέχθειον）的铭文列出了工人名单，公民、外邦人和奴隶都在其中，每人每天的工钱都是一德拉克马。想象：凿子敲击彭特利孔大理石的声音响彻全城。",
  "athenians:voyage": "公元前415年，舰队启航远征西西里（Σικελία）。修昔底德（Θουκυδίδης）描述黎明时分全城的人都来到比雷埃夫斯（Πειραιεύς）送行。号角响起，示意肃静，众人高唱凯歌，水手们用金杯银杯洒酒祭神。随后战船竞相驶向埃伊纳（Αἴγινα）。这些船中能回来的寥寥无几，而那个清晨的希望一直留在人们的记忆里。",
  "athenians:festival": "每四年一次的大泛雅典娜节（Παναθήναια τὰ μεγάλα）上，雅典（Ἀθῆναι）少女们织成的一件新长袍「佩普洛斯」，被送到卫城（Ἀκρόπολις）上的雅典娜（Ἀθηνᾶ）神像前。游行队伍中有骑手、战车、手持橄榄枝的长者，还有提着篮子的少女。帕特农神庙（Παρθενών）的饰带浮雕描绘的正是这支队伍，全城的人都参与其中。",
  "athenians:games": "在泛雅典娜竞技会上，胜者的奖品是来自雅典娜（Ἀθηνᾶ）圣树的橄榄油，盛在彩绘的大双耳罐里，罐的一面画着女神，另一面画着比赛项目。一位战车赛冠军可以得到140罐。夜里还有火炬赛跑，各队接力传递火种，奔向祭坛。",
  "athenians:drought": "公元前330年至公元前326年间，雅典（Ἀθῆναι）和希腊（Ἑλλάς）大部分地区遭遇粮荒。昔兰尼（Κυρήνη）的一块石刻铭文列出了它运粮接济的城市，雅典名列榜首。以低价运来粮食的雅典商人被授予冠冕以示表彰。想象：一家家人在比雷埃夫斯（Πειραιεύς）的粮市排队，眺望着海平线上是否有船驶来。",
  "athenians:quake": "修昔底德（Θουκυδίδης）写道，公元前431年伯罗奔尼撒战争（Πελοποννησιακὸς πόλεμος）爆发前夕，圣岛提洛（Δῆλος）发生了地震，这是人们记忆中的第一次。负责照管岛上阿波罗（Ἀπόλλων）圣所的雅典人（Ἀθηναῖοι）认为，这是灾难将至的征兆。想象：祭司和朝圣者聚集在震过的岛上，猜不透神想说什么。",
  "athenians:winter": "公元前432年波提狄亚（Ποτείδαια）的冬季围城战中，天气冷得可怕。士兵们用毛毡和羊皮裹住双脚。阿尔基比亚德斯（Ἀλκιβιάδης）后来讲述，苏格拉底（Σωκράτης）只穿着平常的斗篷，赤脚走在冰上，比穿鞋的人走得还要轻松。士兵们不知道该钦佩他，还是该怨恨他。",
  "athenians:plague": "公元前430年，正当乡下人挤进城墙之内时，雅典（Ἀθῆναι）爆发了瘟疫。修昔底德（Θουκυδίδης）本人也染上此病并幸存下来，他描述了高烧、干渴以及横陈在神庙中的死者。人们不再顾及法律或神明。伯里克利（Περικλῆς）也死于这场瘟疫。这是历史上对一场流行病最生动的记述之一。",
  "athenians:wedding": "雅典人（Ἀθηναῖοι）喜欢在献给赫拉（Ἥρα）的伽墨利昂月（Γαμηλιών）结婚。婚礼前夜，新娘把自己的玩具和一绺头发献给阿尔忒弥斯（Ἄρτεμις）。宴席之后，送亲队伍在火炬光中把她送往新家，由新娘的母亲手持火炬。第二天，两家人送来结婚礼物，称为「埃保利亚」。",
  "spartans:siege": "公元前425年，斯法克特里亚（Σφακτηρία）。四百二十名斯巴达人（Σπαρτιᾶται）被困在一座小岛上，四周是雅典舰队。希洛人趁夜游水，带来混有蜂蜜和亚麻籽的罂粟籽袋子为他们送粮。七十二天后，在四面围攻之下，292名幸存者投降。整个希腊（Ἑλλάς）为之震惊：从没有人想到斯巴达人会投降。",
  "spartans:triumph": "普鲁塔克（Πλούταρχος）说，斯巴达人（Σπαρτιᾶται）靠计谋取胜时，会向阿瑞斯（Ἄρης）献祭一头牛；而在正面交战中获胜，只献一只公鸡：他们认为战场取胜不过是本分。想象：战斗结束后，士兵们回到家中，妇女和老人迎接他们，却没有喧闹的庆祝。",
  "spartans:build": "普鲁塔克（Πλούταρχος）写道，斯巴达的法律规定，建房时屋顶只能用斧头，门只能用锯子，这样就没有人会贪图奢华。数百年间斯巴达（Σπάρτη）都没有城墙；人们说，斯巴达的城墙就是它的男人。想象：邻居们互相帮忙，用木梁和土墙搭起一座简朴的房子。",
  "spartans:voyage": "约公元前706年，一群被称为「帕特尼埃」（Παρθενίαι）的斯巴达（Σπαρτιᾶται）青年——他们生于一场漫长的战争期间，未获完整的公民权——向西航行，在意大利南部建立了塔拉斯城（Τάρας）。神谕告诉他们，要在看到晴空落雨的地方定居。首领睡着时，他的妻子伏在他头上哭泣，泪水落下，他便明白：就是这里了。",
  "spartans:festival": "阿波罗（Ἀπόλλων）的节日卡尔涅亚节（Κάρνεια）对斯巴达人（Σπαρτιᾶται）而言极其神圣，节日结束前他们绝不出兵作战。这就是他们迟到马拉松（Μαραθών）的原因。节日期间，青年们追逐一个戴着花环的跑者；如果追上了，就是城邦的好兆头。人们搭起帐篷，共享餐食。",
  "spartans:games": "公元前396年，斯巴达国王的女儿库尼斯卡（Κυνίσκα）凭借她的四马战车，成为第一位在奥林匹亚（Ὀλυμπία）获胜的女性。女性不能亲自参赛，但奖项归马车的主人所有。她的铭文写道：「在全希腊（Ἑλλάς）的女性中，唯有我赢得了这顶冠冕。」斯巴达女孩也赛跑和摔跤，这在希腊很不寻常。",
  "spartans:drought": "想象：在一个干旱的夏天，欧罗塔斯河（Εὐρώτας）缩成一道细流，在拉科尼亚（Λακωνική）田间劳作的希洛人（εἵλωτες）艰难地收割庄稼。公共食堂「叙西提亚」仍须照常供给。一家家人在泰格托斯山（Ταΰγετος）上向宙斯（Ζεύς）祈祷，长老们则派人去德尔斐（Δελφοί）问神意。",
  "spartans:quake": "公元前464年，一场大地震摧毁了斯巴达（Σπάρτη）。普鲁塔克（Πλούταρχος）说全城只剩五座房屋屹立。正在体育场锻炼的青年在体育场倒塌时遇难。国王阿希达穆斯（Ἀρχίδαμος）召集公民拿起武器，起事的希洛人（εἵλωτες）发现斯巴达人（Σπαρτιᾶται）早已严阵以待。这场灾难使斯巴达元气大伤，持续了一代人之久。",
  "spartans:winter": "普鲁塔克（Πλούταρχος）描述了接受训练的斯巴达男孩：一年只有一件斗篷，不穿鞋，睡在用手从欧罗塔斯河（Εὐρώτας）边拔来的芦苇铺成的床上，不许用刀。冬天他们在芦苇里掺进蓟花绒来保暖。想象：男孩们在寒冷的营房里，躺在芦苇床上瑟瑟发抖，饥肠辘辘，学着忍耐。",
  "spartans:plague": "想象：当高烧在营地士兵中蔓延时，斯巴达人（Σπαρτιᾶται）向阿波罗（Ἀπόλλων）和阿斯克勒庇俄斯（Ἀσκληπιός）祈祷，病人由战友们照料。斯巴达人以默默忍受痛苦为荣。城里的母亲们等待着消息，准备好听到最坏的结果，也不在人前落泪。",
  "spartans:wedding": "普鲁塔克（Πλούταρχος）描述了斯巴达的婚礼：新娘的头发被剪短，穿上男人的斗篷和凉鞋，独自躺在黑暗中的草垫上。新郎从公共食堂过来，与她短暂相处，然后回去和战友们一起睡觉。很长一段时间里，夫妻只能偷偷相会，有时孩子都生了，还没在白天见过彼此。",
  "macedonians:siege": "公元前316年，皮德纳（Πύδνα）。亚历山大（Ἀλέξανδρος）的母亲奥林匹娅丝（Ὀλυμπιάς）带着家眷和士兵被困城中，卡山德（Κάσσανδρος）围城整整一个冬天。粮食吃光了：士兵们吃掉自己的马，大象被喂以木屑而死，人们饿死在街头。到了春天，城镇投降。狄奥多罗斯（Διόδωρος）讲述了这个故事。",
  "macedonians:triumph": "公元前324年，克拉特鲁斯（Κρατερός）率领约一万名亚历山大（Ἀλέξανδρος）军中的老兵返回马其顿（Μακεδονία）。他们从佩拉（Πέλλα）出发，一路行军到印度又折返，历时十余年。想象：在各个村庄里，等待了十年的母亲和妻子在一张张白发苍苍的面孔中寻找亲人，听他们讲述波斯、大象和世界尽头的故事。",
  "macedonians:build": "公元前331年亚历山大（Ἀλέξανδρος）建立亚历山大城（Ἀλεξάνδρεια）时，建筑师狄诺克拉底（Δεινοκράτης）没有白垩来标出城市规划，便用大麦粉代替。成群的鸟儿飞下来把它吃光了。占卜者说，这预示着这座城市将养活许多民族。想象：工人们挖着第一批沟渠，笑看鸟群，城市的街道渐渐成形。",
  "macedonians:voyage": "公元前325年，尼阿库斯（Νέαρχος）率领舰队从印度河口出发，沿着荒凉的海岸驶向波斯湾。他们遭遇了鲸鱼、海岸边的「食鱼人」，还有饥饿。当尼阿库斯终于见到亚历山大（Ἀλέξανδρος）时，他和部下又瘦又黑，国王竟没认出他们，看到他们还活着，不禁落泪。",
  "macedonians:festival": "每年春天，马其顿军队都要庆祝洁净节「克珊迪卡」（Ξανδικά）。全军从一条被献祭的狗的两半尸体之间行军穿过，随后举行模拟战斗和赛跑。想象：士兵们手持木制兵器互相冲杀，又笑又喊，新的征战季节就此开始。",
  "macedonians:games": "普鲁塔克（Πλούταρχος）记载，公元前356年亚历山大（Ἀλέξανδρος）出生那天，腓力（Φίλιππος）一连收到三个好消息：一位将军打了胜仗，他的赛马在奥林匹克运动会上夺冠，他的儿子降生了。想象：在佩拉（Πέλλα），年轻人在平原上赛马，模仿那位奥林匹克冠军。",
  "macedonians:drought": "想象：干旱之年，佩拉（Πέλλα）和埃迦伊（Αἰγαί）周围的马其顿平原一片枯黄，牧人早早把羊群赶上山间牧场。农民向宙斯（Ζεύς）和得墨忒耳（Δημήτηρ）祈祷，国王从王家粮仓调拨粮食，家家户户省着面包过日子。",
  "macedonians:quake": "想象：一场地震撼动埃迦伊（Αἰγαί），房屋的墙壁开裂。山上的牧人看见山石滚落、羊群受惊。事后，人们向撼地之神波塞冬（Ποσειδῶν）献祭，用石头和木材重建家园，彼此帮忙把沉重的梁木抬回原处。",
  "macedonians:winter": "公元前329年，亚历山大（Ἀλέξανδρος）的大军冒雪翻越兴都库什山。士兵们断了粮，又没有柴火生火，只得生吃驮畜。有人雪盲，有人冻死。想象：一名远离家乡的马其顿士兵在一小堆火边暖手，想起村里自家的炉火。",
  "macedonians:plague": "想象：炎热时节，热病在巴比伦的军营中蔓延，士兵们病倒在帐篷里。医生给他们用草药和葡萄酒，士兵们向阿斯克勒庇俄斯（Ἀσκληπιός）祈祷。远在马其顿（Μακεδονία）的家人要等上好几个月才有消息，不知道谁还活着。",
  "macedonians:wedding": "希波洛科斯（Ἱππόλοχος）描述过一位名叫卡拉诺斯（Κάρανος）的马其顿人的婚宴：二十位宾客每人得到银杯、金冠和满盘的菜肴，还有吹笛女和舞者助兴。想象：在一场乡村婚礼上，两家人同享羊肉和美酒，宾客们跳舞直到深夜。",
  "romans:siege": "约公元前390年，高卢人攻占罗马（Roma），最后的守军只守住卡比托利欧山（Capitolium）。他们饿了几个月，眼看着山下的城市燃烧。一天夜里，高卢人悄悄攀上悬崖，而朱诺（Iuno）的圣鹅——尽管饥荒也没有被吃掉——开始嘎嘎大叫、拍打翅膀。马库斯·曼利乌斯惊醒，把第一个爬上来的敌人推了下去。罗马人（Romani）把这些鹅记了好几百年。",
  "romans:triumph": "罗马凯旋式：将军乘四马战车穿城而过，脸涂成红色，身披朱庇特（Iuppiter）的紫色托加袍。俘虏、缴获的财宝和描绘战役的图画走在他前面。他身后是行进的士兵，像凯撒的部下那样唱着取笑自家统帅的粗俗歌谣，好让他保持谦逊。游行队伍最后抵达朱庇特神庙。",
  "romans:build": "哈德良（Hadrianus）长城始建于公元122年，修筑者是军团士兵，而非奴隶。沿着长城，一块块刻字的小石头记录着每一段是由哪个百人队修的：「某某百人队筑此」。想象：远离家乡的士兵们冒雨切石砌墙，一边说笑一边抱怨，百夫长丈量着工程，长城在群山间延伸。",
  "romans:voyage": "琉善（Λουκιανός）描述过运粮船「伊西斯号」，约公元150年被风吹离航线，漂到了比雷埃夫斯（Πειραιεύς）：船长如神庙，载的粮食足够雅典（Ἀθῆναι）吃上一年。这样的船通常从亚历山大里亚（Ἀλεξάνδρεια）驶往罗马（Roma），要在海上航行数周。想象：水手们眺望奥斯蒂亚的大灯塔，当灯火出现在地平线上时，他们欢呼起来。",
  "romans:festival": "十二月的农神节上，罗马（Roma）一切颠倒过来。人人戴上被释奴隶的毡帽，主人在餐桌旁服侍奴隶，人们公开赌博，互赠蜡烛和小陶俑作礼物。街上回荡着「io Saturnalia！」的欢呼。塞涅卡抱怨全城都陷入了疯狂，普林尼（Plinius）则躲进一间安静的屋子。",
  "romans:games": "盖乌斯·阿普列尤斯·狄奥克勒斯是来自卢西塔尼亚的战车手，公元2世纪时驰骋赛场二十四年。他的铭文记载他出赛4257场，获胜1462场，赢得的奖金堪称巨富。在大竞技场，二十五万观众为各自支持的颜色呐喊：红队（russata）、白队（albata）、绿队（prasina）或蓝队（veneta），有些人甚至对敌对车手下诅咒。",
  "romans:drought": "公元前22年，洪水和疫病之后，饥荒降临罗马（Roma）。运粮船队迟迟未到，饥饿的民众挤满了城市。奥古斯都接管了粮食供应，自掏腰包购粮。对普通罗马人（Romani）来说，每月的配给粮就是生与饿的分界线，每一次延误都切身可感。",
  "romans:quake": "公元79年8月24日，维苏威火山爆发。小普林尼（Plinius Minor）在海湾对岸的米塞努姆目睹了这一切，形容那团烟云形如一棵伞松。他的舅舅驾船驶向险境去救朋友，死在了海滩上。庞贝和赫库兰尼姆被掩埋，炉中还有面包，墙上还有涂鸦，直到18世纪才重见天日。",
  "romans:winter": "李维（Livius）记载，约公元前398年有一个可怕的冬天：道路被大雪封堵，台伯河（Tiberis）冻得结结实实，无法行船。许多牲畜死去，第二年又暴发了疾病。想象：一家人挤在小屋里围着火盆取暖，孩子们在冰封的河面上滑冰。",
  "romans:plague": "公元165年，从东方归来的士兵带回一场瘟疫，如今认为是天花。医生盖伦（Γαληνός）记述了发热、黑色皮疹和腹泻。它在帝国各地蔓延多年；在罗马（Roma），一天就有数千人死去。人们在门上写下阿波罗的护佑诗句，而盖伦一边尽力救治，一边把所见的一切都记了下来。",
  "romans:wedding": "罗马新娘披着火焰色的面纱，叫作flammeum，头发要用矛尖分开。新人右手相握。傍晚，一支队伍举着火把、吹着笛子，送她去丈夫家，宾客们高喊「Talassio！」并抛撒坚果。到了门口，她给门柱涂油，丈夫抱她跨过门槛。",
  "carthaginians:siege": "迦太基（𐤒𐤓𐤕𐤇𐤃𐤔𐤕），公元前149年至公元前146年。在罗马人的围困下，人们日夜打造兵器；妇女剪下头发，为投石机编绳。三年后，罗马人攻入城中，挨家挨户巷战了六天。最后，统帅的妻子看见丈夫投降，便带着孩子们投身于燃烧的神庙火焰之中。",
  "carthaginians:triumph": "公元前216年坎尼之战后，汉尼拔（𐤇𐤍𐤁𐤏𐤋）的弟弟马戈（𐤌𐤂𐤍）乘船回到迦太基（𐤒𐤓𐤕𐤇𐤃𐤔𐤕）。在议事会上，他倒出一大堆从阵亡罗马骑士手上取下的金戒指，多到要用斗来量。想象：消息传遍港口和市场，在海外作战的士兵家属设宴庆贺，盼着儿子们回家。",
  "carthaginians:build": "迦太基（𐤒𐤓𐤕𐤇𐤃𐤔𐤕）的港口堪称奇观：一座长方形的商港，后面是一座圆形军港，中央有一座小岛。阿庇安（Ἀππιανός）记载那里的船棚可容纳220艘战舰，每座船棚都有立柱，看上去就像一道柱廊。想象：工人们挖掘港池、用石块砌岸，唱着歌打节拍，造船匠们等着开工造船。",
  "carthaginians:voyage": "约公元前500年，汉诺（𐤇𐤍𐤀）率六十艘船从迦太基（𐤒𐤓𐤕𐤇𐤃𐤔𐤕）出发，驶出赫拉克勒斯之柱（Ἡρακλέους στῆλαι），沿西非海岸南下建立殖民地。他的记述讲到满是鳄鱼的河流、一座夜里燃烧的山——他们称之为「众神之车」（Θεῶν Ὄχημα），还有浑身长毛的野人，译员称之为「大猩猩」。这次航行比此前任何一次都走得更远。",
  "carthaginians:festival": "想象：在迦太基（𐤒𐤓𐤕𐤇𐤃𐤔𐤕）守护女神塔尼特（𐤕𐤍𐤕）的节日里，一家家人登上神庙，献上香、水果和小陶俑。乐师们敲着手鼓、吹着双管笛，商人们挤满港口附近的市场，叫卖紫色布料、玻璃珠和鱼酱，来自各地海岸的船只停满了码头。",
  "carthaginians:games": "想象：在迦太基（𐤒𐤓𐤕𐤇𐤃𐤔𐤕）城外的平原上，年轻人赛马，不用缰绳驾马的努米底亚骑手在一旁观看。另一些人在尘土中摔跤，人群押注谁会赢。后来在罗马统治下，迦太基修建了非洲最大的竞技场之一，当地人对战车比赛的热爱不亚于任何城市。",
  "carthaginians:drought": "迦太基（𐤒𐤓𐤕𐤇𐤃𐤔𐤕）的马戈（𐤌𐤂𐤍）写过一部著名的农书，长达二十八卷，备受推崇，罗马元老院专门下令把它译成拉丁文。他教人如何种植葡萄和橄榄以熬过干燥的夏天，以及如何选择土地。想象：干旱之年，山区的农民照他的办法深挖土地，珍惜每一滴水。",
  "carthaginians:quake": "想象：夜里一场地震撼动迦太基（𐤒𐤓𐤕𐤇𐤃𐤔𐤕），比尔萨山上房屋里的油灯纷纷跌落。到了早上，墙上裂缝纵横，人们聚集到神庙。祭司向巴力·哈蒙（𐤁𐤏𐤋 𐤇𐤌𐤍）和塔尼特（𐤕𐤍𐤕）献祭，工匠们开始修补损毁之处。",
  "carthaginians:winter": "公元前218年秋，汉尼拔（𐤇𐤍𐤁𐤏𐤋）的大军翻越阿尔卑斯山（Alpes）。大雪纷飞，山路结冰，人和战象从悬崖上滑落。李维（Livius）说，士兵们用火烧热岩石，再浇上醋，把岩石弄碎。波利比乌斯（Πολύβιος）写道，汉尼拔让士兵们看山下意大利（Italia）的平原，以鼓舞士气。",
  "carthaginians:plague": "狄奥多罗斯（Διόδωρος）写道，公元前396年，一支围攻叙拉古（Συράκουσαι）的迦太基军队在夏日酷暑中遭瘟疫袭击。士兵们死在营中，连尸体都无法掩埋。少数生还者回到迦太基（𐤒𐤓𐤕𐤇𐤃𐤔𐤕），全城陷入悲痛，人们关上店铺，在街头哭泣。",
  "carthaginians:wedding": "想象：在迦太基（𐤒𐤓𐤕𐤇𐤃𐤔𐤕），新娘戴着金耳环和城中作坊所制的玻璃珠项链，被送往丈夫家。两家人享用鱼、无花果和葡萄酒，乐师奏乐。人们摆放小护身符和陶土面具，保佑新家不受邪祟侵扰。",
  "aztecs:siege": "特诺奇蒂特兰（Tenōchtitlan），1521年。八十天里，这座岛城被西班牙战船和数以万计的本地盟军团团围住。天花已经夺去了许多人的生命。不久后写成的一首歌唱道：断矛横在路上，我们悲痛地揪扯头发，我们嚼着枯枝和咸草。墨西加人（Mēxihcah）坚持到最后，一条街一条街地守卫特拉特洛尔科（Tlatelōlco）。",
  "aztecs:triumph": "想象：武士们出征归来，回到特诺奇蒂特兰（Tenōchtitlan）。俘获敌人的武士获赐新斗篷，并有权佩戴特定的饰物，他们所在的街区卡尔普利（calpōlli）以歌声和鼓声庆祝。母亲和妻子在堤道上迎接他们，老人们给年轻人讲自己当年出征的故事。",
  "aztecs:build": "1449年，一场大洪水过后，特斯科科（Tetzcohco）的诗人国王内萨瓦尔科约特尔（Nezahualcoyōtl）设计了一道横跨特斯科科湖的堤坝，长逾十五公里，用来把咸水挡在特诺奇蒂特兰（Tenōchtitlan）的淡水和浮田（chinampa）之外。来自许多城邦的数千名工人打下木桩，再填入石块和泥土。想象：劳动号子在湖面上此起彼伏。",
  "aztecs:voyage": "墨西加人（Mēxihcah）讲述，他们的祖先离开了白鹭之乡阿兹特兰（Aztlān），在神灵维齐洛波奇特利的指引下漂泊了好几代人。他们要在看见鹰立仙人掌的地方定居。1325年，在湖中一座小岛上，他们看到了这一景象，便在那里建立了特诺奇蒂特兰（Tenōchtitlan）。鹰立仙人掌至今仍是这片土地的象征。",
  "aztecs:festival": "每隔五十二年，两套历法重新回到同一天时，墨西加人（Mēxihcah）便担心世界可能就此终结。所有的火都被熄灭。夜里，祭司们登上维沙赫特兰山，观望昴星团（tianquiztli）。当星团越过头顶，便点燃新火，由信使跑着送往每一座城镇。最后一次是在1507年。",
  "aztecs:games": "球赛「奥拉马利斯特利」（ōllamaliztli）用一只沉重的橡胶球，以髋部击球。球员要让球穿过高悬在墙上的石环才能得分，但极少做到。观众拿斗篷、珠宝甚至房子来下注。「帕托利」（Patōlli）是一种以豆子为骰子的游戏，深受喜爱，人们到处都在玩。玩家甚至把席子带到市场上。",
  "aztecs:drought": "「一兔年」（Ce Tōchtli），即1454年，雨水已连续三年断绝，霜冻冻死了玉米，墨西加人（Mēxihcah）陷入饥荒。人们把自己或孩子卖给有玉米的沿海托托纳克人。此后，墨西加人一遇「一兔年」就心生畏惧。国王们修建粮仓，储存玉米以备荒年。",
  "aztecs:quake": "阿兹特克抄本记录了地震，称为「特拉洛林」（tlālolīn），墨西加人（Mēxihcah）相信当今这个世界将在一场地震中终结。日符「奥林」（Ōlīn），意为「运动」，是这个纪元的神圣符号。想象：特诺奇蒂特兰（Tenōchtitlan）大地震动时，人们纷纷跑出屋外，老人们想起种种预兆，祈祷末日尚未到来。",
  "aztecs:plague": "1520年，天花席卷特诺奇蒂特兰（Tenōchtitlan）。根据纳瓦（Nāhuah）幸存者口述写成的《佛罗伦萨抄本》说，脓疮布满人们的脸和身体；他们动弹不得，连身都翻不了，许多人因无人照料而饿死。他们称之为「大疹」（huēyi zahuatl）。它恰好在城市为生存而战时到来。",
  "aztecs:wedding": "《佛罗伦萨抄本》描述了纳瓦（Nāhuah）人的婚礼：由担任媒人的老妇人与两家商定。傍晚，新娘由一名妇人背着，在火把簇拥下送到新郎家。新人坐在灶边的席子上，媒人把新郎斗篷的一角系在新娘的上衣上。长者们发表长篇训诫。",
  "mayans:siege": "多斯皮拉斯，公元760年代。面临威胁，人们从自己的宫殿和神庙上拆下石块，在城市中心周围筑起石墙和木栅，甚至横穿王家广场。考古学家发现了这些仓促修筑的城墙。想象：一家家人挤进墙内，扛着玉米，武士们紧盯着森林，提防敌人。",
  "mayans:triumph": "博南帕克壁画约绘于公元790年，描绘了一场庆典：乐师们摇着沙槌，敲着鼓和龟甲，吹着长号角，舞者戴着巨大的羽冠。身穿白色斗篷的贵族在一旁观看。这些画面展现了一整场节庆，有胜利，也有王室继承人。一千二百年过去了，色彩依旧鲜艳。",
  "mayans:build": "想象：在蒂卡尔（Yax Mutul），工人们把石灰岩石块扛上神庙的台阶，另一些人用熊熊大火烧制石灰，调成灰泥，涂抹白色和红色的墙面。每座神庙烧石灰都要耗费大量木材，城市周围的森林日渐萎缩。石匠们在石头上雕刻象形文字，讲述国王的故事。",
  "mayans-late:voyage": "1502年，在洪都拉斯近海，哥伦布的船队遇到一艘巨大的玛雅贸易独木舟。它由一整棵树凿成，长如一艘桨帆船，有二十五名桨手，船中央搭着遮棚。船上载着棉布、铜铃、黑曜石刀片和可可豆——玛雅人用可可豆当钱。费尔南多·哥伦布注意到，他们捡拾掉落的可可豆时多么小心。",
  "mayans:festival": "在365天的一年结束时，有五个不吉利的日子，称为「瓦耶布」（Wayeb）。兰达主教写道，人们这几天不洗澡、不梳头、不干任何重活，生怕招来厄运。随后新年在欢庆中开始，人们打扫房屋，扔掉旧陶罐和旧席子。",
  "mayans:games": "在《波波尔·乌》（Popol Wuj）中，英雄双子乌纳普（Junajpu）和斯巴兰克（Xb'alanke）与冥界希巴尔巴（Xib'alb'a）的众王比赛球戏，凭机智取胜。玛雅城市修建了带斜墙的石砌球场。球员用髋部击打沉重的橡胶球，观众在墙上观看。这种球戏至今仍以「乌拉马」（ulama）之名流传。",
  "mayans:drought": "湖泊沉积物显示，约公元800年至1000年间，玛雅低地遭受了一连串严重干旱。蒂卡尔（Yax Mutul）和卡拉克穆尔等城市人去城空。想象：农民眼看玉米枯萎，蓄水池干涸，一家家人离开房屋，带着能带的东西向北方或河边走去。",
  "mayans:quake": "约公元600年，萨尔瓦多霍亚德塞伦村附近的洛马卡尔德拉火山爆发。村民们仓皇逃离，留下了晚餐的碗、工具，甚至还有一只拴在角落里的鸭子。火山灰把整个村子完全掩埋，反而将它保存了下来——这是唯一一个能让我们看到日常生活原貌的玛雅农村。",
  "mayans-late:plague": "《卡克奇克尔年鉴》记下了1520年代的那场疫病：死者的恶臭冲天。我们的父辈和祖辈死后，一半的人逃进了田野。狗和秃鹫吞食尸体。孩子们，我们生来就是要死的。作者在孩童时幸存下来，把这一切写下来留给后人。",
  "mayans:wedding": "兰达主教写道，玛雅父亲在媒人的帮助下为儿子挑选妻子。新郎要为岳父做好几年的工。婚礼那天，两家人聚在新娘父亲家中，祭司对新人训话。想象：宾客们分享玉米粽（tamales）和可可饮料。",
  "incas:siege": "比尔卡班巴（Willkapampa），位于安第斯山脚下炎热的森林之中。1537年后的三十五年间，最后一批印加人（Inka）在这片偏远的山谷里坚守，有自己的神庙和房屋。1572年，一支军队来了，人们放火烧了城镇，逃进森林。图帕克·阿马鲁（Thupa Amaru）被俘。人们记得比尔卡班巴是他们最后的避难所。",
  "incas:triumph": "胜利之后，印加（Inka）军队列队返回库斯科（Qusqu），人们唱起凯歌「海利」（haylli）。编年史家记载，这些歌在丰收时和战争中都会唱。想象：士兵们走进大广场，海螺号吹响，一家家人唱着海利，围成圆圈跳舞。",
  "incas-late:build": "每年，阿普里马克河（Apurimaq）附近的四个克丘亚（Runa Simi）村社都会重建最后一座印加（Inka）索桥——Q'eswachaka桥。各家把伊丘草（ichu）搓成细绳，再把细绳拧成粗缆，男人们用三天时间在峡谷上编出新桥，女人们在一旁唱歌。旧桥则任其坠入河中。",
  "incas:voyage": "编年史家萨米恩托讲过一个传说：印加王图帕克·印卡·尤潘基（Inka Thupa Yupanki）率军乘轻木筏驶入太平洋，几个月后带着从遥远岛屿掳来的俘虏和财宝归来。无人知道这是否属实。想象：木筏向西漂流了几个星期，直到地平线上出现一道细细的陆地轮廓。",
  "incas:festival": "六月至日的「因蒂·赖米」（Inti Raymi）是太阳节。在库斯科（Qusqu），人们斋戒数日，然后在黎明前赤脚聚集到大广场上，等待第一缕阳光。太阳升起时，他们以歌声相迎，并献上奇恰酒（chicha）。如今，因蒂·赖米又在萨克萨瓦曼（Saksaywaman）重新举行。",
  "incas:games": "想象：在高原的一个村子里，年轻人沿山路往上奔跑，练习成为「查斯基」（chaski）信使——他们以接力的方式在帝国各地传递消息，一天约跑240公里。另一些人玩「皮奇卡」（pichqa），一种用五面骰子的游戏。获胜者赢得欢呼，还能喝上奇恰酒。",
  "incas:drought": "印加人（Inka）在山坡上修建了成千上万座仓库，称为「科尔卡」（qollqa），里面存满冻干马铃薯、玉米和布匹。遇上干旱，这些仓库就养活百姓。想象：在一个久旱无雨的村子里，官员打开科尔卡，一家家人满怀感激地把一袋袋丘纽（ch'uñu）扛回家。",
  "incas-late:quake": "1650年，一场大地震撼动库斯科（Qusqu），毁掉了大部分殖民时期的教堂和房屋，而用石块严丝合缝砌成、不用灰浆的印加（Inka）墙却岿然不动。印加工匠把墙设计成向内倾斜，门洞做成梯形。石块会晃动、会落定，却不会倒塌。",
  "incas:winter": "六七月间，安第斯山干燥的冬季带来冰冻的夜晚。各家把马铃薯铺在地上，让它们夜里冻结、白天在阳光下解冻，然后赤脚踩踏，挤出水分。这样做成的丘纽（ch'uñu）可以储存好几年。想象：黎明时分，一家家人在结霜的田里一起劳作。",
  "incas:plague": "约1527年，在任何西班牙人到达库斯科（Qusqu）之前，天花就从北方传来。印加王瓦伊纳·卡帕克（Inka Wayna Qhapaq）在基多（Kitu）死于天花，他的继承人也随之死去。编年史家说，这场疫病在安第斯各地夺去了许多人的生命。对百姓而言，这是一场无名的恐怖，帝国陷入悲痛与混乱。",
  "incas:wedding": "安第斯的夫妇往往先以「试婚」的方式同居，称为「西尔维纳库伊」（sirvinakuy），一些村庄至今仍保留这一习俗。编年史家说，在印加（Inka）时代，地方官员会以集体仪式为年轻夫妇主持婚礼。想象：两家人互赠布匹和食物，全村伴着笛声和鼓声起舞。",
  "haudenosaunee:siege": "想象：一座豪德诺索尼（Rotinonhsión:ni）城镇坐落在河边的山丘上，四周环绕着双层削尖原木栅栏，栅栏上设有供守卫站立的平台。敌人已在周围扎营多日。妇女们把水和石块运上平台，孩子们帮忙递箭，储藏坑里的玉米让所有人都有饭吃。夜里，守卫们唱歌鼓舞士气。",
  "haudenosaunee:triumph": "想象：年轻人长途跋涉后回到城镇，在森林边缘高声呼喊，好让人们知道是谁回来了。氏族母亲们一一清点人数。当晚有演说，有玉米汤和鹿肉的盛宴，长屋里跳起社交舞，水鼓和角制沙槌打着节拍。",
  "haudenosaunee:build": "一座长屋可长达六十米，住着同一氏族的好几户人家。邻里们聚在一起，竖起弯曲的铁木杆，再盖上春天剥下的榆树皮。想象：男人们抬起木杆，女人们用椴树皮绳把树皮绑牢，一位老人唱着歌带动大家干活，笑声随着椽木一起升起。",
  "haudenosaunee:voyage": "豪德诺索尼的传统讲述，和平缔造者乘着一艘白石独木舟渡过安大略湖，为彼此交战的各族带来和平的讯息。他与海华沙（Haiëñ'wa'tha）一起走遍一座座城镇，直到五族种下了和平之树。这个故事在集会上代代传讲，那艘白石独木舟从未被遗忘。",
  "haudenosaunee:festival": "初夏野草莓成熟时，豪德诺索尼各社区会举行草莓感恩节。人人分享草莓汁，因为据说草莓长在通往造物主之地的路上。这类集会之前要诵读《感恩致辞》（Ganǫhonyohk），依次问候人们、大地、水、草木和天空。",
  "haudenosaunee:games": "长曲棍球是造物主的游戏，称为Dehontsigwaehs，用来表达感恩、疗愈伤病和化解纠纷。过去整座城镇组队，在长达一英里的场地上比赛。球员手持弯曲山核桃木制成的球棍，网兜用鹿肠编成。想象：长者们在场边观看，年轻人一直跑到筋疲力尽，人群的呼喊声响彻全场。",
  "haudenosaunee:drought": "豪德诺索尼（Rotinonhsión:ni）人的生活依靠「三姐妹」：一起种植的玉米、豆子和南瓜。想象：干燥的夏天，玉米叶卷曲起来，拥有田地的妇女们用树皮桶从河里提水。各家定量分配储存的玉米，人们祈求西方的祖父们——雷神（Ratiwé:ras）——带来雨水。",
  "haudenosaunee:quake": "1663年2月，一场大地震撼动了整个圣劳伦斯河谷及其以南地区。《耶稣会报告》描述森林摇晃、河流改道、人们纷纷逃出家门。想象：在一座豪德诺索尼（Rotinonhsión:ni）城镇里，长屋的木杆嘎吱作响、来回摇摆，长者们聚在一起，商议大地在诉说什么。",
  "haudenosaunee:winter": "1779年至1780年的冬天是人们记忆中最艰难的冬天之一。秋天城镇和果园被焚毁后，数千户豪德诺索尼（Rotinonhsión:ni）家庭在尼亚加拉附近的深雪中扎营。食物匮乏，许多人死于寒冷和饥饿，林中的动物也冻死了。长者们记得，那是雪深及腰的冬天。",
  "haudenosaunee:plague": "1630年代和1640年代，天花和麻疹席卷豪德诺索尼（Rotinonhsión:ni）的城镇，也许夺去了一半人口。《耶稣会报告》描述了全家卧病的长屋。失去许多成员的氏族把他人收养进家族，让名字延续下去。哀悼与慰唁仪式帮助幸存者承受失去亲人的痛苦。",
  "haudenosaunee:wedding": "据十九世纪观察者描述的古老习俗，婚事由母亲们安排。新娘给新郎的母亲送去一篮玉米面包，新郎的母亲回赠鹿肉或其他猎物，表示两家都能养家。夫妇住在妻子所属氏族的长屋里，孩子归属母亲的氏族。",
  "lakota:siege": "1876年夏天过后的那个冬天，士兵们穿过雪原追踪拉科塔（Lakȟóta）人的营地。一家家人一次又一次迁移，几乎没有时间打猎。1877年1月，在狼山，人们在暴风雪中作战，掩护妇女和孩子撤离。整个寒冬他们都在坚持，忍饥挨饿，马匹消瘦，直到春天许多部落才前往保留地管理处。",
  "lakota:triumph": "1876年6月，油草河（Pȟežísla Wakpá）——即小大角河——之战后，沿河的营地彻夜跳起胜利之舞。当时年仅十二岁的黑麋鹿（Heȟáka Sápa）记得那鼓声和歌声，记得妇女们如何唱出勇士的名字。各家也在哀悼自己的亡者。随后，这个大营地便解散迁移了。",
  "lakota:build": "帐篷（thípi）属于妇女，由她们制作和搭建。妇女们用鞣制过的野牛皮缝制帐篷外罩，有时还会设宴款待帮手。搭建时，她们先绑好三四根主杆，再把其余的杆子斜靠成圆锥形，用最后一根杆子挑起外罩，然后用木钉把它别合。想象：两个女人边说边笑，几分钟就搭起一顶帐篷。",
  "lakota:voyage": "18世纪，拉科塔人（Lakȟóta）从密西西比河附近的林地向西迁往开阔的大平原，追随野牛，并学会了骑马。一份「冬季纪年」记载，约1776年，立牛到达了黑山（Ȟe Sápa），带回一根松枝。想象：一家家人第一次看见黝黑的群山从平原上拔地而起。",
  "lakota:festival": "夏天，拉科塔（Lakȟóta）各部落在漫长冬季的分散之后汇聚成大营地。这里有盛宴、赠礼、赛马和社交舞会「瓦奇皮」（wačhípi），亲人相聚，青年男女求爱，大家互通消息。集会中的一些仪式是神圣的，由族人自己守护。对各家来说，这是一年中最快乐的时光。",
  "lakota:games": "在夏季营地，年轻人在草原上赛马，人们押注输赢。男孩们玩圈杆游戏，向滚动的圆环投掷标枪。妇女们玩「欣尼」（shinny），一种用弯棍击球的游戏，女孩们则用李子核当骰子玩游戏。想象：骑手们冲过终点时，营地里充满了呼喊和欢笑。",
  "lakota:drought": "想象：干燥的夏天，草原上的草变黄，小溪干涸，野牛远去。侦察兵骑马跑了好几天也找不到牛群。各家吃着干肉和野萝卜（tȟíŋpsiŋla），营地一次次迁移，寻找水源和猎物，祈求降雨。",
  "lakota:quake": "北部大平原上很少发生地震。想象：一个夏夜，大地震动，帐篷的支杆咔咔作响，马匹嘶鸣着挣脱缰绳。第二天早上，长老们议论这预示着什么，年轻人则出去收拢跑散的马。冬季纪年的保管者也许会把这件事画成这一年的图像。",
  "lakota:winter": "拉科塔人（Lakȟóta）的纪年者绘制冬季纪年（waníyetu wówapi），每年一幅图画。许多年份是因寒冷而被记住的：大雪之冬、许多马被冻死之冬。想象：营地躲进河谷的树林里，积雪堆在帐篷四周，各家分享干肉，围着火讲故事，直到春天来临。",
  "lakota:plague": "1837年，天花随一艘汽船沿密苏里河而上，蔓延到整个大平原。拉科塔人（Lakȟóta）的冬季纪年用布满斑点的人形标记这一年。整座营地的人病倒，许多家庭失去了亲人。有些拉科塔部落几年前接种过疫苗，受害较轻。幸存者哀悼之后，继续前行。",
  "lakota:wedding": "年轻男子用雪松木笛（siyótȟaŋka）求爱，夜里在营地边吹奏，又在姑娘的帐篷旁与她一同披着他的毯子站立。要娶亲，他得给她家送马作为礼物。女方家也回赠礼物，新人的帐篷则由女方家的妇女们制作。",
  "americans:siege": "1863年，密西西比州维克斯堡。小城被围困了四十七天，日夜遭受炮击。各家在黏土山坡上挖洞，带着家具和孩子住进地下。面粉吃光了，人们吃骡肉和老鼠。7月4日，小城投降。一位妇女在日记中写下了枪炮停歇后的寂静。",
  "americans:triumph": "1945年8月14日。战争结束的消息传来，人群涌进纽约时代广场，欢呼着，亲吻陌生人，从办公楼的窗口抛撒纸片。一名水兵亲吻了一位护士，那张照片后来闻名于世。在小城镇里，教堂钟声响起，汽车喇叭齐鸣。家家户户等待着士兵们归来。",
  "americans:build": "19世纪70年代，工人们在西弗吉尼亚为铁路开凿大弯隧道。传说力大无穷的钢钎手约翰·亨利挥锤与蒸汽钻机比赛并获胜，却手握铁锤死去。铁路工人们唱着他的歌谣，让锤子敲击钢钎时合上节拍。",
  "americans:voyage": "1620年9月，五月花号载着102名乘客驶离普利茅斯。他们横渡大西洋六十六天，风暴甚至把一根主梁震裂。11月9日，他们望见了科德角的沙丘。威廉·布拉德福德写道，他们跪倒在地，感谢上帝带领他们渡过了浩瀚而狂暴的大洋。",
  "americans:festival": "自1907年以来，每年12月31日午夜，一只彩球都会从纽约时代广场上方的旗杆上降下。人群倒数最后几秒，随后彩纸飞舞，号角齐鸣，陌生人互相拥抱，乐队奏起《友谊地久天长》。全国各地的家庭在电视机前观看，许下新年的心愿。",
  "americans:games": "1939年7月4日，扬基体育场。曾连续出场2130场比赛的「铁马」卢·格里克，因病结束职业生涯后，站在六万名球迷面前。他说：今天，我认为自己是世上最幸运的人。体育场一片寂静，随后欢呼声持续了好几分钟。",
  "americans:drought": "1935年4月14日，黑色星期天。一堵沙尘之墙席卷南部大平原，白昼变成黑夜。多年干旱之后，堪萨斯、俄克拉何马和得克萨斯的表土被狂风卷走。各家用湿布塞住窗缝，紧紧搂住孩子。伍迪·格思里为此写下《再见，很高兴认识你》，许多家庭收拾行装前往加利福尼亚。",
  "americans:quake": "1906年4月18日清晨。一场地震摇撼旧金山近一分钟。房屋倒塌，大火在全城燃起，烧了三天。各家在金门公园露营，在街头做饭。人们把自己的地址写在废墟的墙上，好让亲人找到他们。",
  "americans:winter": "1888年1月12日。内布拉斯加和达科他的草原上是个暖和的早晨，孩子们没穿外套就去上学了。下午，暴风雪骤然袭来，风雪之大，伸手不见五指。许多孩子在回家路上迷失。这场风暴后来被称为「儿童暴风雪」，那些家庭永远没有忘记。",
  "americans:plague": "1918年秋，流感疫情席卷全国。学校、教堂和剧院纷纷关闭。人们在街上戴着纱布口罩。在费城，一次游行之后，每天有数百人死去。木匠来不及做棺材。各家自己照料病人，孩子们跳绳时唱着一首童谣：我有一只小鸟，它的名字叫恩扎。",
  "americans:wedding": "想象：在一座小镇上，新娘穿戴着旧的、新的、借来的和蓝色的东西。教堂仪式之后，两家人聚在挂满彩灯的谷仓里，一位提琴手拉起方块舞曲。在许多非裔美国人家庭中，新人会在宾客的欢呼声中跳过扫帚，这是从奴隶制时代流传下来的传统。",
  "mexicans:siege": "想象：大革命期间，约1914年，北方一座小镇被围困数周。随军的妇女（soldaderas）在小火堆上烙玉米饼，冒着枪火运水。各家躲进教堂地窖。围城结束后，一位歌手为此编了一首科里多（corrido）叙事歌，在集市上传唱多年。",
  "mexicans:triumph": "想象：在山中的一个村庄，男人们从战场归来。教堂钟声响起，铜管乐队奏乐，妇女们抛撒鲜花。各家为全村准备莫莱酱和玉米粽。当晚，在灯笼的光下，一位歌手弹着吉他，唱起一首歌颂他们英勇的新科里多。",
  "mexicans:build": "在瓦哈卡的村庄里，「特基奥」（tequio）是集体劳动的传统：每户人家都派人去修建学校、修缮教堂或清理道路，不拿报酬。想象：一个星期天，全村人搬石头、和灰浆，妇女们送来饭菜，乐队奏乐，墙壁一点点升高。",
  "mexicans:voyage": "从1565年到1815年的250年间，马尼拉大帆船「中国船」（Nao de China）横渡太平洋前往阿卡普尔科，航程长达四到六个月。一望见船影，小镇便挤满前来赶大集的商人，抢购丝绸、瓷器和香料。想象：被坏血病折磨得虚弱不堪的水手们，望见墨西哥海岸时流下了眼泪。",
  "mexicans:festival": "从12月16日到24日，「波萨达」节（Las Posadas）重现玛利亚（María）和约瑟（José）寻找住处的故事。每天晚上，邻居们手持蜡烛，挨家挨户在门前唱歌，请求借宿。屋里的人先是拒绝，最后终于开门，大家一拥而入，享用玉米粽、热果饮（ponche），还有皮纳塔。孩子们打破星形的皮纳塔，争抢糖果。",
  "mexicans:games": "1942年，一位戴银色面具的摔跤手走上墨西哥城（Ciudad de México）的擂台：他就是「圣徒」（El Santo）。几十年间，他在自由搏击（lucha libre）中征战，从不在公开场合摘下面具，还主演了多部电影。自由搏击是全家同乐的表演：观众为「正派」（técnicos）喝彩，向「反派」（rudos）喝倒彩，孩子们买下心中英雄的面具。",
  "mexicans:drought": "1785年，早霜冻死了墨西哥中部的玉米，随后又是干旱。1786年被称为「饥荒之年」（el año del hambre）。数千人死去，人们离开村庄四处寻找食物。教会和城镇打开粮仓，各家靠草根和野菜度日。",
  "mexicans:quake": "1985年9月19日早上7点19分。一场地震袭击墨西哥城（Ciudad de México），楼房纷纷倒塌，数千人遇难。普通百姓组成救援队，徒手在瓦砾中挖掘。这些志愿者后来被称为「鼹鼠」（topos）。一连数日，他们努力寻找幸存者，有时呼吁大家安静下来，倾听石块下的呼声。",
  "mexicans:winter": "1967年1月11日，墨西哥城（Ciudad de México）下起了雪，这是在世的人几乎从未见过的景象。孩子们跑到外面，在街上堆雪人，人们在宪法广场（Zócalo）打雪仗，摄影师们赶忙拍下白雪覆盖的火山和屋顶。这座城市把那一天记作奇迹般的一天。",
  "mexicans:plague": "1737年，一种名为「马特拉萨瓦特尔」（matlazahuatl）的瘟疫席卷墨西哥城（Ciudad de México），夺去数千人的生命。全城奉瓜达卢佩圣母（Virgen de Guadalupe）为主保，祈求她的庇护，瘟疫渐渐平息。各家在屋里点起蜡烛，游行队伍挤满街道。那一年的虔诚至今留在这座城市的记忆中。",
  "mexicans:wedding": "在墨西哥的婚礼上，教父母（padrinos）为新人提供支持。弥撒中，一条由鲜花或念珠串成的绳索（lazo）套在新人的肩上，新郎送给新娘十三枚金币（arras）。宴会上，马里亚奇乐队演奏，宾客们跳起「海蛇舞」（la víbora de la mar），从新人高举的手臂下穿过。",
  "mapuche:siege": "想象：一个马普切社群退守到普卡拉（pukara）——一座环绕着壕沟和木桩的山顶堡垒。敌方骑手在山下盘旋。堡垒里，各家分享储存的土豆和干肉，妇女们磨玉米，战士（weichafe）们守望。夜里，昆特隆鼓（kultrun，kultrung）响起，为人们鼓舞士气。",
  "mapuche:triumph": "想象：战士（weichafe）们骑马归来，社群聚在一起。特鲁特鲁卡长号（trutruka）——一种长长的竹制号角——吹响，昆特隆鼓（kultrun，kultrung）敲起。妇女们准备穆代酒（muday），一种用玉米或小麦发酵的饮料，各家欢宴。长老们讲述战士们的英勇，年轻人翩翩起舞。",
  "mapuche:build": "当一户人家需要新建一座茅屋（ruka）——用茅草和木头搭成的传统房屋——邻居们便来参加「明加科」（mingako），一起干上一天活。他们立柱、编墙，用茅草和芦苇苫顶。完工后，主人家为大家奉上丰盛的肉、面包和穆代酒。",
  "mapuche:voyage": "从17世纪起，马普切家庭经由山口向东翻越安第斯山，前往东方之地普埃尔马普（Puelmapu），也就是广阔的潘帕斯草原。他们赶着马和牛，进行贸易。想象：在山口的雪中跋涉多日后，各家看见平原在脚下展开，于是献上感恩。",
  "mapuche:festival": "马普切新年「我们的特里潘图」（We Tripantu）在六月冬至。前一晚，各家聚在一起，分享食物和故事。黎明时分，年轻人到冰冷的河里沐浴，迎接新年的力量。随后，随着白昼开始变长，各家迎接太阳的回归。",
  "mapuche:games": "帕林（Palin）是马普切人用弯棍和小球玩的游戏，一场可以打上一整天。各社群相互挑战，选手们在脸上涂彩，家人们前来观看助威。赛后，两个社群一同欢宴。帕林至今仍有人玩。",
  "mapuche:drought": "想象：南方的雨水迟迟不来，溪流干涸。小麦和土豆枯萎了。各家从河里挑水，分享储存的粮食。社群聚到一起，请酋长（lonko）和长老们召集众人祈雨。",
  "mapuche:quake": "1960年5月22日，有记录以来最强烈的地震袭击智利南部的瓦尔迪维亚附近，随后又是海啸。马普切社群失去了家园。马普切传说中有两条大蛇特伦特伦（Tren Tren，Trengtreng）和凯凯（Kai Kai，Kaykay）：凯凯掀起海水，特伦特伦抬升群山，拯救了人们。",
  "mapuche:winter": "在安第斯山南段，佩文切人（Pewenche）——意为「智利南洋杉之民」——秋天采集南洋杉的种子，储存起来过冬。想象：大雪覆盖群山，各家围坐在茅屋（ruka）的火塘边，烤着种子讲故事，孩子们倾听风吹过树林的声音。",
  "mapuche:plague": "想象：16世纪，一种前所未见的疾病随陌生人而来。马普切人称之为「查瓦隆戈」（chavalongo），即热病。一家家人病倒了，巫医（machi）用草药和祷告救治。许多人死去，幸存的社群哀悼死者。",
  "mapuche:wedding": "在传统的马普切婚礼中，新郎和朋友们会骑马来到新娘家，在征得她同意的前提下，以一场仪式性的追逐把她带走，这叫「尼亚皮通」（ñapitun）。随后，新郎家向新娘家送上聘礼（mafün），两家一同欢宴。",
  "muisca:siege": "想象：高原上的穆伊斯卡（Muysca）村庄由木桩围成的栅栏（cercados）保护着。敌人逼近时，人们带着玉米和土豆退进栅栏里。战士们守在门口，妇女们酿制奇恰酒（fapqua）。围困持续数日，人们一直坚守，直到敌人撤退。",
  "muisca:triumph": "想象：在边境抵御潘切人的穆伊斯卡（Muysca）战士（güechas）沿山路回到巴卡塔（Bacatá）高原。人们捧着装满奇恰酒（fapqua）的葫芦迎接他们，伴着笛声和鼓声唱歌、跳起长长的舞。战士们佩戴羽饰和金饰，老人们向孩子们讲述每个人是如何作战的。",
  "muisca:build": "在太阳圣城苏加穆希（Sugamuxi），穆伊斯卡人（Muysca）用从远方运来的巨大木柱建起一座神庙。编年史家记载，1537年，手持火把的陌生人进入神庙，神庙随即焚毁。想象：建造者们拖着巨大的木柱穿越高原，唱着歌合拍用力。",
  "muisca:voyage": "穆伊斯卡人（Muysca）用锡帕基拉和内莫孔盐矿的盐以及祖母绿，与邻近民族交换棉花、黄金和羽毛。想象：一队商人背着盐块从高原走下，翻山过河，直到望见下方温暖的河谷。",
  "muisca:festival": "想象：丰收时节，高原上的穆伊斯卡人（Muysca）聚在一起过节。他们酿奇恰酒（fapqua），煮玉米和土豆，随着笛声和鼓声起舞。编年史家描述过身着盛装、戴着面具的舞者列队游行，一连唱上好几天。这个节日标志着辛苦劳作的结束。",
  "muisca:games": "今天在哥伦比亚流行的特霍（tejo）游戏，据说源自穆伊斯卡人（Muysca）向目标投掷金属或石盘的游戏。想象：傍晚，穆伊斯卡的年轻人聚在一起，把石盘掷向目标，一边下注一边说笑，共饮奇恰酒（fapqua）。",
  "muisca:drought": "想象：雨水迟迟不降到高原上，垄田里的玉米和土豆枯萎了。湖泊和沼泽缩小，芦苇变得枯黄。各家像父辈那样走到圣湖边献上供品，分享粮仓里剩下的东西，等待云彩重新聚集在群山之上。",
  "muisca:quake": "想象：穆伊斯卡（Muysca）高原的大地震动起来，木头、竹子和茅草搭成的圆屋摇晃着吱吱作响。人们抱着孩子跑到田野里，狗在嚎叫。事后，长老们议论大地借此想说什么，邻居们互相帮忙，竖起倒下的柱子，重新绑好屋顶。",
  "muisca:plague": "1537年以后的几十年里，一波又一波的天花和其他新的疾病传到高原，西班牙的记录提到1558年的一场大瘟疫。想象：在一个穆伊斯卡（Muysca）村庄里，全家人同时病倒，人手少得收不完玉米。医者尝试草药和咒歌，幸存者哀悼那些承载着古老知识的长老。",
  "muisca:wedding": "想象：高原上的一场穆伊斯卡（Muysca）婚礼。新郎家送来彩绘的棉斗篷——穆伊斯卡人以这种精美布料闻名——新娘家则回以食物和奇恰酒（fapqua）。新人并肩坐在长老面前，听他们传授婚姻生活的忠告。随后全村人饮酒、唱歌，伴着笛声和鼓声跳舞直到天明。",
  "tupi:siege": "16世纪50年代曾被图皮南巴人（Tupinambá）俘虏的德国人汉斯·施塔登，描述过他们由双层原木栅栏保护的村庄。想象：一支敌方战队包围了村庄，守卫者从栅栏后放箭，妇女们送来水和食物。他们一直坚守，直到敌人撤退。",
  "tupi:triumph": "让·德·莱里描述过图皮南巴（Tupinambá）战士从战场归来时，村庄如何用木薯发酵的考因酒（cauim）和一连跳上几天的舞蹈来庆祝。战士们讲述自己的战功，妇女们歌唱。想象：人们欢庆之时，鼓声隆隆。",
  "tupi:build": "图皮南巴人（Tupinambá）住在巨大的长屋（oca）里，每座长屋住着许多户人家。全村人齐心协力建造长屋，砍伐木杆，用棕榈叶苫盖屋顶。想象：男人们爬上屋架，妇女们把叶子往上递，孩子们在中间跑来跑去，笑个不停。",
  "tupi:voyage": "图皮-瓜拉尼诸民族横越南美洲迁徙，寻找「无恶之地」伊维马拉埃伊（Yvy Marã'ey）——一个没有死亡和苦难的地方。在萨满的引领下，整村整村的人离开家园，步行数月。想象：人们来到海边，看见无边的海水在眼前展开。",
  "tupi:festival": "1557年，让·德·莱里在一座大屋里听到图皮南巴人（Tupinambá）唱歌：男人们齐声合唱「Heu, heuraure, heura」。他写道，自己深受感动，每当回想起来，心都会颤抖。想象：舞蹈伴着沙锤（maraca，mbaraká）和考因酒（cauim）通宵达旦。",
  "tupi:games": "想象：一个晴朗的午后，图皮村庄的年轻人比赛冲进河里，逆流游泳，另一些人则向棕榈叶编成的靶子射箭。图皮男孩几乎刚会走路，就学会了在独木舟上射鱼。获胜者在歌声中受到称颂，全村人共饮考因酒（cauim），跳舞直到深夜。",
  "tupi:drought": "想象：海岸一带的雨水迟迟不来，溪流缩成一个个水洼，烧垦地里的木薯蔫了。河水低浅，鱼也少了。村庄决定迁往森林深处仍有流水的地方，带上吊床、陶罐和一篮篮木薯粉（farinha）。长老们在前面带路，孩子们肩上扛着鹦鹉。",
  "tupi:quake": "想象：一天夜里，一座图皮村庄脚下的大地颤动起来，这在那片海岸上几乎从未有过。吊床在柱子上晃荡，葫芦掉落，长屋的屋架在熟睡的家人头顶吱嘎作响。大家都跑到空地上。第二天早上，人们去问医者兼先知帕热（pajé）这意味着什么，众人聚拢来聆听。",
  "tupi:plague": "1562年和1563年，天花席卷巴伊亚的图皮南巴（Tupinambá）村庄，夺去数万人的生命，随后又是饥荒，因为没有人有力气耕种。耶稣会士的书信描述了无人掩埋的尸体，以及逃入森林的家庭，有些人甚至为了食物卖身。整村整村的人消失了，幸存者无论走到哪里，都带着这份悲痛。",
  "tupi:wedding": "让·德·莱里写道，在图皮南巴人（Tupinambá）中，想结婚的年轻人会去向姑娘的父亲求亲，父亲同意，婚事便成了。之后，女婿要为女方家打猎、捕鱼、开垦田地。想象：两家人聚在长屋里，新娘用格尼帕果汁（genipapo）彩绘身体，戴着羽饰，全村人以考因酒（cauim）和舞蹈庆祝。",
  "mayans:fire": "约公元810年，敌人攻入阿瓜特卡——一座位于佩特斯巴通湖上方悬崖上的玛雅城市，放火烧了宫殿和贵族的宅邸。各家人两手空空地逃走。在烧毁的屋顶下，猪俣健领导的考古学家发现一切都留在原处：磨石、彩绘陶罐、书吏的贝壳墨盒、雕刻的骨饰，甚至还有工匠未完成的作品。终结这座城市的大火，将古典期玛雅生活的一天保存了十二个世纪。",
  "mayans:thunder": "在古典期玛雅的陶瓶上，雨神恰克（Chahk）在风暴中起舞，高举石斧劈开云层；闪电本身则是卡维尔（K'awiil），一个长着一条蛇腿、额头插着冒烟斧头的小神。国王们手持卡维尔形象的权杖，以示自己掌控风暴，并以他的名字为名：「天生闪电」西亚赫·昌·卡维尔（Siyaj Chan K'awiil）于公元411年至456年统治蒂卡尔（Yax Mutul）。雷声滚过森林时，人们听见众神在工作。",
  "mayans:voyage": "约公元734年，蒂卡尔（Yax Mutul）国王哈索·昌·卡维尔（Jasaw Chan K'awiil）葬于一号神庙之下，身旁放着雕刻的骨头。其中一块刻着一只独木舟滑过冥界之水：两位年老的划桨神，一位在船头，一位在船尾，载着玉米神和一只猴子、一只鹦鹉、一条狗和一只鬣蜥，一边前行一边下沉。古典期玛雅真实的独木舟沿河流和加勒比海岸运载盐、黑曜石、玉和可可。",
  "mayans:plague": "古典期晚期，科潘（Oxwitik）河谷的人口已超出田地所能轻松养活的数量。那几个世纪的骸骨显示出贫血和儿童期感染的痕迹，许多人早早死去。想象：约公元800年，一场热病在河边的房屋间蔓延。一位医者焚烧柯巴脂，呼唤宫廷陶瓶上所绘的瓦伊（wahy）精灵——能够降下疾病的生灵——母亲们则从科潘河打来水，为孩子们降温。",
  "incas:quake": "在今天利马附近的沙漠海岸上，矗立着帕查卡马克（Pachakamaq）——推动世界之神的圣所。大地震动时，安第斯人说那是帕查卡马克在发怒转身，朝圣者从塔万廷苏尤各地赶来献上供品，向他的神谕询问未来。印加人（Inka）尊崇这座古老的圣所，在它旁边建起一座太阳神庙。他们的第九位君主取名帕查库特克（Pachakutiq），意为「翻转世界者」。",
  "incas:build": "约1440年，印加（Inka）君主帕查库特克（Pachakutiq）在库斯科（Qusqu）上方开始修建要塞神庙萨克塞瓦曼（Saksaywaman），他的继任者们又接着修了几十年。编年史家谢萨·德·莱昂听说，两万人通过米塔（mit'a）劳役轮流前来：有人采石，有人用绳索和滚木拖运重逾百吨的巨石，有人把石块拼合得严丝合缝，连刀刃都插不进去。传说有一块累坏了的石头流下血泪，再也不肯挪动。",
  "egyptians-late:hunt": "每年秋天，数以百万计的鹌鹑向南飞越地中海，精疲力竭地落在埃及北部海岸的沙滩上。世世代代，从阿里什（العريش）到马特鲁港（مرسى مطروح）的人家都会沿沙滩在杆子上张起细网，在黎明时分捕捉它们。想象：九月的一个夜里，一位渔夫和儿子们在黑暗中守在网边，听着海浪声，直到第一批疲惫的鸟儿贴着浪头低低飞来，男孩们沿着海岸奔跑。",
  "egyptians-late:battle": "1798年7月21日，因巴巴（إمبابة）。在尼罗河西岸、与开罗（القاهرة）隔河相望的地方，身穿丝绸和锁子甲的马穆鲁克骑兵冲向列成方阵的法军，在火枪射击下纷纷倒下；许多人试图渡河时溺水而亡。身在城中的编年史家阿卜杜勒-拉赫曼·贾巴尔提（عبد الرحمن الجبرتي）记下了东岸人群的哀号，以及开罗百姓带着能拿走的一切仓皇出逃的情景。",
  "egyptians-late:siege": "1807年3月31日，拉希德（رشيد），即罗塞塔。一支英军纵队开进这座尼罗河古港的狭窄街巷，发现四下寂静无声。随后，一声信号，城中百姓和守军从高大砖房的窗口和屋顶开火，士兵们被困在巷子里。四月，另一支部队围城两周，随后撤走。拉希德至今每年九月都以歌声和游行纪念人们的这次抗击。",
  "egyptians-late:triumph": "1928年，阿姆斯特丹。来自三角洲的举重运动员赛义德·努赛尔（السيد نصير）三项总成绩355公斤，夺得轻重量级金牌；几天后，摔跤手易卜拉欣·穆斯塔法（إبراهيم مصطفى）又夺得古典式摔跤金牌。他们是埃及的第一批奥运冠军，也是阿拉伯世界的第一批。想象：代表队乘船回国时，亚历山大（الإسكندرية）的码头人山人海，鼓手和歌手领着两人穿过欢呼的街道。",
  "egyptians-late:gather": "夏末，三角洲的棉花在田野上绽开一片洁白；一个世纪以来，埃及的长绒棉一直是国家的财富。全家人连同孩子一起手工采摘，把棉花装进挎在肩上的布袋里。想象：1930年，曼苏拉（المنصورة）附近，黎明时分，一排妇女和女孩沿着田垄向前移动，一人领唱，众人应和，一个男孩把装满的袋子跑着送到田边的秤旁。",
  "egyptians-late:build": "1869年，为了苏伊士运河通航，赫迪夫伊斯梅尔（الخديوي إسماعيل）想让开罗（القاهرة）拥有一座歌剧院。意大利建筑师和埃及工匠在老城边上用木头和砖块，大约六个月就建起了赫迪夫歌剧院；木匠、泥瓦匠和画师们在灯下赶工，及时完成了金碧辉煌的大厅。当年十一月，歌剧院以威尔第的《弄臣》揭幕，1871年12月又在这里首演了《阿依达》。",
  "egyptians-late:voyage": "1932年3月，来自阿拉伯世界各地的音乐家来到开罗（القاهرة），参加阿拉伯音乐大会（مؤتمر الموسيقى العربية）：伊拉克木卡姆歌手穆罕默德·古巴恩奇（محمد القبانجي）带着他来自巴格达的恰尔吉（chalghi）乐队，还有来自阿勒颇、突尼斯、阿尔及利亚和非斯的乐手。欧洲学者也前来聆听和录音，巴托克·贝拉便在其中。三周里，他们为音阶和四分之一音争论不休，晚上则彼此演奏。",
  "egyptians-late:festival": "每年十月棉花收获之后，坦塔（طنطا）会涌入多达两百万人，参加赛义德·巴达维诞辰节（مولد السيد البدوي）——这位13世纪的苏菲圣徒就葬在这里。苏菲教团举着旗帜游行，颂歌手（منشدين）在帐篷下通宵吟唱，齐克尔（ذكر）的圆圈随着奈伊笛和鼓声摇摆。各家在街头露营，孩子们荡秋千、买糖果，最后一夜以盛大的游行告终。",
  "egyptians-late:games": "在上埃及的棕榈树下，在婚礼和诞辰节上，两个男人手持长棍相对而立，这就是赛义德（صعيد）地区的棍术游戏塔赫提卜（تحطيب）。他们随着米兹马尔双簧管（مزمار）和大型塔布勒巴拉迪鼓缓缓绕圈，佯攻、出击、格挡，每一招都以礼相应，从不意在伤人。观众围成一圈，为最巧妙的招式喝彩。2016年，塔赫提卜被列入联合国教科文组织非物质文化遗产名录。",
  "egyptians-late:ritual": "19世纪30年代，爱德华·莱恩在开罗（القاهرة）观看了这一仪式。每年夏天，一位传报人——「尼罗河报信人」（منادي النيل）——走街串巷，宣告罗达岛（الروضة）水位计上河水每天上涨的高度。当水位达到满额，横在城市运河上的土坝便在船只、鼓声和焰火中被掘开，河水涌入：这就是「尼罗河守信」（وفاء النيل）。一个好年景即将到来。",
  "egyptians-late:rain": "直到1973年为止的近四十年里，每月的第一个星期四晚上，开罗（القاهرة）的街道都空空荡荡。从巴格达到拉巴特，人们在咖啡馆、家中和村庄广场上围坐在收音机旁，等待乌姆·库勒苏姆（أم كلثوم）。她一首歌要唱一个多小时，应听众的呼声把一句歌词反复吟唱，直到大厅里的人和远方的听众一同升入塔拉布（طرب）——聆听的狂喜。",
  "egyptians-late:drought": "从1979年到1988年，埃塞俄比亚高原年复一年地缺雨，尼罗河水量稀薄。阿斯旺高坝后面的大湖水位不断下降，工程师们担心涡轮机会停转。河谷里的农民等着轮到自己用水渠，眼看着沟里的水位下降。想象：1988年夏天，明亚（المنيا）的一位农民守着收音机，等待来自阿斯旺（أسوان）的消息；那年八月，洪水终于来了。",
  "egyptians-late:flood": "直到20世纪60年代，尼罗河仍像法老时代以来那样，每年八月漫过埃及的田野。村庄建在土丘上，红褐色的河水漫开时，大地变成一片湖泊，点缀着棕榈树和房屋，男孩们从一个屋顶游到另一个屋顶。想象：1964年，为修建高坝，河水在阿斯旺（أسوان）被改道，卢克索（الأقصر）附近的一位老妇人望着最后几次洪水之一，唱起母亲教给她的洪水之歌。",
  "egyptians-late:wind": "每年春天，喀新风（خماسين）——「五十天」的热风——把沙尘从沙漠中吹来。开罗（القاهرة）的天空变成黄色，太阳成了一个苍白的圆盘，沙粒钻进面包和水罐里。这也是闻风节（شم النسيم）的季节，穆斯林和科普特人同样过这个春季节日，各家到尼罗河边野餐，吃咸鱼、洋葱和彩蛋。想象：一阵喀新风吹散了野餐，大家笑着跑去躲避。",
  "egyptians-late:fire": "1971年10月28日黎明前，开罗（القاهرة）的赫迪夫歌剧院燃起大火。这座1869年落成的古老木结构建筑在几个小时内烧成平地，布景、戏服和一个世纪积累的乐谱尽数化为灰烬。消防员和阿塔巴（العتبة）街区的邻居们奋力扑救，但到了早上只剩一片灰烬，开罗的音乐家们站在广场上落泪。1988年，一座新歌剧院在杰济拉（الجزيرة）岛上落成。",
  "egyptians-late:thunder": "1994年11月2日，上埃及经历了连日罕见的暴雨，闪电击中了艾斯尤特（أسيوط）附近杜伦卡（درنكة）村上方的油罐。洪水裹挟着燃烧的燃油冲进村中小巷，整个村子同时遭受火与水的吞噬，数百人罹难。周边村庄的乡亲们蹚水进来救出幸存者，艾斯尤特的清真寺和教堂向失去一切的家庭敞开了大门。",
  "egyptians-late:quake": "1992年10月12日下午3点09分，开罗（القاهرة）的地面震动了约半分钟。中世纪老城里的旧房屋开裂倒塌，宣礼塔的塔顶坠落，拥挤的学校里，孩子们在楼梯上的慌乱中被踩踏挤压。五百多人遇难。当晚，成千上万的家庭因害怕余震而睡在街头和花园里，此后老开罗的工匠们花了数年时间修复清真寺。",
  "egyptians-late:winter": "亚历山大（الإسكندرية）的渔民靠风暴来认识冬天，这些风暴叫做「瑙瓦」（نوات），每一场都有名字和日期：十一月的卡西姆（القاسم），十二月的大法伊达（الفيضة الكبرى），一月的加塔斯（الغطاس），即主显节的风暴。瑙瓦来临时，海浪越过滨海大道，渔船停泊在安富希（الأنفوشي）港内，男人们坐在咖啡馆里喝着热萨拉卜（سحلب），等待风停。",
  "egyptians-late:plague": "1947年9月，霍乱在三角洲的古赖因（القرين）村暴发，并沿着运河蔓延。数周之间，电台每天播报死亡人数；村庄被封闭，水井被消毒，病人被抬进帐篷医院。超过一万名埃及人死亡。在巴格达，年轻诗人纳齐克·梅拉伊卡（نازك الملائكة）听到这些数字，写下了她的诗《霍乱》（الكوليرا），用一种全新的自由节奏，步履如同运尸的灵车。",
  "egyptians-late:birth": "婴儿出生后第七天，埃及家庭会举行「苏布厄」（سبوع）。婴儿被放在筛子里轻轻摇晃，母亲从婴儿身上跨过七次，一位老妇人敲击黄铜研钵，好让孩子将来不惧怕声响，孩子们则举着蜡烛穿过屋子，为新生儿唱歌。想象：约1900年，在塔马伊·扎哈伊拉（طماي الزهايرة），村里的伊玛目为女儿乌姆·库勒苏姆（أم كلثوم）举办这样的庆宴，却不知道她的歌声将会成就什么。",
  "egyptians-late:wedding": "「扎法」（زفة）护送新郎新娘穿过街道前往新家：鼓手敲着塔布尔鼓和里克手鼓，米兹玛尔唢呐齐鸣，妇女们发出颤音欢呼「扎加里特」（زغاريد），一位舞者头顶点燃的烛台起舞。这种烛台舞「拉各斯·沙马丹」（رقص الشمعدان）据说由19世纪90年代开罗（القاهرة）的著名舞者沙菲卡·齐卜提亚（شفيقة القبطية）首创。想象：1950年在舒布拉（شبرا），邻居们在巷子上空挂起彩灯，整条街的人都跟着游行队伍走。",
  "egyptians-late:death": "1975年2月5日，开罗（القاهرة）安葬了乌姆·库勒苏姆（أم كلثوم）。数百万人涌上街头，人群从官方送葬队伍中接过她的灵柩，扛在肩上在城中走了好几个小时，一直抬到她生前钟爱的侯赛因（الحسين）清真寺，然后才让灵柩前往墓地。电台整日播放她的歌。整个阿拉伯世界的人们都说，一个时代的声音沉寂了。",
  "mayans-late:hunt": "在许多高原城镇，守护圣人节上至今仍会跳「鹿舞」（Baile del Venado）：猎人带着猎犬，和老人们一起，随着马林巴琴或笛与鼓的伴奏，追踪戴着鹿面具、披着鹿皮的舞者，直到鹿被捉住。这支舞记住了古老狩猎的一条规矩：猎人进入森林之前，要向山神请求许可，每猎取一只动物，都要献上柯巴脂和蜡烛。",
  "mayans-late:battle": "每年一月，在拉维纳尔的圣保罗节上，阿奇玛雅人会演出《拉维纳尔武士》（Xajoj Tun），这是一部用基切语演出的舞剧，讲述西班牙人到来之前两个王国之间的战争。被俘的武士基切·阿奇与英雄拉维纳尔·阿奇相对而立，在通鼓（tun，裂缝鼓）缓慢的节拍和长号角声中，展开一场漫长的豪言对决。1850年，拉维纳尔的长老巴托洛·西斯把台词记录下来，使其不致失传。",
  "mayans-late:siege": "《卡克奇克尔年鉴》（又称《哈希尔编年史》）记载了1524年以后的岁月：卡克奇克尔人离开了他们的城市伊希姆切，躲进深山和森林。他们在隐秘之处生活了多年，缺衣少食，拒绝缴纳沉重的贡赋。作者弗朗西斯科·埃尔南德斯·阿拉纳和后来的弗朗西斯科·迪亚斯用卡克奇克尔语把这一切写下来，好让子孙知道。想象：一家人躲在松树下，磨着最后一点玉米，侧耳倾听小路上是否有陌生人走来。",
  "mayans-late:triumph": "波士顿，1952年4月19日。来自安提瓜附近旧城（Ciudad Vieja）的卡克奇克尔跑者多罗特奥·瓜穆奇·弗洛雷斯，从小在山路上背运货物长大，赢得了波士顿马拉松。回到家乡，他受到了人山人海的欢迎，后来危地马拉城的国家体育场以他的另一个名字「马特奥·弗洛雷斯」命名。想象：在他的家乡，马林巴琴彻夜演奏，孩子们在鹅卵石街道上来回赛跑，假装自己就是他。",
  "mayans-late:gather": "每逢周四和周日，基切人的小城奇奇卡斯特南戈（Chuwi'la）就变成一个巨大的集市。天亮之前，各家各户从小村落步行而来，背着玉米、豆子、辣椒、陶罐、鲜花和织好的惠皮尔上衣，在白色的圣托马斯教堂周围支起遮篷。讨价还价的声音用基切语和西班牙语此起彼伏，柯巴脂的烟从教堂台阶上飘下来，不知何处正响着马林巴琴。",
  "mayans-late:build": "约1545年，多明我会修士在奇奇卡斯特南戈（Chuwi'la）一座前西班牙时期的平台上建起了圣托马斯教堂，由基切劳工搬运石料。据说它的十八级台阶代表古老历法的十八个月，至今仍有守日人在台阶上焚烧柯巴脂。约1702年，教区神父弗朗西斯科·希门尼斯在这里看到了一部基切语书籍，并把它抄录下来：这就是《波波尔·乌》（Popol Wuj），人民之书。",
  "mayans-late:festival": "每年12月13日至21日，奇奇卡斯特南戈（Chuwi'la）庆祝其守护圣人圣托马斯。各个宗教兄弟会（cofradía）在柯巴脂的烟雾中抬着圣像穿街而过，奇里米亚管（chirimía）和鼓在游行队伍前开道，广场上马林巴琴声不断。戴面具的舞者跳起「征服之舞」，鞭炮炸响，人们竖起一根高高的「飞人柱」（palo volador），两名腰系绳索的年轻人从柱顶旋转着降落到地面。",
  "mayans-late:games": "每年11月1日，在马姆人的小镇托多斯桑托斯库丘马坦，骑手们穿着红条纹长裤、系着彩带，在山坡上一段短短的赛道上来回疾驰，一遍又一遍，从早上一直跑到天色将晚。这场赛马没有赢家，只看谁能一直留在马背上。马林巴琴整日演奏，家人们在山坡上欢呼，到了晚上，全镇的人前往墓地缅怀逝者。",
  "mayans-late:ritual": "在莫莫斯特南戈，每隔260天，基切人的神圣历法就会回到它的起始之日「瓦哈基卜·巴茨」（Wajxaqib' B'atz'，八·线）。守日人（ajq'ijab'）聚集在帕克洛姆和丘蒂萨巴尔的山顶祭坛，焚烧柯巴脂和蜡烛，献上鲜花、糖和酒。他们用齐泰树（tz'ite）的种子推算历法中的日子，解答人们的疑问：一桩婚姻是否美满，一个梦意味着什么，何时该播种。",
  "mayans-late:rain": "在霍科坦附近的乔尔蒂玛雅村庄，旱季结束时要举行祈雨仪式。5月3日十字架节前后，长老和祈雨教父们带着蜡烛、柯巴脂和火鸡的血来到泉边，祈求水中的蛇灵把雨水降到山岭之上。想象：随后全村等待着，凝望山上的天空，直到第一颗沉重的雨滴砸在铁皮屋顶上。",
  "mayans-late:drought": "2001年，危地马拉东部的干旱走廊雨季失约。在霍科坦和卡莫坦的乔尔蒂玛雅村庄，玉米枯萎，咖啡收获季也没带来多少活计，在救援到来之前，已有数十名儿童死于饥饿。想象：一位母亲背着最小的孩子走了好几个小时去卫生站，而在家里，她的丈夫望着龟裂的田地，犹豫是该再种一次，还是离家去找活干。",
  "mayans-late:flood": "2005年10月5日，在飓风「斯坦」带来的暴雨中，一股泥石流从帕纳巴赫上方的火山上崩泻而下。帕纳巴赫是圣地亚哥阿蒂特兰的一个楚图希尔玛雅街区，泥石掩埋了正在熟睡的家家户户，数百人罹难。邻居们用铁锹和双手挖了好几天，那些找不到的遇难者就被留在原地安息，那片地方被宣布为墓地。小镇在更高的山坡上重建。",
  "mayans-late:wind": "在阿蒂特兰湖上，每到正午前后，「索科米尔」（xocomil）便会刮起：这是一阵突如其来的风，据说它在卡克奇克尔语中的意思是「带走罪孽的风」。几分钟之内，它就能把平静的蓝色湖水掀起陡峭的浪头。楚图希尔和卡克奇克尔渔民驾着木制独木舟（cayuco），熟知它来临的时辰，总在它到来之前划向岸边。想象：一天下午它来得早了，父子俩奋力划桨，唱着歌合着节拍，直到独木舟搁浅在圣地亚哥阿蒂特兰的芦苇丛中。",
  "mayans-late:quake": "1976年2月4日凌晨3点01分，大地震撼危地马拉约四十秒。在卡克奇克尔人的城镇特克潘、科马拉帕和帕齐西亚，沉重的土坯房屋和教堂倒塌，压在熟睡的家人身上，全国约有23,000人遇难。黎明时分，幸存者在瓦砾中挖掘，埋葬亲人，在寒冷中睡在塑料布下。随后他们用木头和更轻的屋顶重建家园，在第一个节日里，马林巴琴又响了起来。",
  "mayans-late:winter": "十二月和一月，霜冻（heladas）降临托托尼卡潘和莫莫斯特南戈周围海拔2,500米以上的基切高原城镇。清晨的玉米地一片白，水罐里结了一层薄冰。莫莫斯特南戈的羊毛毯向来闻名，它们用脚踏织机织成，在温泉中洗涤。想象：一家人裹着这样的毯子，紧挨着火塘入睡，早上再到「图赫」（tuj）汗蒸浴的蒸汽里取暖。",
  "mayans-late:birth": "想象：在一个基切村庄，一位接生婆（iyom）整夜陪着年轻的母亲，祈祷着，按摩她的腹部。婴儿降生后，脐带被剪下埋在火塘边，好让孩子永远记得回家。产后，母亲和孩子在「图赫」（tuj）汗蒸浴中取暖。然后一家人去拜访守日人，守日人在260天的历法中解读孩子出生之日的「纳瓦尔」（nawal），说出孩子将来会成为怎样的人。",
  "mayans-late:wedding": "在高原地区，婚姻从提亲开始。新郎的父母带着一位替他们说话的长老，几次三番登门拜访新娘家，带去面包、巧克力和酒，直到新娘的父亲点头。想象：在一个基切小镇的婚礼当天，教堂仪式之后，两家人在院子里吃玉米粽和火鸡，马林巴琴一连几个小时演奏「颂」（son）曲，新人——新娘穿着崭新的惠皮尔上衣——与他们的教父母一同起舞。",
  "mayans-late:death": "每年11月1日，卡克奇克尔小镇圣地亚哥萨卡特佩克斯会在墓地里放飞巨型风筝（barriletes），有些宽达十米以上，由一群群年轻人花数月时间用薄纸和竹子扎成。各家用鲜花装点坟墓，与逝去的亲人分享一餐，许多人说风筝会把讯息带给天上的灵魂。傍晚风停时，风筝落下，马林巴琴奏起逝者生前最爱的「颂」曲。",
  "incas-late:hunt": "在阿普里马克高山村庄七月的「血之节」（Yawar Fiesta）上，男人们攀上山峰去捕捉一只神鹰（kuntur）。他们藏身于用树枝盖住的坑里，上面放一具动物尸体作诱饵，一等就是好几个小时；当巨鸟落下时，他们便抓住它的双腿。何塞·玛丽亚·阿格达斯在1941年的小说中描写过这一节日。神鹰被绑在广场上一头公牛的背上，之后再放归山林。",
  "incas-late:battle": "每年12月25日，在库斯科（Qusqu）附近的丘姆比维尔卡斯省，人们以「塔卡纳库伊」（Takanakuy）——也就是拳斗——来了结一年的纷争。男男女女戴着面具、穿着戏装走进圈子，伴着小提琴和曼陀林唱起「瓦伊利亚斯」（waylliya），然后在一位手持鞭子的裁判注视下，与对手一一交锋。打斗结束后，双方相拥，纷争便随着这一年一同了结。",
  "incas-late:siege": "在帕乌卡尔坦博的高山河谷中，克罗人（Q'ero）世代居住在远高于庄园的地方，放牧美洲驼和羊驼，把古老的印加图案织进斗篷，保存着在别处早已消失的歌谣和献给群山的祭品。1955年，奥斯卡·努涅斯·德尔普拉多率领的考察队登上他们的村庄，大为惊叹。想象：一场冬季暴风雪中，各家聚在石屋里，把美洲驼留在身边，向山神（apu）歌唱，直到雪停。",
  "incas-late:triumph": "在「星雪节」（Qoyllur Rit'i，Quyllur Rit'i）最后一天的黎明，熊人「乌库库」（ukuku）身穿毛茸茸的服装，从科尔克普恩库山的冰川上走下来。他们在冰上度过了一夜；世世代代，他们都会把冰块背下山，作为家乡村庄的圣水，但随着冰川退缩，这一习俗已经停止。山下，成千上万的朝圣者用笛子、鼓和歌声迎接他们，各村的舞蹈队让整个山谷充满音乐。",
  "incas-late:gather": "四五月间，库斯科（Qusqu）周围的山坡上开始收获土豆。各家以「艾尼」（ayni）的方式轮流互助，挖出几十个品种的红色、紫色和黄色土豆。想象：中午他们停下来做「瓦提亚」（wathiya），在田里用土块垒成小窑加热烤土豆，年轻人伴着恰朗戈琴唱起瓦伊诺（huayno），姑娘们与小伙子们一句一句对唱，而老妇人们把收成分拣成堆。",
  "incas-late:voyage": "从20世纪50年代起，数十万克丘亚家庭离开大山前往利马，乘坐卡车和巴士沿安第斯山而下，来到雾气笼罩的海岸。在不断扩张的街区里，他们按家乡村庄组建了同乡会。每逢星期天下午，他们挤满了「科利塞奥」（coliseo）剧场，聆听瓦伊诺歌手演唱，比如「瓦斯卡兰的金翅雀」（埃内斯托·桑切斯·法哈多）和「瓦拉斯的小牧女」（玛丽亚·阿尔瓦拉多·特鲁希略），听着那些唱给远方故乡的歌而落泪。",
  "incas-late:festival": "1944年6月24日，库斯科（Qusqu）的人们聚集在萨克塞瓦曼（Saksaywaman），观看重新上演的「太阳节」（Inti Raymi）。这一节日由作家福斯蒂诺·埃斯皮诺萨·纳瓦罗复兴，他用克丘亚语（Runa Simi）写下了台词。一名扮演印加王的演员向太阳致敬，祭司献上祭品，数百名表演者随着克纳笛、西库排箫和鼓声起舞。如今每年都有数万人前来，整座城市一整周都沉浸在节庆和游行之中。",
  "incas-late:games": "在安第斯山区的狂欢节上，村庄会玩「云萨」（yunza）：在广场上立起一棵树，挂满礼物、水果、气球、毯子和锅。一对对舞伴伴着瓦伊诺和狂欢节歌曲绕树起舞，然后轮流用斧子砍树。树干嘎吱作响时，所有人都屏住呼吸；砍倒大树的那一对欢呼雀跃，并且必须承办来年的云萨。",
  "incas-late:ritual": "相传1780年，一个在奥桑加特山下放牧美洲驼的男孩马里亚诺·迈塔，在冰川上遇到一个神秘的孩子，两人成了朋友。那孩子消失后，人们在一块岩石上发现了一幅基督像。每年基督圣体节之前，数以万计的朝圣者攀登到海拔近4,800米的「星雪」（Qoyllur Rit'i，Quyllur Rit'i）圣所，以舞蹈队的形式连跳数日，祈求山之主的赐福。",
  "incas-late:rain": "八月是大地张开的月份。在安第斯山区的村庄里，各家向大地母亲帕查玛玛献上「向大地付礼」（pago a la tierra，haywarisqa）：把古柯叶、美洲驼脂肪、糖果和谷物包在纸里，在田间焚烧或掩埋。想象：在乌鲁班巴（Willkamayu）河上方的一个村庄，一家人犁地，种下第一批土豆，然后熬过九月干旱的几周，望着群山上空聚集的云，等待雨季来临。",
  "incas-late:drought": "1982年和1983年，一场强烈的厄尔尼诺给的的喀喀湖（Titiqaqa）周围的高原带来干旱。雨水迟迟不来，土豆和藜麦枯萎，成群的羊驼和美洲驼因缺乏牧草而死去。普诺的许多克丘亚和艾马拉家庭下山到城市找活干。想象：一个牧人赶着他最后几只瘦弱的羊驼，从一片干涸的牧场走到另一片，向山神祈求那场迟迟不来的雨。",
  "incas-late:flood": "1626年3月15日，波托西上方卡里卡里湖的堤坝决口，一股夹带泥浆的洪流冲过城里的银矿加工坊和印第安人教区。数千人死亡，其中许多是服「米塔」（mita）劳役的安第斯劳工，他们从遥远的村庄来到这座银山做工。想象：一位幸存的妇女抱着孩子爬上山坡，教区的人们为死者唱起丧歌。",
  "incas-late:wind": "想象：在库斯科（Qusqu）上方的高原草原「普纳」（puna）上，八月的寒风中，一个牧羊姑娘赶着美洲驼穿过开阔的草地回家。风在伊丘草间呼啸，把尘土和冰雹卷过山坡。她裹紧披肩，唱起放牧的歌来安抚牲畜，顶着狂风前行，直到看见自家房子旁的石砌畜栏，母亲正在那里吹着炉火。",
  "incas-late:fire": "想象：在七月的旱季，牧人篝火的一点火星点燃了库斯科（Qusqu）附近山坡上的伊丘草。风迅速把火势沿山坡推向村庄和桉树林。教堂钟声响起，所有人拿着铁锹、树枝和毯子跑去扑火。到了夜里，山坡一片焦黑，村民们分享着奇恰酒和汤，讲述他们如何保住了房屋。",
  "incas-late:thunder": "西班牙人到来后，雷神伊利亚帕换上了圣地亚哥——圣雅各——的面孔，据说他的马蹄声就是雷声。7月25日圣地亚哥节这天，安第斯山区的牧人为他们的牲畜过节，给美洲驼和羊驼系上彩色丝带，并为它们唱歌。被雷击中而活下来的人，被认为是山选中的人，将成为能与山神（apu）交谈的治疗师「帕科」（paqo）。",
  "incas-late:winter": "六七月间，霜冻（qasa）降临高原草原，在海拔四千米以上的地方，夜间气温远低于冰点。普诺和库斯科（Qusqu）羊驼牧场上的牧人会有幼畜冻死。想象：在一间石屋里，一家人盖着羊驼毛毯挤在一起睡觉，小羊驼也被抱进屋里，黎明时父亲敲开溪上的冰，好让牲畜饮水。",
  "incas-late:plague": "1719年和1720年，一场大瘟疫席卷南部安第斯地区，从布宜诺斯艾利斯一直蔓延到库斯科（Qusqu）。编年史家写道，仅库斯科一地就有数千人死亡，整村整村的人去屋空，田地无人收割。神父们带领游行队伍穿过街道，克丘亚家庭日复一日地把死者抬到教堂墓地。想象：在城郊的一个村子里，一个男孩被派去敲教堂的钟，他一直敲到双臂酸痛。",
  "incas-late:birth": "1911年1月18日，何塞·玛丽亚·阿格达斯出生于安达韦拉斯。他幼年丧母，在克丘亚仆人和农民中间长大，他们教会了他自己的语言和歌谣。他后来成为作家和瓦伊诺歌谣的收集者，让安第斯在文学中发出了声音。想象：在安达韦拉斯的一所房子里，一位克丘亚妇女用克丘亚语轻声唱歌，哄着新生儿安静下来。",
  "incas-late:wedding": "想象：在一个克丘亚村庄，教堂婚礼之后，新郎新娘走向他们教父母的家，身后跟着用竖琴、小提琴和克纳笛演奏瓦伊诺的乐手。两家人送上土豆、一只羊、毯子和硬币作为礼物，教父母把一个十字架放在新人身上。所有人彻夜跳着瓦伊诺舞，老妇人们端上汤和奇恰酒，年轻的新人并肩而坐，有点害羞。",
  "incas-late:death": "1969年12月，何塞·玛丽亚·阿格达斯在利马去世。他生前要求葬礼要有安第斯音乐相伴，他的朋友、来自阿亚库乔的小提琴手马克西莫·达米安，在灵柩被抬过街道时演奏了瓦伊诺和哀歌，身边还有其他安第斯乐手。在安第斯的村庄里，人们同样为逝者歌唱：守灵之夜，家人为他们唱歌奏乐，送他们踏上旅程。",
  "egyptians:showcase": "尼罗河上的音乐比法老还要古老：前王朝时期的象牙响板和彩陶上描绘了随着节拍起舞的场景。古王国的墓葬中可以看到弓形竖琴的演奏者、竖吹笛手，以及用手势指挥乐队的歌手，梅梅特双管（memet）也已出现。新王国从西亚带来了新的声音：长颈鲁特琴、里拉琴和类似双簧管的双簧乐器，而神庙的女歌者则为哈托尔（𓉡）摇动叉铃和梅纳特项链（menat）。图坦卡蒙的两支号角，一支银质、一支青铜，保存至今，仍能吹响。旋律和调音从未被记录下来，因此这首乐曲是一种复原：由梅梅特双管领奏——它的嗡鸣声至今仍活在祖玛拉（zummara）和阿尔古尔（arghul）中——竖琴（benet）应和。",
  "babylonians:showcase": "美索不达米亚音乐从苏美尔诸城传入巴比伦（𒆍𒀭𒊏𒆠），带来了里拉琴、竖琴、管乐器和哀歌祭司。古巴比伦时期，书吏们做了一件新事：泥板上记下了萨穆里拉琴（sammû）九根弦的名称，以及由四度和五度构成的七种调音——伊沙尔图（išartu）、恩布布（embūbu）、皮图（pītu）等，乌尔出土的一块泥板还说明了如何从一种调音转换到另一种。纳鲁（nāru）歌手在宫廷和神庙中演唱，卡卢（kalû）祭司则伴着巨大的青铜利利苏（lilissu）定音鼓唱苏美尔语哀歌，这门技艺一直保持到希腊化时代。泥板只给出了调音而没有旋律，所以本曲中的萨穆里拉琴和恩布布管演奏的是复原。",
  "assyrians:showcase": "亚述音乐源于美索不达米亚共同的里拉琴、竖琴、管乐器和鼓的传统。阿舒尔（𒀸𒋩𒆠）出土的一块中亚述时期泥板按体裁列出了歌曲标题，显示出数量庞大的颂歌和歌曲曲目。最清晰的图景来自新亚述诸王宫殿的浮雕：在尼尼微（𒌷𒉌𒉡𒀀），竖琴手用拨子弹奏水平的角形竖琴，或徒手弹奏立式竖琴，吹管手和鼓手随军行进；一幅著名的浮雕描绘了埃兰乐师手持竖琴、双管和鼓，后面跟着拍手唱歌的妇女和儿童。旋律本身已经失传；本曲以角形竖琴和双管领奏，阿达普（adapu）框鼓伴奏，是一种复原。",
  "sumerians:showcase": "苏美尔音乐是我们能看到的最古老的音乐之一。约公元前2500年，在乌尔（𒋀𒀊𒆠）的王陵中，饰有金牛头的里拉琴、普阿比王后的乐器和一对银管与它们的主人一同下葬，「乌尔军旗」上也描绘了宴会上的里拉琴手和歌手。颂歌赞美舒尔吉王（𒀭𒂄𒄀）精通多种乐器。加拉（gala）祭司用埃梅萨尔方言伴着巴拉格（balag）和利利斯（lilis）鼓唱哀歌，哀悼被毁的城市，这些哀歌在苏美尔口语消亡后，又以苏美尔语被抄写和传唱了约两千年。没有任何苏美尔旋律流传下来，所以这里的牛头里拉琴、银管和鼓演奏的是复原。",
  "hittites:showcase": "在哈图沙（𒌷𒄩𒀜𒌅𒊭），节庆文献中处处是音乐：歌手常被冠以苏美尔头衔LÚ.NAR，用哈梯语、卢维语和胡里语歌唱，伴奏有齐纳尔里拉琴（zinar）、大型洪齐纳尔里拉琴（hunzinar）、阿尔卡米鼓（arkammi）和加尔加尔图里（galgalturi）。泥板上写明了谁演奏、谁拍手、鼓何时响起，却没有曲调。约公元前17世纪的伊纳恩迪克陶瓶描绘了一整支神庙乐队，有鲁特琴、里拉琴和钹；阿拉贾许于克的一幅浮雕则描绘了杂技演员身旁的鲁特琴手。哈图沙沉寂之后，卡尔凯美什等后来城市的石浮雕上仍可见鼓手和号手。旋律已经失传，所以这里的长颈鲁特琴和齐纳尔琴演奏的是复原。",
  "phoenicians:showcase": "在黎凡特沿岸，音乐服务于神庙、宴会和丧礼。基诺尔里拉琴（𐤊𐤍𐤓）是这一地区一千多年间的弦乐器。附近的乌加里特在约公元前1400年留下了保存最完整的最古老记谱歌曲——一首胡里语颂歌，附有用「尼德卡布利」（nīd qabli）调音演奏九弦里拉琴的说明。腓尼基的青铜和银碗上描绘了手持双管、里拉琴和框鼓的妇女游行队伍，许多陶俑表现了手持托夫鼓（𐤕𐤐）的妇女。希腊作家知道一种腓尼基小管，名为金格拉斯（gingras），用于阿多尼斯的哀悼仪式。腓尼基歌曲本身从未被记录下来，所以这里的基诺尔琴和哈利尔管（halil）演奏的是复原。",
  "palmyrans:showcase": "帕尔米拉（𐡶𐡣𐡬𐡴）是商队路线上的一片绿洲，地处希腊罗马地中海与美索不达米亚两个音乐世界之间。我们所知的大部分来自石刻：墓葬浮雕和宴饮场景描绘了双管、里拉琴和框鼓；城中诸神的祭司举行仪式宴会，宴会所用的陶筹至今尚存。他们的歌很可能用城中铭文所用的阿拉米语演唱，但帕尔米拉音乐没有一个音符保存下来。罗马东方的托勒密的乐理描述了中立的四分之三音音程，因此本曲借用了类似巴亚提（bayati）的色彩，以双管、里拉琴和长颈鲁特琴在达夫框鼓（duff）上演奏，作为一种复原。",
  "minoans:showcase": "青铜时代的克里特岛留下了音乐的图像，却没有留下音符。阿吉亚特里亚达（Αγία Τριάδα）出土的「收割者瓶」描绘了男人们跟在一位叉铃手身后边走边唱，同一遗址出土的彩绘石棺上则描绘了祭祀中的七弦里拉琴手和双管吹奏者。在神龛中发现、在印章上描绘的法螺被当作号角吹奏。后来占据克诺索斯（𐀒𐀜𐀰）的迈锡尼希腊人也使用这种乐器：皮洛斯出土的线形文字B泥板列有里拉琴手，皮洛斯的一幅壁画描绘了坐在岩石上的里拉琴手。里拉琴从这些宫殿传入了后来的希腊音乐。米诺斯的曲调已不可知，所以这里的里拉琴和双管用古风时期的斯彭代昂音阶（spondeion）演奏一种复原。",
  "greeks:showcase": "希腊音乐植根于克里特和迈锡尼的青铜时代里拉琴；荷马笔下的歌手用福尔明克斯琴（phorminx）伴唱史诗。古风时期，基萨拉琴（κιθάρα）和阿夫洛斯管（αὐλός，一对簧管）成为重要的音乐会乐器，德尔斐（Δελφοί）的皮提亚竞技会上设有音乐比赛，每个节日都有合唱歌曲。毕达哥拉斯学派把音程与数联系起来，亚里士多塞诺斯描述了调式以及自然、半音和四分音三种音类。在希腊化时代的亚历山大，克特西比乌斯发明了水压风琴（hydraulis），这是最早的管风琴。约六十份记谱残篇保存至今，包括德尔斐颂歌和刻在墓碑上的塞基洛斯之歌。他们的乐理传到罗马，并经罗马传入中世纪欧洲；本曲由基萨拉琴和阿夫洛斯管领奏。",
  "athenians:showcase": "雅典的音乐活在三个地方。在会饮中，宾客们传递里拉琴，唱着名为「斯科利昂」（skolia）的饮酒歌，瓶画家描绘了阿那克里翁抒情诗中长臂的巴尔比托斯琴（βάρβιτος）。在泛雅典娜节（Παναθήναια）上，职业基萨拉弹唱者、阿夫洛斯管乐手和歌手在伯里克利的音乐厅里竞逐奖品。在狄俄尼索斯剧场，悲剧合唱队随着一支阿夫洛斯管载歌载舞，五十人的酒神颂合唱队按部落竞赛。公元前5世纪末，提谟忒俄斯和欧里庇得斯的「新音乐」增添了半音色彩和炫技独奏，令柏拉图大为不满。一份纸草残片保存了欧里庇得斯《俄瑞斯忒斯》的乐谱；这里的巴尔比托斯琴、里拉琴和阿夫洛斯管演奏的是复原。",
  "spartans:showcase": "早期的斯巴达是希腊的音乐中心之一。据说发明了七弦里拉琴的莱斯博斯人特潘德罗斯，赢得了卡尔涅亚节（Κάρνεια）上的第一场音乐比赛；阿尔克曼为少女合唱队写下了「少女之歌」（partheneia），其残篇流传至今。提尔泰奥斯的战争哀歌在出征时被传唱；在裸体青年节（Gymnopaidiai）上，赤身的少年和男子在盛夏的炎热中歌舞。修昔底德描述了方阵如何随着众多阿夫洛斯管乐手的乐声踏步缓缓前进，军队在战前高唱凯歌（paean）。后来的作家讲述，监察官曾剪掉一把弦数过多的里拉琴上的琴弦，这是音乐保守主义的象征。旋律已经失传，所以这里的阿夫洛斯管和福尔明克斯琴演奏的是复原。",
  "macedonians:showcase": "马其顿宫廷把希腊世界的音乐家吸引到了北方。阿基劳斯国王接待了欧里庇得斯，后者最后的几部悲剧就写于此地，据说诗人兼音乐家提谟忒俄斯也曾到访。腓力和亚历山大（Ἀλέξανδρος）出征时都带着音乐家，有个故事讲道，阿夫洛斯管乐手提谟忒俄斯把激昂的「高调诺莫斯」（orthios nomos）吹得如此动人，亚历山大竟一跃而起去抓武器。军队高唱凯歌，并随萨尔平克斯号（salpinx）的信号行进。亚历山大之后，托勒密王朝使亚历山大城成为音乐之都：克特西比乌斯在那里制造了水压风琴，盛大的王家游行有合唱队和吹管手随行。旋律已经失传，所以这里的萨尔平克斯号和弗里吉亚阿夫洛斯管演奏的是复原。",
  "romans:showcase": "早期罗马音乐大多经由伊特鲁里亚人传入：每一场献祭都有蒂比亚（tibia，双管）乐手伴奏；公元前311年，他们的行会举行了一场著名的罢工，离开罗马城，直到被人哄劝回来。罗马军团使用青铜铜管乐器：长直的图巴号（tuba）、弯曲的科尔努号（cornu）、布奇纳号（buccina）和利图斯号（lituus），这些都见于出土文物和浮雕。随着罗马吸收希腊世界，希腊的基萨拉弹唱者、哑剧和乐理也随之而来；尼禄本人就曾作为基萨拉弹唱者参加比赛。水压风琴在竞技场中演奏，兹利坦镶嵌画上就有描绘，阿昆库姆还出土了一架3世纪的管风琴。后来波爱修斯把希腊乐理带入了中世纪欧洲。没有罗马旋律流传下来，所以这里的科尔努号、图巴号和水压风琴演奏的是复原。",
  "carthaginians:showcase": "迦太基（𐤒𐤓𐤕𐤇𐤃𐤔𐤕）把腓尼基的音乐带到了西地中海。布匿圣所和墓葬中的陶俑描绘了把托夫框鼓（tof）抵在肩头的妇女和吹奏双管的男子，小型青铜铃和钹被放入坟墓。类似黎凡特基诺尔琴（kinnor）和内维尔琴（nevel）的里拉琴和竖琴在宴会和神庙仪式中演奏。布匿典籍没有流传到古代之后，就我们所知，也从未有布匿旋律或调音被记录下来。本曲中的双管、基诺尔琴和托夫鼓以借用的巴比伦调音演奏一种复原。",
  "egyptians-late:showcase": "法老时代之后，尼罗河谷先用希腊语歌唱，后来是科普特教会圣咏，从7世纪起则用阿拉伯语，乌德琴（عود）、卡龙琴（قانون）、奈伊笛（ناي）和木卡姆（maqam）调式体系在此扎根。在中世纪的开罗（القاهرة），宫廷歌手和以奈伊笛与框鼓伴奏的苏非派齐克尔（ذكر）圈子塑造了一种持久的风格。19世纪，由乌德琴、卡龙琴、奈伊笛、小提琴和里克手鼓（رق）组成的小型乐团「塔赫特」（takht）为阿卜杜·哈穆利（عبده الحامولي）等歌手伴奏，赛义德·达尔维什（سيد درويش）带来了大众戏剧歌曲。广播和电影使乌姆·库勒苏姆（أم كلثوم）和穆罕默德·阿卜杜·瓦哈卜成为明星，他们与大型「菲尔卡」（فرقة）乐团同台演唱。塔拉布（طرب）——听者的狂喜——至今仍是音乐追求的境界；本曲由乌德琴领奏。",
  "aztecs:showcase": "早在墨西加人（Mēxihcah）之前，中美洲音乐就已十分古老：数千年来的墓葬中都有陶哨、笛子和摇响器，特奥蒂瓦坎也曾响起海螺号。在特诺奇蒂特兰（Tenōchtitlan），每个年轻人都要进入「歌之屋」（cuicacalli），每晚在那里学习随着立式韦韦特尔鼓（huēhuētl）和双音特波纳斯特利裂缝鼓（teponāztli）唱歌跳舞。歌是神圣而富有诗意的：特斯科科的内萨瓦尔科约特尔（Nezahualcoyōtl）被人们铭记为诗人国王，16世纪的《墨西哥歌集》（Cantares Mexicanos）保存了附有特波纳斯特利鼓点音节的歌词。特拉特洛尔科出土了一只骷髅形的「死亡哨」。纳瓦村庄至今仍保存着雕花的特波纳斯特利鼓，墨西加舞蹈团体今天仍在演奏韦韦特尔鼓、海螺号和种子摇响器。这里的笛子和鼓是一种复原。",
  "mayans:showcase": "我们对玛雅音乐的了解来自陶器和彩绘。烧制的陶哨和陶笛在许多遗址都有发现，其中很多做成人偶形状，比如海纳岛墓葬中出土的那些。古典期的彩绘陶瓶描绘了宫廷中的鼓、摇响器和号角；约790年绘制的博南帕克壁画描绘了一支乐师游行队伍，有长木号、立式鼓、用鹿角敲击的龟甲和摇响器。在《波波尔·乌》（Popol Wuj）中，胡恩·巴茨和胡恩·绰文兄弟是吹笛手和歌手，是艺术的守护者。铜铃被投入奇琴伊察（Chi'ch'e'n Itsa'）的圣井。没有古典期的旋律流传下来，所以这里的陶笛、通库尔鼓（tunk'ul）和帕什鼓（pax）演奏的是复原。",
  "mayans-late:showcase": "16世纪以后，高原上的玛雅城镇将新旧融为一体。通鼓（tun，裂缝鼓）和长号角在《拉维纳尔武士》（Xajoj Tun）中继续鸣响，这部舞剧在19世纪50年代首次被记录下来，至今仍在上演。教会音乐带来了奇里米亚唢呐（chirimía），它与鼓一起在宗教兄弟会为守护圣人举行的游行中开道。马林巴琴带有葫芦共鸣器，其上的薄膜会嗡嗡作响，它出现在殖民时期的记录中，很可能在很大程度上源于非洲木琴；玛雅人把它变成了自己的乐器，在凯克奇语中称之为k'ojom。19世纪90年代前后，人们制造出了大型半音「双排马林巴」（marimba doble），由几位乐手同时演奏。如今每个节日都有马林巴琴，而古老的自然音阶葫芦马林巴（marimba de tecomates）仍为本曲领奏。",
  "incas:showcase": "安第斯音乐非常古老：约公元前2000年，卡拉尔就有人用神鹰和鹈鹕的骨头制作笛子；刻有图案的海螺号「普图图」（pututu）被存放在查文德万塔尔的地下廊道中；纳斯卡人制作了音准精良的陶制安塔拉排箫（antara）。在印加时代，音乐与农事年历以及库斯科（Qusqu）「太阳节」（Inti Raymi）等国家盛大节庆紧密相连。编年史家描述了「塔基」（taki）歌舞、妇女们唱的「哈拉维」（harawi）、名为「万卡尔」（wankar）的鼓，以及用来向情人求爱的笛子。西库排箫（siku）被分成两半，由两个人交替吹奏，这种演奏方式沿用至今。印加旋律从未被记谱，所以这首由克纳笛（qina）领奏的乐曲是一种复原。",
  "incas-late:showcase": "16世纪以后，安第斯音乐家接受了从西班牙传来的竖琴、小提琴和吉他，并把它们与克纳笛、西库排箫和鼓融合在一起。小小的恰朗戈琴（charango）出现于殖民时期，过去曾用犰狳壳制作。古老的哈拉维演变成了缓慢哀伤的「亚拉维」（yaraví）歌曲，而瓦伊诺（wayno）——一种二拍子的欢快舞曲——成为该地区流传最广的形式。牧人们吹奏「瓦克拉普库」（waqra phuku），一种用牛角制成的号角。20世纪，唱片和广播把瓦伊诺歌手带进了城市，城市乐团复兴了西库排箫乐队。如今剪刀舞者随着竖琴和小提琴起舞，在本曲中，克纳笛在恰朗戈琴、西库排箫和邦博鼓（bombo）之上领奏。",
  "haudenosaunee:showcase": "豪德诺索尼人（Rotinonhsión:ni）的音乐世世代代在长屋中口耳相传。仪式歌曲属于一年的节令循环，从仲冬到青玉米节和丰收节；用鳄龟壳制成的龟壳摇响器为「大羽舞」伴奏，令人想起那只托起大地的乌龟。约从1800年起，「美湖」（Handsome Lake）的教诲塑造了延续至今的长屋仪式。社交舞由一位手持小水鼓的歌手领唱——水鼓是把兽皮绷在部分盛水的容器上——另一位搭档摇着牛角摇响器；舞者们应和。烟舞、鱼舞和女子的拖步舞（Shuffle Dance）至今仍在社交聚会上传唱，新的歌曲也不断被创作出来。",
  "lakota:showcase": "拉科塔人（Lakȟóta）的音乐在大平原上围绕人声和鼓发展起来。歌曲得自异象，归各个社团所有，或为荣誉、战争、疗愈和哀悼而作。年轻男子用「西约坦卡」（siyótȟaŋka）求爱，这是一种雪松木笛，在姑娘的帐篷附近独自吹奏。在太阳舞（Wiwáŋyaŋg Wačhípi）上，舞者吹着鹰骨哨，歌手们击鼓。19世纪，草舞及其歌曲从邻近民族传播过来；约1911年至1914年，弗朗西丝·登斯莫尔用蜡筒录下了数百首拉科塔歌曲。如今在「瓦奇皮」（wačhípi）聚会上，歌手们围坐在一面大鼓（čhaŋčhéga）旁，领唱者以高音起头，其他人随后加入，妇女们则加上颤动的「利利利」（lililí）呼声。木笛自20世纪后期以来得到了复兴。",
  "americans:showcase": "美国民间音乐有多重根源。来自不列颠群岛的移民带来了小提琴曲和叙事歌；班卓琴源于被奴役的非洲人制作的葫芦鲁特琴，19世纪40年代成为流行的舞台乐器。18世纪的歌唱学校，以威廉·比林斯等作曲家为代表，催生了《神圣竖琴》（The Sacred Harp，1844年）等形状音符赞美诗集，人们围成空心方阵分四个声部演唱。横笛与鼓乐队列队行进，到19世纪后期，每个城镇都想拥有一支短号乐队。20世纪20年代，唱片传播了老式小提琴和班卓琴音乐；40年代，比尔·门罗的乐队以曼陀林的震音塑造了蓝草音乐。小提琴手大会和《神圣竖琴》歌唱聚会至今仍在举行；本曲由小提琴领奏。",
  "mexicans:showcase": "墨西哥西部的音乐历史悠久：哈利斯科竖井墓中出土的约两千年前的陶俑，描绘了手持鼓、刮响器和摇响器的乐师。殖民时代，传教区和城镇开始使用小提琴、竖琴和吉他，当地乐手创造了新的乐器形式，如比韦拉琴（vihuela）和低音深沉的吉他龙（guitarrón）。「马里亚奇」（mariachi）一词最早见于19世纪50年代的文字记载，指的是在节庆上演奏「颂」曲的弦乐队，用竖琴、小提琴和比韦拉琴。特卡利特兰的巴尔加斯马里亚奇乐队成立于1897年。20世纪30至40年代，广播和电影使马里亚奇声名远扬，小号加入其中，吉他龙取代大竖琴（arpa grande）担任低音。如今马里亚奇在世界各地演奏；本曲由小提琴和小号领奏。",
  "mapuche:showcase": "马普切音乐是仪式、疗愈和土地的音乐。治疗师「马奇」（machi）敲击「库尔特伦」（kultrun）——一种木制或葫芦制的鼓，鼓皮上画着世界的地图——在为病人治疗时歌唱。16和17世纪的西班牙编年史家就已描述过马普切人的号角、角号、哨子和鼓。「特鲁特鲁卡」（trutruka）是一根缠着肠线的长科利韦竹管，其牛角喇叭口是接触欧洲人之后才添加的，它与「皮菲尔卡」（pifilka）哨笛和「库尔库尔」（kull kull）角号一同鸣响。在盛大的社群祈祷「恩吉利亚通」（ngillatun）上，人们伴着特鲁特鲁卡、皮菲尔卡、库尔特伦和卡斯卡维亚铃（kaskawilla）跳「普伦」（purrun）舞，妇女们唱起「塔尤尔」（tayül），即家族世系之歌。这些歌曲至今仍在传唱和演奏。",
  "muisca:showcase": "我们对穆伊斯卡音乐的了解主要来自考古和16、17世纪的西班牙编年史家。在波哥大（Bacatá）和通哈（Hunza）周围的高原上，出土了陶笛、陶埙和哨子。编年史家描述了节庆、游行以及在瓜塔维塔湖举行的献祭仪式——这正是「黄金国」（El Dorado）传说的起源——仪式上有用葫芦或贝壳制成的「福图托」号（fotuto）、笛子，以及伴随舞蹈的长篇吟唱。穆伊斯卡语（muysccubun）在殖民时期逐渐消亡，歌谣也随之消逝；没有任何旋律被记录下来。高原村庄至今仍吹奏「卡帕多尔」（capador）等排箫，本曲以卡帕多尔排箫领奏，配以陶笛和福图托号，是一种复原。",
  "tupi:showcase": "我们对图皮南巴音乐的了解来自16世纪50年代的欧洲访客。汉斯·施塔登描述了「马拉卡」（maracá），一种装满种子的葫芦摇响器，巫师「帕热」（pajé）把它视为神灵的声音。让·德莱里在1557年和1558年与图皮南巴人共同生活，他听到男人们在一座大屋里围成圈子边唱边跳，妇女们应和；在他1578年出版的书中，他记下了几段他们的旋律，这是美洲最早被记谱的歌曲之一。他还描述了骨笛和后来被称为「伊努比亚」（inúbia）的战争号角。莱里记下的曲调后来被维拉-罗伯斯等作曲家所采用。马拉卡至今在图皮-瓜拉尼民族中仍是神圣之物；本曲由骨笛领奏，是一种复原。",
});
